INSERT INTO public.questions (subject_tag, subtopic_tag, question_text, option_a, option_b, option_c, option_d, correct_option, explanation) VALUES ('node_0', 'General', 'राज्यसभेच्या सदस्याचा कार्यकाळ किती वर्षांचा असतो?', '५ वर्षे', '६ वर्षे', '४ वर्षे', 'कायमस्वरूपी', 'B', 'राज्यसभा हे स्थायी सभागृह असले तरी तिच्या प्रत्येक सदस्याची मुदत ६ वर्षांची असते.');
INSERT INTO public.questions (subject_tag, subtopic_tag, question_text, option_a, option_b, option_c, option_d, correct_option, explanation) VALUES ('node_0', 'General', 'अनिल चे वय ५ वर्षांपूर्वी १० वर्षे होते, तर ५ वर्षांनंतर त्याचे वय किती असेल?', '१५ वर्षे', '२० वर्षे', '२५ वर्षे', '३० वर्षे', 'B', 'आजचे वय = १० + ५ = १५ वर्षे. ५ वर्षांनंतरचे वय = १५ + ५ = २० वर्षे.');
INSERT INTO public.questions (subject_tag, subtopic_tag, question_text, option_a, option_b, option_c, option_d, correct_option, explanation) VALUES ('node_0', 'General', '''जसे पेरवाल तसे उगवेल.'' हे वाक्य कोणत्या प्रकारचे आहे?', 'केवल वाक्य', 'संयुक्त वाक्य', 'मिश्र वाक्य', 'प्रश्नार्थी वाक्य', 'C', 'जसे-तसे या संबंधी उभयान्वयी अव्ययाने जोडलेले वाक्य हे मिश्र वाक्य असते.');
INSERT INTO public.questions (subject_tag, subtopic_tag, question_text, option_a, option_b, option_c, option_d, correct_option, explanation) VALUES ('node_0', 'General', 'समीकरण सोडवा: ७x + ५ = ४०, तर x = ?', '४', '५', '६', '७', 'B', '७x = ४० - ५ => ७x = ३५ => x = ३५ / ७ = ५.');
INSERT INTO public.questions (subject_tag, subtopic_tag, question_text, option_a, option_b, option_c, option_d, correct_option, explanation) VALUES ('node_0', 'General', 'महाराष्ट्रातील ''तब्बल ५'' जिल्ह्यांची सीमा स्पर्श करणारा शेजारील राज्य कोणता?', 'गोवा', 'तेलंगणा', 'गुजरात', 'कर्नाटक', 'B', 'महाराष्ट्रातील नांदेड, यवतमाळ, चंद्रपूर, गडचिरोली यांसारख्या जिल्ह्यांच्या सीमा तेलंगणा राज्याला लागून आहेत.');
INSERT INTO public.questions (subject_tag, subtopic_tag, question_text, option_a, option_b, option_c, option_d, correct_option, explanation) VALUES ('node_0', 'General', 'राज्यसभेचे पदसिद्ध अध्यक्ष कोण असतात?', 'राष्ट्रपती', 'उपराष्ट्रपती', 'पंतप्रधान', 'लोकसभा अध्यक्ष', 'B', 'भारताचे उपराष्ट्रपती हे संसदेच्या वरिष्ठ सभागृहाचे (राज्यसभेचे) पदसिद्ध सभापती असतात.');
INSERT INTO public.questions (subject_tag, subtopic_tag, question_text, option_a, option_b, option_c, option_d, correct_option, explanation) VALUES ('node_0', 'General', 'मालिकेतील गहाळ पद शोधा: Z, X, V, T, ?', 'S', 'R', 'Q', 'P', 'B', 'वर्णमालेत मागून एक एक अक्षर सोडून क्रम आहे: Z (-2) X (-2) V (-2) T (-2) R.');
INSERT INTO public.questions (subject_tag, subtopic_tag, question_text, option_a, option_b, option_c, option_d, correct_option, explanation) VALUES ('node_0', 'General', 'भारताचा राष्ट्रीय खेळ कोणता मानला जातो?', 'क्रिकेट', 'हॉकी', 'कबड्डी', 'फुटबॉल', 'B', 'भारताचा ऐतिहासिक क्रीडा वारसा आणि ऑलिम्पिक यशांमुळे ट्रॅडिशनल पातळीवर हॉकीला भारताचा राष्ट्रीय खेळ मानले जाते.');
INSERT INTO public.questions (subject_tag, subtopic_tag, question_text, option_a, option_b, option_c, option_d, correct_option, explanation) VALUES ('node_0', 'General', 'खालीलपैकी कोणती विभक्ती प्रत्ययरहित (प्रत्यय नसलेली) असते?', 'प्रथमा', 'द्वितीया', 'सप्तमी', 'संबोधन', 'A', 'प्रथमा विभक्तीच्या एकवचन किंवा अनेकवचनात कोणतेही प्रत्यय नसतात.');
INSERT INTO public.questions (subject_tag, subtopic_tag, question_text, option_a, option_b, option_c, option_d, correct_option, explanation) VALUES ('node_0', 'General', 'मानवाच्या लाल रक्तपेशींचे (RBC) सरासरी आयुष्य किती दिवसांचे असते?', '६० दिवस', '१२० दिवस', '१८० दिवस', '३०० दिवस', 'B', 'मानवी शरीरातील लाल रक्तपेशींचा जीवनकाळ साधारणपणे १२० दिवसांचा असतो.');
INSERT INTO public.questions (subject_tag, subtopic_tag, question_text, option_a, option_b, option_c, option_d, correct_option, explanation) VALUES ('node_0', 'General', 'विसंगत पद ओळखा: १४४, १६९, १९६, २१०, २२५', '१६९', '१९६', '२१०', '२२५', 'C', '२१० व्यतिरिक्त इतर सर्व संख्या अनुक्रमे १२², १३², १४² आणि १५² या वर्ग संख्या आहेत.');
INSERT INTO public.questions (subject_tag, subtopic_tag, question_text, option_a, option_b, option_c, option_d, correct_option, explanation) VALUES ('node_0', 'General', '''अभिनव भारत'' या क्रांतिकारक संघटनेची स्थापना कोणी केली?', 'लाला लजपत राय', 'विनायक दामोदर सावरकर', 'भगतसिंग', 'चाफेकर बंधू', 'B', 'स्वातंत्र्यवीर विनायक दामोदर सावरकर यांनी १९०४ मध्ये नाशिक येथे ''अभिनव भारत'' या गुप्त क्रांतिकारक संघटनेची स्थापना केली.');
INSERT INTO public.questions (subject_tag, subtopic_tag, question_text, option_a, option_b, option_c, option_d, correct_option, explanation) VALUES ('node_0', 'General', '₹१२०० मुद्दलाचे १०% दराने २ वर्षांचे सरळव्याज किती होईल?', '₹२४०', '₹१२०', '₹२००', '₹२८०', 'A', 'सरळव्याज = (मुद्दल × दर × मुदत) / १०० = (१२०० × १० × २) / १०० = २४० रुपये.');
INSERT INTO public.questions (subject_tag, subtopic_tag, question_text, option_a, option_b, option_c, option_d, correct_option, explanation) VALUES ('node_0', 'General', 'घड्याळात ९:०० वाजता तासकाटा व मिनिटकाटा यांत किती अंशाचा कोन असतो?', '४५°', '९०°', '१२०°', '१८०°', 'B', '९:०० वाजता ९० अंशाचा (काटकोन) असतो.');
INSERT INTO public.questions (subject_tag, subtopic_tag, question_text, option_a, option_b, option_c, option_d, correct_option, explanation) VALUES ('node_0', 'General', '''कमळ'' या शब्दाचा समानार्थी शब्द कोणता?', 'नीरज', 'नग', 'अंबर', 'तरू', 'A', 'नीरज, पंकज, राजीव, सरोज हे सर्व ''कमळ'' या शब्दाचे समानार्थी शब्द आहेत.');
INSERT INTO public.questions (subject_tag, subtopic_tag, question_text, option_a, option_b, option_c, option_d, correct_option, explanation) VALUES ('node_0', 'General', '''तो पेरू खातो.'' या वाक्याचा प्रयोग ओळखा.', 'कर्तरी प्रयोग', 'कर्मणी प्रयोग', 'भावे प्रयोग', 'संकीर्ण प्रयोग', 'A', 'कर्त्याला प्रत्यय नाही आणि क्रियापद कर्त्याच्या लिंग/वचनानुसार बदलते.');
INSERT INTO public.questions (subject_tag, subtopic_tag, question_text, option_a, option_b, option_c, option_d, correct_option, explanation) VALUES ('node_0', 'General', 'अ हा ब पेक्षा मोठा आहे, ब हा क पेक्षा मोठा आहे, तर सर्वात लहान कोण?', 'अ', 'ब', 'क', 'सांगता येत नाही', 'C', 'क्रमानुसार अ > ब > क. त्यामुळे क हा सर्वात लहान आहे.');
INSERT INTO public.questions (subject_tag, subtopic_tag, question_text, option_a, option_b, option_c, option_d, correct_option, explanation) VALUES ('node_0', 'General', '५०० रुपयांच्या मुदलाचे दरसाल दरशेकडा १० दराने २ वर्षांचे सरळव्याज किती होईल?', '₹ ५०', '₹ १००', '₹ १५०', '₹ २००', 'B', 'सरळव्याज = (म × द × क) / १०० = (५०० × १० × २) / १०० = १०० रुपये.');
INSERT INTO public.questions (subject_tag, subtopic_tag, question_text, option_a, option_b, option_c, option_d, correct_option, explanation) VALUES ('node_0', 'General', 'मराठी वृत्तपत्रांचे जनक कोणाला मानले जाते?', 'बाळशास्त्री जांभेकर', 'लोकमान्य टिळक', 'गोपाळ गणेश आगरकर', 'भाऊ महाजन', 'A', '६ जानेवारी १८३२ रोजी ''दर्पण'' हे पहिले मराठी वृत्तपत्र सुरू केल्यामुळे बाळशास्त्री जांभेकर यांना मराठी वृत्तपत्रांचे जनक मानले जाते.');
INSERT INTO public.questions (subject_tag, subtopic_tag, question_text, option_a, option_b, option_c, option_d, correct_option, explanation) VALUES ('node_0', 'General', 'सूर्यमालेतील सर्वात मोठा ग्रह कोणता आहे?', 'पृथ्वी', 'मंगळ', 'गुरु', 'शनि', 'C', 'गुरु (Jupiter) हा आपल्या सूर्यमालेतील आकारमानाने आणि वस्तुमानाने सर्वात मोठा ग्रह आहे.');
INSERT INTO public.questions (subject_tag, subtopic_tag, question_text, option_a, option_b, option_c, option_d, correct_option, explanation) VALUES ('node_0', 'General', 'महाराष्ट्रातील ''कोयना'' जलविद्युत प्रकल्प कोणत्या जिल्ह्यात आहे?', 'सांगली', 'सातारा', 'रत्नागिरी', 'कोल्हापूर', 'B', 'महाराष्ट्राची भाग्यलक्ष्मी मानला जाणारा कोयना प्रकल्प सातारा जिल्ह्यातील पाटण तालुक्यात आहे.');
INSERT INTO public.questions (subject_tag, subtopic_tag, question_text, option_a, option_b, option_c, option_d, correct_option, explanation) VALUES ('node_0', 'General', 'घड्याळात ५:०० वाजता तासकाटा व मिनिटकाटा यांत किती अंशाचा कोन असतो?', '१२०°', '१३५°', '१५०°', '१८०°', 'C', 'प्रत्येक तासाला ३० अंश. ५ वाजता (५ × ३०°) = १५० अंशाचा कोन बनेल.');
INSERT INTO public.questions (subject_tag, subtopic_tag, question_text, option_a, option_b, option_c, option_d, correct_option, explanation) VALUES ('node_0', 'General', 'भारताची मध्यवर्ती प्रमाणवेळ (IST) ही कोणत्या शहरातून जाणाऱ्या रेखावृत्तावरून ठरवली जाते?', 'मुंबई', 'मिर्झापूर (अलाहाबाद)', 'उज्जैन', 'नागपूर', 'B', 'उत्तर प्रदेशातील मिर्झापूर जवळून जाणाऱ्या ८२.५° पूर्व रेखावृत्तावरून भारताची प्रमाणवेळ ठरते.');
INSERT INTO public.questions (subject_tag, subtopic_tag, question_text, option_a, option_b, option_c, option_d, correct_option, explanation) VALUES ('node_0', 'General', 'माहिती अधिकार कायदा (RTI Act) भारतामध्ये कधी लागू करण्यात आला?', '२००१', '२००५', '२०१०', '२०१५', 'B', 'नागरिकांना पारदर्शक माहिती मिळण्यासाठी १२ ऑक्टोबर २००५ रोजी माहितीचा अधिकार कायदा लागू करण्यात आला.');
INSERT INTO public.questions (subject_tag, subtopic_tag, question_text, option_a, option_b, option_c, option_d, correct_option, explanation) VALUES ('node_0', 'General', 'महाराष्ट्रातील सर्वात लांब नदी कोणती आहे?', 'कृष्णा', 'भीमा', 'गोदावरी', 'तापी', 'C', 'गोदावरी नदी ही महाराष्ट्रातील सर्वात लांब नदी असून तिला ''दक्षिण गंगा'' असेही म्हटले जाते.');
INSERT INTO public.questions (subject_tag, subtopic_tag, question_text, option_a, option_b, option_c, option_d, correct_option, explanation) VALUES ('node_0', 'General', 'वि सु संग त पर्याय ओळखा: जानेवारी, मार्च, मे, नोव्हेंबर', 'जानेवारी', 'मार्च', 'मे', 'नोव्हेंबर', 'D', 'जानेवारी, मार्च आणि मे हे महिने ३१ दिवसांचे आहेत, तर नोव्हेंबर हा ३० दिवसांचा महिना आहे.');
INSERT INTO public.questions (subject_tag, subtopic_tag, question_text, option_a, option_b, option_c, option_d, correct_option, explanation) VALUES ('node_0', 'General', 'भारतात नोटा छापण्याचा कारखाना महाराष्ट्रात कोठे आहे?', 'मुंबई', 'नागपूर', 'नाशिक', 'पुणे', 'C', 'नाशिक येथे ''करन्सी नोट प्रेस'' (Currency Note Press) कारखाना आहे.');
INSERT INTO public.questions (subject_tag, subtopic_tag, question_text, option_a, option_b, option_c, option_d, correct_option, explanation) VALUES ('node_0', 'General', 'जर एका वस्तूची खरेदी किंमत ₹४०० आहे आणि ती ₹५०० ला विकली, तर शेकडा नफा किती?', '२०%', '२५%', '३०%', '१५%', 'B', 'नफा = ५०० - ४०० = १०० रुपये. शेकडा नफा = (१०० / ४००) * १०० = २५%.');
INSERT INTO public.questions (subject_tag, subtopic_tag, question_text, option_a, option_b, option_c, option_d, correct_option, explanation) VALUES ('node_0', 'General', 'एका वस्तूची खरेदी किंमत ₹५०० व विक्री किंमत ₹५५० आहे, तर शेकडा नफा किती?', '५%', '१०%', '१२%', '१५%', 'B', 'नफा = ५० रुपये. शेकडा नफा = (५० / ५००) × १०० = १०%.');
INSERT INTO public.questions (subject_tag, subtopic_tag, question_text, option_a, option_b, option_c, option_d, correct_option, explanation) VALUES ('node_0', 'General', 'पोलीस खात्यातील ''PSI'' या पदाचा पूर्ण अर्थ काय?', 'Police Sub Inspector', 'Police Senior Inspector', 'Public Safety Inspector', 'Police Security Inspector', 'A', 'PSI म्हणजे Police Sub Inspector (पोलीस उपनिरीक्षक).');
INSERT INTO public.questions (subject_tag, subtopic_tag, question_text, option_a, option_b, option_c, option_d, correct_option, explanation) VALUES ('node_0', 'General', '''तो घाबरून पळाला.'' या वाक्यात ''घाबरून'' हे कोणते अव्यय आहे?', 'शब्दयोगी अव्यय', 'क्रियाविशेषण अव्यय', 'उभयान्वयी अव्यय', 'केवलप्रयोगी अव्यय', 'B', 'पळण्याच्या क्रियेबद्दल अधिक माहिती सांगत असल्याने ''घाबरून'' हे क्रियाविशेषण आहे.');
INSERT INTO public.questions (subject_tag, subtopic_tag, question_text, option_a, option_b, option_c, option_d, correct_option, explanation) VALUES ('node_0', 'General', 'खालीलपैकी कोणता रक्तगट ''सर्वयोग्य दाता'' (Universal Donor) म्हणून ओळखला जातो?', 'A+', 'B+', 'AB+', 'O-', 'D', 'O निगेटिव्ह (O-) रक्तगट हा कोणत्याही रक्तगटाच्या व्यक्तीला दिला जाऊ शकत असल्याने त्याला ''सर्वयोग्य दाता'' म्हणतात.');
INSERT INTO public.questions (subject_tag, subtopic_tag, question_text, option_a, option_b, option_c, option_d, correct_option, explanation) VALUES ('node_0', 'General', 'पचनक्रियेत अन्नाचे पचन प्रामुख्याने मानवी शरीराच्या कोणत्या अवयवात पूर्ण होते?', 'जठर', 'मोठे आतडे', 'लहान आतडे', 'यकृत', 'C', 'अन्नाचे अंतिम पचन आणि पोषकांचे शोषण लहान आतड्यात (Small Intestine) पूर्ण होते.');
INSERT INTO public.questions (subject_tag, subtopic_tag, question_text, option_a, option_b, option_c, option_d, correct_option, explanation) VALUES ('node_0', 'General', 'मराठी भाषेत एकूण किती मुख्य वर्ण (Mool Varn) मानले जातात?', '४८', '५२', '३४', '१२', 'B', 'नवीन शासन निर्णयानुसार मराठी वर्णमालेत आता एकूण ५२ वर्ण (इंग्रजी स्वरांसह) समाविष्ट आहेत.');
INSERT INTO public.questions (subject_tag, subtopic_tag, question_text, option_a, option_b, option_c, option_d, correct_option, explanation) VALUES ('node_0', 'General', '''कवी'' या शब्दाचे स्त्रीलिंगी रूप काय होईल?', 'कवीत्री', 'कवयित्री', 'कवीता', 'काव्या', 'B', 'मराठी व्याकरणात ''कवी'' या शब्दाचे शुद्ध आणि योग्य स्त्रीलिंगी रूप ''कवयित्री'' असे लिहिले जाते.');
INSERT INTO public.questions (subject_tag, subtopic_tag, question_text, option_a, option_b, option_c, option_d, correct_option, explanation) VALUES ('node_0', 'General', '''सूर्य'' या शब्दाची संधी विग्रह कशी होईल?', 'सूर्या + उदय', 'सूर्य + उदय', 'सूर्य + दय', 'सूर्यो + दय', 'B', 'सूर्य + उदय = सूर्योदय (गुणदेश स्वरसंधीचे उदाहरण).');
INSERT INTO public.questions (subject_tag, subtopic_tag, question_text, option_a, option_b, option_c, option_d, correct_option, explanation) VALUES ('node_0', 'General', 'मालिकेतील विसंगत घटक शोधा: ९, १६, २५, ३५, ४९', '१६', '२५', '३५', '४९', 'C', '९, १६, २५, ४९ या अनुक्रमे ३, ४, ५, ७ च्या वर्ग संख्या आहेत, ३५ ही वर्ग संख्या नाही.');
INSERT INTO public.questions (subject_tag, subtopic_tag, question_text, option_a, option_b, option_c, option_d, correct_option, explanation) VALUES ('node_0', 'General', '''मी निबंध लिहिला असेल.'' या वाक्याचा काळ ओळखा.', 'साधा भूतकाळ', 'अपूर्ण भूतकाळ', 'पूर्ण भविष्यकाळ', 'रीती भविष्यकाळ', 'C', 'भविष्यात क्रिया पूर्ण झालेली असेल असा बोध होत असल्याने हा पूर्ण भविष्यकाळ आहे.');
INSERT INTO public.questions (subject_tag, subtopic_tag, question_text, option_a, option_b, option_c, option_d, correct_option, explanation) VALUES ('node_0', 'General', '''ज्याला कोणीही शत्रू नाही असा'' या शब्दसमूहाबद्दल एक शब्द सांगा.', 'अजातशत्रू', 'निशत्रू', 'मितशत्रू', 'सर्वमित्र', 'A', 'ज्याचा कोणीही शत्रू जन्माला आला नाही किंवा ज्याचा कोणी शत्रू नाही, त्याला ''अजातशत्रू'' म्हणतात.');
INSERT INTO public.questions (subject_tag, subtopic_tag, question_text, option_a, option_b, option_c, option_d, correct_option, explanation) VALUES ('node_0', 'General', 'जागतिक पर्यावरण दिन कधी साजरा केला जातो?', '५ जून', '२२ एप्रिल', '१६ सप्टेंबर', '२१ जून', 'A', 'पर्यावरण संरक्षणासाठी जनजागृती व्हावी म्हणून दरवर्षी ५ जून हा जागतिक पर्यावरण दिन म्हणून पाळला जातो.');
INSERT INTO public.questions (subject_tag, subtopic_tag, question_text, option_a, option_b, option_c, option_d, correct_option, explanation) VALUES ('node_0', 'General', 'मालिकेतील गाळलेली संख्या शोधा: ३, ९, २७, ८१, ?', '१६२', '२४३', '३२४', '२५०', 'B', 'प्रत्येक संख्या ३ ने गुणली आहे. ८१ × ३ = २४३.');
INSERT INTO public.questions (subject_tag, subtopic_tag, question_text, option_a, option_b, option_c, option_d, correct_option, explanation) VALUES ('node_0', 'General', 'महाराष्ट्रातील ''गौताळा औट्रमघाट'' अभयारण्य कोणत्या जिल्ह्यात स्थित आहे?', 'छत्रपती संभाजीनगर व जळगाव', 'पुणे व सातार', 'नागपूर व वर्धा', 'नाशिक व नगर', 'A', 'गौताळा अभयारण्य हे छत्रपती संभाजीनगर आणि जळगाव जिल्ह्यांच्या सीमेवर पसरलेले आहे.');
INSERT INTO public.questions (subject_tag, subtopic_tag, question_text, option_a, option_b, option_c, option_d, correct_option, explanation) VALUES ('node_0', 'General', '''क्षणभंगुर'' या शब्दाचा योग्य अर्थ ओळखा.', 'कायम टिकणारा', 'थोड्याच वेळात नष्ट होणारा', 'कधीही न संपणारा', 'मजबूत असणारा', 'B', 'ज्या गोष्टीचे अस्तित्व अतिशय अल्पकाळ टिकते त्याला ''क्षणभंगुर'' म्हणतात.');
INSERT INTO public.questions (subject_tag, subtopic_tag, question_text, option_a, option_b, option_c, option_d, correct_option, explanation) VALUES ('node_0', 'General', '''डोळे उघडणे'' या वाक्प्रचाराचा अर्थ काय?', 'झोपेतून उठणे', 'चूक लक्षात येणे / वस्तूस्थिती समजणे', 'डोळे साफ करणे', 'रागाने बघणे', 'B', 'अनुभवातून किंवा सत्याची जाणीव होऊन स्वतःची चूक लक्षात येणे म्हणजेच ''डोळे उघडणे''.');
INSERT INTO public.questions (subject_tag, subtopic_tag, question_text, option_a, option_b, option_c, option_d, correct_option, explanation) VALUES ('node_0', 'General', 'झाशीची राणी लक्ष्मीबाई यांनी १८५७ च्या उठावात कोठून नेतृत्व केले?', 'कानपूर', 'झाशी', 'दिल्ली', 'लखनऊ', 'B', 'राणी लक्ष्मीबाई यांनी १८५७ च्या स्वातंत्र्यसंग्रामात झाशी येथून ब्रिटिशांविरुद्ध लढा दिला.');
INSERT INTO public.questions (subject_tag, subtopic_tag, question_text, option_a, option_b, option_c, option_d, correct_option, explanation) VALUES ('node_0', 'General', '''उंटावरून शेळ्या हाकणे'' या म्हणीचा अर्थ काय?', 'उंट चालवणे', 'प्रत्यक्ष काम न करता लांबूनच केवळ फुकटचा सल्ला देणे', 'शेळ्यांची काळजी घेणे', 'अतिशय कष्ट करणे', 'B', 'स्वतः कामात भाग न घेता दूरवरूनच सूचना किंवा हुकूम सोडण्याच्या वृत्तीला ''उंटावरून शेळ्या हाकणे'' म्हणतात.');
INSERT INTO public.questions (subject_tag, subtopic_tag, question_text, option_a, option_b, option_c, option_d, correct_option, explanation) VALUES ('node_0', 'General', 'जर काल मंगळवार होता, तर परवाच्या नंतरचा दिवस कोणता असेल?', 'शुक्रवार', 'शनिवार', 'रविवार', 'सोमवार', 'B', 'काल = मंगळवार, आज = बुधवार, उद्या = गुरुवार, परवा = शुक्रवार, परवानंतरचा दिवस = शनिवार.');
INSERT INTO public.questions (subject_tag, subtopic_tag, question_text, option_a, option_b, option_c, option_d, correct_option, explanation) VALUES ('node_0', 'General', 'भारताची राजधानी कोणती आहे?', 'मुंबई', 'नवी दिल्ली', 'कोलकाता', 'चेन्नई', 'B', '१९११ मध्ये राजधानी कोलकात्याहून दिल्लीला हलवण्यात आली आणि सध्या नवी दिल्ली ही भारताची अधिकृत राजधानी आहे.');
INSERT INTO public.questions (subject_tag, subtopic_tag, question_text, option_a, option_b, option_c, option_d, correct_option, explanation) VALUES ('node_0', 'General', 'महाराष्ट्र गुप्तवार्ता विभाग (SID) चे मुख्यालय कोठे आहे?', 'मुंबई', 'पुणे', 'नागपूर', 'नाशिक', 'A', 'महाराष्ट्र पोलिसांच्या गुप्तवार्ता विभागाचे (State Intelligence Department) मुख्य कार्यालय मुंबई येथे आहे.');
INSERT INTO public.questions (subject_tag, subtopic_tag, question_text, option_a, option_b, option_c, option_d, correct_option, explanation) VALUES ('node_0', 'General', 'वि सु संग त घटक ओळखा: मीटर, किलोमीटर, ग्रॅम, सेंटीमीटर', 'मीटर', 'किलोमीटर', 'ग्रॅम', 'सेंटीमीटर', 'C', 'मीटर, किलोमीटर आणि सेंटीमीटर ही लांबी मोजण्याची एकके आहेत, तर ''ग्रॅम'' हे वस्तुमान (वजन) मोजण्याचे एकक आहे.');
INSERT INTO public.questions (subject_tag, subtopic_tag, question_text, option_a, option_b, option_c, option_d, correct_option, explanation) VALUES ('node_0', 'General', 'महाराष्ट्रात लोकसभेच्या एकूण किती जागा आहेत?', '४८', '१९', '२८८', '७८', 'A', 'महाराष्ट्रातून लोकसभेवर एकूण ४८ खासदार निवडून जातात.');
INSERT INTO public.questions (subject_tag, subtopic_tag, question_text, option_a, option_b, option_c, option_d, correct_option, explanation) VALUES ('node_0', 'General', 'जर सांकेतिक भाषेत ''BOOK'' ला ''CQPLO'' असे लिहिले, तर ''PEN'' कसे लिहिले जाईल?', 'QFO', 'QFO', 'QFPO', 'QGP', 'A', 'येथे प्रत्येक अक्षराच्या जागी वर्णमालेतील पुढील अक्षर (+१) वापरले आहे: P(+1)->Q, E(+1)->F, N(+1)->O. त्यामुळे उत्तर QFO येईल.');
INSERT INTO public.questions (subject_tag, subtopic_tag, question_text, option_a, option_b, option_c, option_d, correct_option, explanation) VALUES ('node_0', 'General', 'एका संख्येचा ३/४ भाग ६० आहे, तर ती संख्या कोणती?', '७०', '८०', '९०', '१००', 'B', 'x × (३/४) = ६० => x = (६० × ४) / ३ = २४० / ३ = ८०.');
INSERT INTO public.questions (subject_tag, subtopic_tag, question_text, option_a, option_b, option_c, option_d, correct_option, explanation) VALUES ('node_0', 'General', 'महाराष्ट्रातील सर्वात उंच शिखर कोणते आहे?', 'साल्हेर', 'महाबळेश्वर', 'कलसुबाई', 'त्र्यंबकेश्वर', 'C', 'अहमदनगर जिल्ह्यातील ''कलसुबाई'' (उंची १६४६ मीटर) हे महाराष्ट्रातील सर्वात उंच शिखर आहे.');
INSERT INTO public.questions (subject_tag, subtopic_tag, question_text, option_a, option_b, option_c, option_d, correct_option, explanation) VALUES ('node_0', 'General', 'महाराष्ट्राचे राज्य प्राणी कोणता आहे?', 'शेकरू (मोठी खार)', 'वाघ', 'हरिण', 'हत्ती', 'A', 'भीमाशंकरच्या जंगलात आढळणारी विशालकाय खार ''शेकरू'' हा महाराष्ट्राचा राज्य प्राणी आहे.');
INSERT INTO public.questions (subject_tag, subtopic_tag, question_text, option_a, option_b, option_c, option_d, correct_option, explanation) VALUES ('node_0', 'General', 'मुलगा पूर्व दिशेला तोंड करून उभा आहे. तो घड्याळाच्या विरुद्ध दिशेने ९०° वळल्यास त्याचे तोंड कोणत्या दिशेला असेल?', 'दक्षिण', 'उत्तर', 'पश्चिम', 'ईशान्य', 'B', 'पूर्व दिशेकडून घड्याळाच्या विरुद्ध दिशेने (डावीकडे) ९० अंशात वळल्यास ''उत्तर'' दिशा येते.');
INSERT INTO public.questions (subject_tag, subtopic_tag, question_text, option_a, option_b, option_c, option_d, correct_option, explanation) VALUES ('node_0', 'General', 'एका चौकोनाच्या चारही कोनांच्या मापांची बेरीज किती अंश असते?', '१८०°', '२७०°', '३६०°', '५४०°', 'C', 'कोणत्याही चौकोनाच्या चार अंतःकोनांच्या मापांची बेरीज ३६० अंश असते.');
INSERT INTO public.questions (subject_tag, subtopic_tag, question_text, option_a, option_b, option_c, option_d, correct_option, explanation) VALUES ('node_0', 'General', 'महाराष्ट्रात सर्वाधिक तालुके असणारे जिल्हे कोणते?', 'नांदेड व यवतमाळ', 'पुणे व नाशिक', 'ठाणे व पालघर', 'अहमदनगर व जळगाव', 'A', 'नांदेड आणि यवतमाळ या दोन्ही जिल्ह्यांमध्ये प्रत्येकी सर्वाधिक म्हणजेच १६ तालुके आहेत.');
INSERT INTO public.questions (subject_tag, subtopic_tag, question_text, option_a, option_b, option_c, option_d, correct_option, explanation) VALUES ('node_0', 'General', 'भारतातील सर्वात मोठे राज्य (क्षेत्रफळाच्या दृष्टीने) कोणते?', 'महाराष्ट्र', 'मध्य प्रदेश', 'राजस्थान', 'उत्तर प्रदेश', 'C', 'क्षेत्रफळाच्या दृष्टीने राजस्थान हे भारतातील सर्वात मोठे राज्य आहे.');
INSERT INTO public.questions (subject_tag, subtopic_tag, question_text, option_a, option_b, option_c, option_d, correct_option, explanation) VALUES ('node_0', 'General', '८, १२, १६ यांचा लसावी (LCM) किती?', '२४', '३६', '४८', '६४', 'C', '८, १२ आणि १६ या तिन्ही संख्यांनी भाग जाणारी लहानात लहान संख्या ४८ आहे.');
INSERT INTO public.questions (subject_tag, subtopic_tag, question_text, option_a, option_b, option_c, option_d, correct_option, explanation) VALUES ('node_0', 'General', 'एका संख्येच्या ४ पटीतून १० वजा केल्यास ३० येतात, तर ती संख्या कोणती?', '८', '१०', '१२', '१५', 'B', 'समीकरण: ४x - १० = ३०  => ४x = ४०  => x = १०.');
INSERT INTO public.questions (subject_tag, subtopic_tag, question_text, option_a, option_b, option_c, option_d, correct_option, explanation) VALUES ('node_0', 'General', 'एका पेनाची किंमत ₹१५ आहे. २ डझन पेनाची किंमत किती होईल?', '₹ १८०', '₹ २४०', '₹ ३६०', '₹ ३००', 'C', '२ डझन = २४ पेने. एकूण किंमत = २४ × १५ = ३६० रुपये.');
INSERT INTO public.questions (subject_tag, subtopic_tag, question_text, option_a, option_b, option_c, option_d, correct_option, explanation) VALUES ('node_0', 'General', 'भारताचे राष्ट्रीय फूल कोणते आहे?', 'गुलाब', 'कमळ', 'सूर्यफूल', 'झेंडू', 'B', 'कमळ (Lotus) हे भारताचे अधिकृत राष्ट्रीय फूल आहे.');
INSERT INTO public.questions (subject_tag, subtopic_tag, question_text, option_a, option_b, option_c, option_d, correct_option, explanation) VALUES ('node_0', 'General', 'महाराष्ट्रातील पहिला सहकारी साखर कारखाना कोठे सुरू झाला?', 'प्रवरानगर', 'बारामती', 'सांगली', 'कोल्हापूर', 'A', 'विठ्ठलराव विखे पाटील यांच्या पुढाकारातून अहमदनगर जिल्ह्यातील प्रवरानगर (लोणी) येथे पहिला यशस्वी सहकारी साखर कारखाना स्थापन झाला.');
INSERT INTO public.questions (subject_tag, subtopic_tag, question_text, option_a, option_b, option_c, option_d, correct_option, explanation) VALUES ('node_0', 'General', 'विरुद्धार्थी शब्द ओळखा: ''आदर'' × ?', 'अनादर', 'सत्कार', 'सन्मान', 'प्रेम', 'A', '''आदर'' या शब्दाचा योग्य विरुद्धार्थी शब्द ''अनादर'' किंवा ''अवहेलना'' असा होतो.');
INSERT INTO public.questions (subject_tag, subtopic_tag, question_text, option_a, option_b, option_c, option_d, correct_option, explanation) VALUES ('node_0', 'General', '''कपाळाला हात लावणे'' या वाक्प्रचाराचा योग्य अर्थ काय?', 'डोके दुखणे', 'हताश किंवा हतबल होणे', 'आनंद होणे', 'विचार करणे', 'B', 'एखाद्या वाईट प्रसंगी किंवा अपयश आल्यावर निराशेने ''कपाळाला हात लावणे'' असा प्रयोग केला जातो.');
INSERT INTO public.questions (subject_tag, subtopic_tag, question_text, option_a, option_b, option_c, option_d, correct_option, explanation) VALUES ('node_1', 'General', 'काझीरंगा राष्ट्रीय उद्यान कोणत्या राज्यात आहे?', 'पश्चिम बंगाल', 'आसाम', 'उत्तराखंड', 'मध्य प्रदेश', 'B', 'एशिंगी गेंड्यासाठी प्रसिद्ध असलेले काझीरंगा राष्ट्रीय उद्यान आसाम राज्यात आहे.');
INSERT INTO public.questions (subject_tag, subtopic_tag, question_text, option_a, option_b, option_c, option_d, correct_option, explanation) VALUES ('node_1', 'General', 'खालीलपैकी ''अग्नी'' या शब्दाचा समानार्थी शब्द कोणता नाही?', 'पावक', 'अनिल', 'अनल', 'वैश्वानर', 'B', 'पावक, अनल आणि वैश्वानर हे सर्व अग्नीचे समानार्थी शब्द आहेत; परंतु ''अनिल'' म्हणजे वारा (हवा).');
INSERT INTO public.questions (subject_tag, subtopic_tag, question_text, option_a, option_b, option_c, option_d, correct_option, explanation) VALUES ('node_1', 'General', 'महाराष्ट्रातील प्रसिद्ध ''भंडारदरा'' धरण कोणत्या नदीवर बांधण्यात आले आहे?', 'प्रवरा', 'गोदावरी', 'कृष्णा', 'मुळा', 'A', 'अहमदनगर जिल्ह्यातील भंडारदरा (विल्सन डॅम) हे धरण प्रवरा नदीवर उभारलेले आहे.');
INSERT INTO public.questions (subject_tag, subtopic_tag, question_text, option_a, option_b, option_c, option_d, correct_option, explanation) VALUES ('node_1', 'General', 'इन्सुलिन (Insulin) हे संप्रेरक मानवी शरीरातील कोणत्या अवयवात तयार होते?', 'यकृत', 'स्वादुपिंड (Pancreas)', 'मूत्रपिंड', 'हृदय', 'B', 'रक्तातील शर्करेचे प्रमाण नियंत्रित करणारे इन्सुलिन हे संप्रेरक स्वादुपिंडातील (Pancreas) बेटांमधून स्रवते.');
INSERT INTO public.questions (subject_tag, subtopic_tag, question_text, option_a, option_b, option_c, option_d, correct_option, explanation) VALUES ('node_1', 'General', 'महाराष्ट्रातील ''चिखलदरा'' हे थंड हवेचे ठिकाण कोणत्या पर्वतावर आहे?', 'सह्याद्री', 'सातपुडा', 'बालाघाट', 'अजिंठा', 'B', 'अमरावती जिल्ह्यातील चिखलदरा हे गिरीस्थान सातपुडा पर्वत रांगेत (गाविलगड टेकड्या) वसलेले आहे.');
INSERT INTO public.questions (subject_tag, subtopic_tag, question_text, option_a, option_b, option_c, option_d, correct_option, explanation) VALUES ('node_1', 'General', 'एका त्रिकोणाचा पाया १० सेमी आणि उंची ८ सेमी आहे, तर त्रिकोणाचे क्षेत्रफळ किती?', '४० चौ सेमी', '८० चौ सेमी', '५० चौ सेमी', '२० चौ सेमी', 'A', 'त्रिकोणाचे क्षेत्रफळ = १/२ × पाया × उंची = १/२ × १० × ८ = ४० चौ सेमी.');
INSERT INTO public.questions (subject_tag, subtopic_tag, question_text, option_a, option_b, option_c, option_d, correct_option, explanation) VALUES ('node_1', 'General', 'खालीलपैकी ''अमृत'' या शब्दाचा विरुद्धार्थी शब्द कोणता?', 'गोड', 'विष', 'सुधा', 'पीयूष', 'B', 'सुधा आणि पीयूष हे अमृताचे समानार्थी शब्द आहेत, तर ''विष'' हा त्याचा विरुद्धार्थी शब्द आहे.');
INSERT INTO public.questions (subject_tag, subtopic_tag, question_text, option_a, option_b, option_c, option_d, correct_option, explanation) VALUES ('node_1', 'General', 'मालिकेतील पुढील पद शोधा: २, ६, १२, २०, ३०, ?', '३६', '४०', '४२', '४८', 'C', 'फरक अनुक्रमे +४, +६, +८, +१० असा वाढत आहे. त्यामुळे पुढील फरक +१२ असेल: ३० + १२ = ४२.');
INSERT INTO public.questions (subject_tag, subtopic_tag, question_text, option_a, option_b, option_c, option_d, correct_option, explanation) VALUES ('node_1', 'General', '''दप्तरदिरंगाई'' कायदा महाराष्ट्रात कधीपासून लागू झाला?', '२००२', '२००६', '२०१०', '२०१५', 'B', 'सरकारी कामात होणारा उशीर टाळण्यासाठी महाराष्ट्र शासकीय कर्तव्ये पार पाडताना होणारा उशीर प्रतिबंधक (दप्तरदिरंगाई) कायदा २००६ मध्ये लागू झाला.');
INSERT INTO public.questions (subject_tag, subtopic_tag, question_text, option_a, option_b, option_c, option_d, correct_option, explanation) VALUES ('node_1', 'General', '''अहिंसा'' या शब्दाचा विरुद्धार्थी शब्द कोणता?', 'शांतता', 'हिंसा', 'सहकार्य', 'सदाचार', 'B', '''अहिंसा'' चा विरुद्धार्थी शब्द ''हिंसा'' असा होतो.');
INSERT INTO public.questions (subject_tag, subtopic_tag, question_text, option_a, option_b, option_c, option_d, correct_option, explanation) VALUES ('node_1', 'General', '६०० रुपयांची वस्तू ४८० रुपयांना विकल्यास शेकडा सुट (Discount) किती मिळाली?', '१५%', '२०%', '२५%', '१०%', 'B', 'सवलत = ६०० - ४८० = १२० रुपये. शेकडा सवलत = (१२० / ६००) × १०० = २०%.');
INSERT INTO public.questions (subject_tag, subtopic_tag, question_text, option_a, option_b, option_c, option_d, correct_option, explanation) VALUES ('node_1', 'General', '३/४ या अपूर्णांकाचे टक्केवारीत (Percentage) रूपांतर करा.', '५०%', '६०%', '७५%', '८०%', 'C', '(३ / ४) × १०० = ३ × २५ = ७५%.');
INSERT INTO public.questions (subject_tag, subtopic_tag, question_text, option_a, option_b, option_c, option_d, correct_option, explanation) VALUES ('node_1', 'General', '३६० चे २५% = ?', '८०', '९०', '१००', '१२०', 'B', '(३६० × २५) / १०० = ३६० / ४ = ९०.');
INSERT INTO public.questions (subject_tag, subtopic_tag, question_text, option_a, option_b, option_c, option_d, correct_option, explanation) VALUES ('node_1', 'General', 'एका आयताची लांबी १५ सेमी आणि रुंदी १० सेमी आहे, तर त्याची परिमिती किती?', '५० सेमी', '१५० सेमी', '२५ सेमी', '३० सेमी', 'A', 'आयताची परिमिती = २ × (लांबी + रुंदी) = २ × (१५ + १०) = २ × २५ = ५० सेमी.');
INSERT INTO public.questions (subject_tag, subtopic_tag, question_text, option_a, option_b, option_c, option_d, correct_option, explanation) VALUES ('node_1', 'General', 'महात्मा गांधींनी ''भारत छोडो'' आंदोलन कोणत्या वर्षी सुरू केले?', '१९२०', '१९३०', '१९४२', '१९४५', 'C', '८ ऑगस्ट १९४२ रोजी मुंबईतील गवालिया टँक मैदानावरून महात्मा गांधींनी ''भारत छोडो'' आंदोलनाची घोषणा केली.');
INSERT INTO public.questions (subject_tag, subtopic_tag, question_text, option_a, option_b, option_c, option_d, correct_option, explanation) VALUES ('node_1', 'General', 'महाराष्ट्रातील ताडोबा राष्ट्रीय उद्यान कोणत्या जिल्ह्यात आहे?', 'नागपूर', 'चंद्रपूर', 'अमरावती', 'गडचिरोली', 'B', 'वाघांसाठी प्रसिद्ध असलेले ''ताडोबा-अंधारी व्याघ्र प्रकल्प'' हे महाराष्ट्रातील चंद्रपूर जिल्ह्यात स्थित आहे.');
INSERT INTO public.questions (subject_tag, subtopic_tag, question_text, option_a, option_b, option_c, option_d, correct_option, explanation) VALUES ('node_1', 'General', 'खालीलपैकी कोणता शब्द शुद्ध आहे?', 'आशिर्वाद', 'आशीर्वाद', 'अशीर्वाद', 'आशीर्वाद्', 'B', 'मराठी व्याकरणाच्या नियमांनुसार ''आशीर्वाद'' हा शब्द शुद्ध आहे (श ला दुसरी वेलांटी व व वर रफार).');
INSERT INTO public.questions (subject_tag, subtopic_tag, question_text, option_a, option_b, option_c, option_d, correct_option, explanation) VALUES ('node_1', 'General', 'रिझर्व्ह बँक ऑफ इंडिया (RBI) चे मुख्यालय कोठे आहे?', 'नवी दिल्ली', 'कोलकाता', 'मुंबई', 'चेन्नई', 'C', 'भारतीय रिझर्व्ह बँकेची स्थापना १९३५ मध्ये झाली असून तिचे मुख्यालय मुंबई येथे आहे.');
INSERT INTO public.questions (subject_tag, subtopic_tag, question_text, option_a, option_b, option_c, option_d, correct_option, explanation) VALUES ('node_1', 'General', 'जर एका सांकेतिक भाषेत MANGO = NBOHP, तर APPLE = ?', 'BQQMF', 'BPQMF', 'BQPMF', 'BQPNF', 'C', 'प्रत्येक अक्षर १ स्थानाने पुढे सरकते: A->B, P->Q, P->Q, L->M, E->F.');
INSERT INTO public.questions (subject_tag, subtopic_tag, question_text, option_a, option_b, option_c, option_d, correct_option, explanation) VALUES ('node_1', 'General', 'विटामिन ''C'' च्या अभावामुळे कोणता रोग होतो?', 'रातांधळेपणा', 'स्करव्ही (Scurvy)', 'बेरीबेरी', 'मुडदूस', 'B', 'जीवनसत्त्व ''क'' (Vitamin C) च्या अभावामुळे दातांच्या हिरड्यांमधून रक्त येणे आणि ''स्करव्ही'' हा आजार होतो.');
INSERT INTO public.questions (subject_tag, subtopic_tag, question_text, option_a, option_b, option_c, option_d, correct_option, explanation) VALUES ('node_1', 'General', '''तोंडाला कुलूप लावणे'' या वाक्प्रचाराचा योग्य अर्थ कोणता?', 'तोंड धुणे', 'मुळीच न बोलणे / गप्प राहणे', 'उपाशी राहणे', 'मोठ्याने ओरडणे', 'B', '''तोंडाला कुलूप लावणे'' म्हणजे काहीही न बोलता पूर्णपणे शांत राहणे.');
INSERT INTO public.questions (subject_tag, subtopic_tag, question_text, option_a, option_b, option_c, option_d, correct_option, explanation) VALUES ('node_1', 'General', 'भारतातील पहिल्या महिला IPS अधिकारी कोण आहेत?', 'किरण बेदी', 'कंचन चौधरी', 'पुनिता अरोरा', 'अर्चना रामासुंदरम', 'A', 'किरण बेदी या १९७२ मध्ये भारतीय पोलीस सेवेत (IPS) रुजू होणाऱ्या पहिल्या महिला अधिकारी ठरल्या.');
INSERT INTO public.questions (subject_tag, subtopic_tag, question_text, option_a, option_b, option_c, option_d, correct_option, explanation) VALUES ('node_1', 'General', 'जर ०.५ × ०.२ = ?', '०.१', '०.०१', '१.०', '०.१०', 'A', '५ × २ = १०. दोन्ही संख्येत मिळून २ अंकांनंतर दशांश चिन्ह दिल्यास ०.१० म्हणजेच ०.१ उत्तर येते.');
INSERT INTO public.questions (subject_tag, subtopic_tag, question_text, option_a, option_b, option_c, option_d, correct_option, explanation) VALUES ('node_1', 'General', '''डोळ्यांवर धुंदी येणे'' या वाक्प्रचाराचा अर्थ काय?', 'डोळे दुखणे', 'गर्व चढणे', 'झोप येणे', 'दिसणे बंद होणे', 'B', '''डोळ्यांवर धुंदी येणे'' म्हणजे संपत्ती, सत्ता किंवा यशामुळे गर्वाने आंधळे होणे.');
INSERT INTO public.questions (subject_tag, subtopic_tag, question_text, option_a, option_b, option_c, option_d, correct_option, explanation) VALUES ('node_1', 'General', 'महाराष्ट्र गुप्तवार्ता प्रबोधिनी कुठे आहे असा प्रश्न असल्यास त्याचे मुख्यालय कोणत्या शहरात आहे?', 'पुणे', 'मुंबई', 'नागपूर', 'ठाणे', 'A', 'महाराष्ट्र पोलिसांची गुप्तवार्ता प्रबोधिनी पुणे शहरात रामटेकडी परिसरात कार्यरत आहे.');
INSERT INTO public.questions (subject_tag, subtopic_tag, question_text, option_a, option_b, option_c, option_d, correct_option, explanation) VALUES ('node_1', 'General', 'अलंकारिक शब्द ओळखा: ''अकलेचा कांदा''', 'अतिशय हुशार मनुष्य', 'मूर्ख मनुष्य', 'कांदा व्यापारी', 'गरीब व्यक्ती', 'B', 'मराठीत ''अकलेचा कांदा'' हा शब्द अत्यंत मूर्ख व्यक्तीसाठी वापरला जातो.');
INSERT INTO public.questions (subject_tag, subtopic_tag, question_text, option_a, option_b, option_c, option_d, correct_option, explanation) VALUES ('node_1', 'General', 'एका नळाने एक टाकी ६ तासांत भरते, तर १ तासात टाकीचा किती भाग भरेल?', '१/२', '१/४', '१/६', '१/३', 'C', 'एकूण वेळ ६ तास असल्यास एका तासातील काम १/६ भाग असेल.');
INSERT INTO public.questions (subject_tag, subtopic_tag, question_text, option_a, option_b, option_c, option_d, correct_option, explanation) VALUES ('node_1', 'General', 'दिशेवरील प्रश्न: दक्षिण दिशेकडे तोंड करून उभा असलेला माणूस डावीकडे ९०° वळल्यास त्याचे तोंड कोठे असेल?', 'उत्तर', 'पश्चिम', 'पूर्व', 'वायव्य', 'C', 'दक्षिण दिशेकडून डावीकडे ९० अंश वळल्यास पूर्व दिशा येते.');
INSERT INTO public.questions (subject_tag, subtopic_tag, question_text, option_a, option_b, option_c, option_d, correct_option, explanation) VALUES ('node_1', 'General', 'मालिकेतील पुढील पद शोधा: ३, ६, १२, २४, ४८, ?', '६०', '७२', '९६', '१०८', 'C', 'प्रत्येक संख्या मागील संख्येची दुप्पट होत आहे. ४८ × २ = ९६.');
INSERT INTO public.questions (subject_tag, subtopic_tag, question_text, option_a, option_b, option_c, option_d, correct_option, explanation) VALUES ('node_1', 'General', 'घड्याळात ६:०० वाजले असता तासकाटा आणि मिनिटकाटा यांमध्ये किती अंशाचा कोन असतो?', '९०°', '१२०°', '१८०°', '३६०°', 'C', '६ वाजता दोन्ही काटे एकमेकांच्या तंतोतंत विरुद्ध दिशेला असतात, ज्यामुळे १८०° चा सरळकोन बनतो.');
INSERT INTO public.questions (subject_tag, subtopic_tag, question_text, option_a, option_b, option_c, option_d, correct_option, explanation) VALUES ('node_1', 'General', '१५ मजूर एक काम २० दिवसांत पूर्ण करतात, तर १० मजूर तेच काम किती दिवसांत पूर्ण करतील?', '३० दिवस', '२५ दिवस', '४० दिवस', '१५ दिवस', 'A', 'व्यस्त प्रमाण: M1 × D1 = M2 × D2 => १५ × २० = १० × D2 => D2 = ३०० / १० = ३० दिवस.');
INSERT INTO public.questions (subject_tag, subtopic_tag, question_text, option_a, option_b, option_c, option_d, correct_option, explanation) VALUES ('node_1', 'General', 'महाराष्ट्र पोलीस दलाचे राज्य मुख्यालय कुठे आहे?', 'पुणे', 'नागपूर', 'मुंबई (कुलाबा)', 'नाशिक', 'C', 'महाराष्ट्र राज्याचे पोलीस मुख्यालय कुलाबा, मुंबई येथे स्थित आहे.');
INSERT INTO public.questions (subject_tag, subtopic_tag, question_text, option_a, option_b, option_c, option_d, correct_option, explanation) VALUES ('node_1', 'General', 'मालिकेतील प्रश्नचिन्हाच्या जागी कोणती संख्या येईल? ५, ११, २३, ४७, ?', '८५', '९५', '९६', '९४', 'B', 'नियम: (संख्या × २) + १. ५×२+१=११, ११×२+१=२३, २३×२+१=४७, ४७×२+१=९५.');
INSERT INTO public.questions (subject_tag, subtopic_tag, question_text, option_a, option_b, option_c, option_d, correct_option, explanation) VALUES ('node_1', 'General', 'महाराष्ट्रातील ''त्र्यंबकेश्वर'' हे ज्योतिर्लिंग कोणत्या जिल्ह्यात आहे?', 'पुणे', 'नाशिक', 'अहमदनगर', 'छत्रपती संभाजीनगर', 'B', 'भारतातील १२ ज्योतिर्लिंगांपैकी एक असलेले त्र्यंबकेश्वर मंदिर नाशिक जिल्ह्यात आहे.');
INSERT INTO public.questions (subject_tag, subtopic_tag, question_text, option_a, option_b, option_c, option_d, correct_option, explanation) VALUES ('node_1', 'General', 'महाराष्ट्र राज्याची सागरी किनारपट्टी किती किलोमीटर लांबीची आहे?', '६५० किमी', '७२० किमी', '८०० किमी', '८५० किमी', 'B', 'महाराष्ट्राला पश्चिमेस अरबी समुद्राचा सुमारे ७२० किलोमीटर लांबीचा विस्तृत समुद्रकिनारा लाभला आहे.');
INSERT INTO public.questions (subject_tag, subtopic_tag, question_text, option_a, option_b, option_c, option_d, correct_option, explanation) VALUES ('node_1', 'General', '''घोडा'' या शब्दाचे लिंग बदला.', 'घोडी', 'घोडं', 'घोडे', 'घोड्या', 'A', '''घोडा'' या पुल्लिंगी शब्दाचे स्त्रीलिंगी रूप ''घोडी'' असे होते.');
INSERT INTO public.questions (subject_tag, subtopic_tag, question_text, option_a, option_b, option_c, option_d, correct_option, explanation) VALUES ('node_1', 'General', 'महाराष्ट्रात ''आनंदवन'' ही संस्था कोणी स्थापन केली?', 'विनोबा भावे', 'बाबा आमटे', 'गाडगेबाबा', 'डॉ. अभय बंग', 'B', 'कुष्ठरोग्यांच्या सेवेसाठी आणि पुनर्वसनासाठी बाबा आमटे यांनी वरोरा (चंद्रपूर) येथे आनंदवनची स्थापना केली.');
INSERT INTO public.questions (subject_tag, subtopic_tag, question_text, option_a, option_b, option_c, option_d, correct_option, explanation) VALUES ('node_1', 'General', '''माहितीचा अधिकार'' (RTI) कायदा भारतात कधी लागू झाला?', '२००१', '२००५', '२००८', '२०१०', 'B', 'माहितीचा अधिकार अधिनियम १२ ऑक्टोबर २००५ पासून संपूर्ण भारतात लागू करण्यात आला.');
INSERT INTO public.questions (subject_tag, subtopic_tag, question_text, option_a, option_b, option_c, option_d, correct_option, explanation) VALUES ('node_1', 'General', 'विमानाचा शोध खालीलपैकी कोणी लावला?', 'थॉमस एडिसन', 'राईट बंधू', 'गॅलिलिओ', 'अॅलेक्झांडर ग्रॅहम बेल', 'B', 'ऑर्व्हिल आणि विल्बर राईट (राईट बंधू) यांनी १९०३ मध्ये यशस्वी विमानाचा शोध लावला.');
INSERT INTO public.questions (subject_tag, subtopic_tag, question_text, option_a, option_b, option_c, option_d, correct_option, explanation) VALUES ('node_1', 'General', 'एक सायकल ₹२००० ला खरेदी करून ₹२४०० ला विकली, तर शेकडा नफा किती?', '१०%', '१५%', '२०%', '२५%', 'C', 'नफा = ४०० रुपये. शेकडा नफा = (४०० / २०००) × १०० = २०%.');
INSERT INTO public.questions (subject_tag, subtopic_tag, question_text, option_a, option_b, option_c, option_d, correct_option, explanation) VALUES ('node_1', 'General', 'महाराष्ट्र राज्याचे सध्याचे गृहमंत्री कोण आहेत?', 'एकनाथ शिंदे', 'देवेंद्र फडणवीस', 'अजित पवार', 'शरद पवार', 'B', 'महाराष्ट्राचे गृह मंत्रालय देवेंद्र फडणवीस यांच्याकडे आहे.');
INSERT INTO public.questions (subject_tag, subtopic_tag, question_text, option_a, option_b, option_c, option_d, correct_option, explanation) VALUES ('node_1', 'General', 'महाराष्ट्रातील पहिली महिला पोलीस महासंचालक (DGP) कोण ठरल्या?', 'रश्मी शुक्ला', 'मीरा बोरवणकर', 'कांचन चौधरी', 'मंजिरी जारुहार', 'A', 'रश्मी शुक्ला या महाराष्ट्र पोलीस दलाच्या पहिल्या महिला पोलीस महासंचालक बनल्या.');
INSERT INTO public.questions (subject_tag, subtopic_tag, question_text, option_a, option_b, option_c, option_d, correct_option, explanation) VALUES ('node_1', 'General', '०.३६ चे घनमूळ किंवा वर्गमूळ काढा: √०.३६ = ?', '०.६', '०.०६', '६', '०.६६', 'A', '३६ चे वर्गमूळ ६ येते, त्यामुळे ०.३६ चे वर्गमूळ ०.६ होईल (०.६ × ०.६ = ०.३६).');
INSERT INTO public.questions (subject_tag, subtopic_tag, question_text, option_a, option_b, option_c, option_d, correct_option, explanation) VALUES ('node_1', 'General', 'एका रांगेत मध्यभागी उभा असलेल्या मुलाचा दोन्ही बाजूंकडून १५ वा क्रमांक आहे, तर रांगेत एकूण किती मुले आहेत?', '२९', '३०', '३१', '२८', 'A', 'एकूण मुले = (१५ × २) - १ = ३० - १ = २९.');
INSERT INTO public.questions (subject_tag, subtopic_tag, question_text, option_a, option_b, option_c, option_d, correct_option, explanation) VALUES ('node_1', 'General', 'भारताची पहिली महिला राष्ट्रपती कोण होत्या?', 'प्रतिभाताई पाटील', 'द्रौपदी मुर्मू', 'इंदिरा गांधी', 'सरोजिनी नायडू', 'A', 'श्रीमती प्रतिभाताई पाटील यांनी २००७ ते २०१२ या कालावधीत भारताच्या पहिल्या महिला राष्ट्रपती म्हणून पद भूषवले.');
INSERT INTO public.questions (subject_tag, subtopic_tag, question_text, option_a, option_b, option_c, option_d, correct_option, explanation) VALUES ('node_1', 'General', 'जर झाडाला पक्षी म्हटले, पक्ष्याला प्राणी म्हटले आणि प्राण्याला जलचर म्हटले, तर आकाशात काय उडेल?', 'झाड', 'पक्षी', 'प्राणी', 'जलचर', 'C', 'आकाशात पक्षी उडतात आणि या कोडिंगनुसार पक्ष्याला ''प्राणी'' म्हटले आहे.');
INSERT INTO public.questions (subject_tag, subtopic_tag, question_text, option_a, option_b, option_c, option_d, correct_option, explanation) VALUES ('node_1', 'General', 'मालिकेतील चुकीचे पद ओळखा: २, ५, १०, १७, २६, ३७, ५०, ६४', '२६', '३७', '५०', '६४', 'D', 'नियम: n² + 1 (1²+1=2, 2²+1=5... 8²+1=65 असणे आवश्यक होते, परंतु ६४ दिले आहे).');
INSERT INTO public.questions (subject_tag, subtopic_tag, question_text, option_a, option_b, option_c, option_d, correct_option, explanation) VALUES ('node_1', 'General', 'एका आयताची लांबी १२ सेमी व रुंदी ५ सेमी आहे, तर त्याच्या कर्णाची (Diagonal) लांबी किती?', '१३ सेमी', '१५ सेमी', '१७ सेमी', '१० सेमी', 'A', 'पायथागोरस सिद्धांतानुसार: कर्ण² = १२² + ५² = १४४ + २५ = १६९. कर्ण = √१६९ = १३ सेमी.');
INSERT INTO public.questions (subject_tag, subtopic_tag, question_text, option_a, option_b, option_c, option_d, correct_option, explanation) VALUES ('node_1', 'General', '''तो धावत गेला.'' या वाक्यातील क्रियापदाचा प्रकार कोणता?', 'सकर्मक क्रियापद', 'अकर्मक क्रियापद', 'संयुक्त क्रियापद', 'प्रयोजक क्रियापद', 'C', '''धावत'' हे धातुसाधित आणि ''गेला'' हे साहाय्यक क्रियापद मिळून ''धावत गेला'' हे संयुक्त क्रियापद तयार होते.');
INSERT INTO public.questions (subject_tag, subtopic_tag, question_text, option_a, option_b, option_c, option_d, correct_option, explanation) VALUES ('node_1', 'General', 'महाराष्ट्र पोलीस दलाचे सर्वोच्च पद कोणते आहे?', 'पोलीस आयुक्त (CP)', 'विशेष पोलीस महानिरीक्षक (IGP)', 'पोलीस महासंचालक (DGP)', 'पोलीस अधीक्षक (SP)', 'C', 'महाराष्ट्र पोलीस दलाचे प्रमुख अधिकारी हे ''पोलीस महासंचालक'' (Director General of Police) असतात.');
INSERT INTO public.questions (subject_tag, subtopic_tag, question_text, option_a, option_b, option_c, option_d, correct_option, explanation) VALUES ('node_1', 'General', '''डोळे झाकणे'' या वाक्प्रचाराचा योग्य अर्थ काय?', 'झोप घेणे', 'दुर्लक्ष करणे', 'काळजी घेणे', 'डोळे मिटून बसणे', 'B', '''डोळे झाकणे'' म्हणजे एखाद्या बाबीकडे किंवा घटनेकडे जाणूनबुजून दुर्लक्ष करणे.');
INSERT INTO public.questions (subject_tag, subtopic_tag, question_text, option_a, option_b, option_c, option_d, correct_option, explanation) VALUES ('node_1', 'General', 'ताशी ९० किमी वेगाने जाणारी ट्रेन एका बोगद्याला ४० सेकंदात पार करते, तर बोगद्याची लांबी किती मीटर असेल? (ट्रेनची लांबी नगण्य मानल्यास)', '८०० मी', '९०० मी', '१०२० मी', '१००० मी', 'D', 'वेग = ९० × ५/१८ = २५ मी/से. लांबी (अंतर) = २५ × ४० = १००० मीटर.');
INSERT INTO public.questions (subject_tag, subtopic_tag, question_text, option_a, option_b, option_c, option_d, correct_option, explanation) VALUES ('node_1', 'General', 'एक व्यक्ती पूर्वेकडे ५ किमी चालते, नंतर उजवीकडे वळून १२ किमी चालते. तर ती सुरुवातीच्या ठिकाणापासून किती अंतरावर आहे?', '१३ किमी', '१५ किमी', '१७ किमी', '१० किमी', 'A', 'पायथागोरस सिद्धांत: √(५² + १२²) = √(२५ + १४४) = √१६९ = १३ किमी.');
INSERT INTO public.questions (subject_tag, subtopic_tag, question_text, option_a, option_b, option_c, option_d, correct_option, explanation) VALUES ('node_1', 'General', 'रमेश पश्चिमेकडे ५ किमी गेला, नंतर डावीकडे वळून १२ किमी चालला. तर तो मूळ स्थानापासून किती अंतरावर आहे?', '१३ किमी', '१७ किमी', '१० किमी', '१५ किमी', 'A', 'पायथागोरसच्या सिद्धांतानुसार: अंतर² = ५² + १२² = २५ + १४४ = १६९. वर्गमूळ काढल्यास अंतर = १३ किमी.');
INSERT INTO public.questions (subject_tag, subtopic_tag, question_text, option_a, option_b, option_c, option_d, correct_option, explanation) VALUES ('node_1', 'General', '४५० चे ४०% = किती?', '१६०', '१८०', '२००', '२१०', 'B', '(४५० × ४०) / १०० = १८००० / १०० = १८०.');
INSERT INTO public.questions (subject_tag, subtopic_tag, question_text, option_a, option_b, option_c, option_d, correct_option, explanation) VALUES ('node_1', 'General', 'महाराष्ट्र राज्याची स्थापना कधी झाली?', '१ मे १९६०', '१५ ऑगस्ट १९४७', '२६ जानेवारी १९५०', '१ मे १९५५', 'A', '१ मे १९६० रोजी द्विभाषिक मुंबई राज्याचे विभाजन होऊन स्वतंत्र महाराष्ट्र राज्य अस्तित्वात आले.');
INSERT INTO public.questions (subject_tag, subtopic_tag, question_text, option_a, option_b, option_c, option_d, correct_option, explanation) VALUES ('node_1', 'General', '५०० चे ३०% = किती?', '१००', '१२०', '१५०', '२००', 'C', '(५०० × ३०) / १०० = १५०.');
INSERT INTO public.questions (subject_tag, subtopic_tag, question_text, option_a, option_b, option_c, option_d, correct_option, explanation) VALUES ('node_1', 'General', '''नयन'' या शब्दाचा समानार्थी शब्द कोणता नाही?', 'लोचन', 'चक्षू', 'नेत्र', 'कर्ण', 'D', 'लोचन, चक्षू आणि नेत्र हे सर्व डोळ्याचे समानार्थी शब्द आहेत, तर ''कर्ण'' म्हणजे कान.');
INSERT INTO public.questions (subject_tag, subtopic_tag, question_text, option_a, option_b, option_c, option_d, correct_option, explanation) VALUES ('node_1', 'General', '''क्षणोक्षणी'' हा शब्द कोणत्या समासाचे उदाहरण आहे?', 'अव्ययीभाव समास', 'तत्पुरुष समास', 'द्वंद्व समास', 'बहुव्रीही समास', 'A', 'ज्या समासातील पहिले पद महत्त्वाचे असते आणि शब्दाची निरुक्ती/द्विरुक्ती होऊन क्रियाविशेषणासारखा वापर होतो, त्याला अव्ययीभाव समास म्हणतात.');
INSERT INTO public.questions (subject_tag, subtopic_tag, question_text, option_a, option_b, option_c, option_d, correct_option, explanation) VALUES ('node_1', 'General', 'महाराष्ट्र राज्य महिला आयोगाचे मुख्यालय कोठे आहे?', 'पुणे', 'नागपूर', 'मुंबई', 'नाशिक', 'C', 'महाराष्ट्र राज्य महिला आयोगाचे मुख्य कार्यालय मुंबई येथे स्थित आहे.');
INSERT INTO public.questions (subject_tag, subtopic_tag, question_text, option_a, option_b, option_c, option_d, correct_option, explanation) VALUES ('node_1', 'General', 'महाराष्ट्रात कोणत्या भागात सर्वाधिक पाऊस पडतो?', 'आंबोली', 'महाबळेश्वर', 'माथेरान', 'लोणावळा', 'A', 'सिंधुदुर्ग जिल्ह्यातील ''आंबोली'' या ठिकाणी महाराष्ट्रात सर्वाधिक पाऊस नोंदवला जातो.');
INSERT INTO public.questions (subject_tag, subtopic_tag, question_text, option_a, option_b, option_c, option_d, correct_option, explanation) VALUES ('node_1', 'General', 'दोन संख्यांचे गुणोत्तर ३:५ आहे व त्यांची बेरीज ८० आहे, तर लहान संख्या कोणती?', '३०', '५०', '२०', '४०', 'A', 'एकूण भाग = ३ + ५ = ८. १ भाग = ८० / ८ = १०. लहान संख्या = ३ × १० = ३०.');
INSERT INTO public.questions (subject_tag, subtopic_tag, question_text, option_a, option_b, option_c, option_d, correct_option, explanation) VALUES ('node_1', 'General', 'एक गाडी ताशी ६० किमी वेगाने जाते, तर ३ तासांत ती किती अंतर कापेल?', '१२० किमी', '१५० किमी', '१८० किमी', '२०० किमी', 'C', 'अंतर = वेग × वेळ. त्यामुळे अंतर = ६० × ३ = १८० किमी.');
INSERT INTO public.questions (subject_tag, subtopic_tag, question_text, option_a, option_b, option_c, option_d, correct_option, explanation) VALUES ('node_1', 'General', 'महाराष्ट्रातील ''राधानगरी'' अभयारण्य कशासाठी प्रसिद्ध आहे?', 'वाघ', 'गवा (बिझोन)', 'हत्ती', 'शेकरू', 'B', 'कोल्हापूर जिल्ह्यातील राधानगरी अभयारण्य गव्यांसाठी (Indian Bison) अत्यंत प्रसिद्ध आहे.');
INSERT INTO public.questions (subject_tag, subtopic_tag, question_text, option_a, option_b, option_c, option_d, correct_option, explanation) VALUES ('node_1', 'General', 'घड्याळात ९:०० वाजता तासकाटा आणि मिनिटकाटा यांच्यात कोणता कोन तयार होतो?', 'लघुकोन', 'काटकोन', 'विशालकोन', 'सरळकोन', 'B', '९ वाजता तासकाटा ९ वर आणि मिनिटकाटा १२ वर असतो, ज्यामुळे अचूक ९० अंशाचा (काटकोन) कोन बनतो.');
INSERT INTO public.questions (subject_tag, subtopic_tag, question_text, option_a, option_b, option_c, option_d, correct_option, explanation) VALUES ('node_1', 'General', '''जालियनवाला बाग'' हत्याकांड कोणत्या शहरात घडले?', 'लाहोर', 'अमृतसर', 'जालंधर', 'दिल्ली', 'B', '१३ एप्रिल १९१९ रोजी पंजाबमधील अमृतसर येथील जालियनवाला बागेत जनरल डायरने निशस्त्र लोकांवर गोळीबार घडवला.');
INSERT INTO public.questions (subject_tag, subtopic_tag, question_text, option_a, option_b, option_c, option_d, correct_option, explanation) VALUES ('node_2', 'General', '''पांढरे केस असलेली स्त्री'' या शब्दसमूहासाठी एक शब्द ओळखा.', 'केशिनी', 'कपिला', 'पलिता', 'श्वेतकेशी', 'D', 'पांढऱ्या केसाइतका अर्थ असणारा शब्द ''श्वेतकेशी'' असा होतो.');
INSERT INTO public.questions (subject_tag, subtopic_tag, question_text, option_a, option_b, option_c, option_d, correct_option, explanation) VALUES ('node_2', 'General', 'समानार्थी शब्द ओळखा: ''चंद्र'' = ?', 'शशांक', 'दिवाकर', 'भास्कर', 'रवी', 'A', 'शशांक, सोम, इंदू हे चंद्राचे समानार्थी शब्द आहेत; तर दिवाकर, भास्कर, रवी हे सूर्याचे शब्द आहेत.');
INSERT INTO public.questions (subject_tag, subtopic_tag, question_text, option_a, option_b, option_c, option_d, correct_option, explanation) VALUES ('node_2', 'General', '६०० रुपयांच्या मुदलाचे ताशी ८% दराने ३ वर्षांचे सरळव्याज किती?', '१२० रुपये', '१४४ रुपये', '१५० रुपये', '१६० रुपये', 'B', 'सरळव्याज = (६०० × ८ × ३) / १०० = १४४ रुपये.');
INSERT INTO public.questions (subject_tag, subtopic_tag, question_text, option_a, option_b, option_c, option_d, correct_option, explanation) VALUES ('node_2', 'General', '''वाघ'' या शब्दाचे स्त्रीलिंगी रूप काय होईल?', 'वाघीण', 'वाघी', 'वाघ्या', 'वाघीणबाई', 'A', '''वाघ'' या पुल्लिंगी नामाचे स्त्रीलिंगी रूप ''वाघीण'' असे होते.');
INSERT INTO public.questions (subject_tag, subtopic_tag, question_text, option_a, option_b, option_c, option_d, correct_option, explanation) VALUES ('node_2', 'General', 'जिल्हा परिषदेचा मुख्य कार्यकारी अधिकारी (CEO) कोणत्या सेवेतील अधिकारी असतो?', 'MPSC', 'IAS', 'IPS', 'IFS', 'B', 'जिल्हा परिषदेचा मुख्य कार्यकारी अधिकारी हा भारतीय प्रशासकीय सेवेतील (IAS) वरिष्ठ अधिकारी असतो.');
INSERT INTO public.questions (subject_tag, subtopic_tag, question_text, option_a, option_b, option_c, option_d, correct_option, explanation) VALUES ('node_2', 'General', '८० किलोमीटर प्रतितास या वेगाने जाणारी ट्रेन २४० किमी अंतर किती वेळात पार करेल?', '२ तास', '३ तास', '४ तास', '५ तास', 'B', 'वेळ = अंतर / वेग = २४० / ८० = ३ तास.');
INSERT INTO public.questions (subject_tag, subtopic_tag, question_text, option_a, option_b, option_c, option_d, correct_option, explanation) VALUES ('node_2', 'General', '''ज्याची काठी त्याची म्हैस'' या म्हणीतील सर्वनामांचा प्रकार कोणता?', 'संबंधी सर्वनाम', 'दर्शक सर्वनाम', 'आत्मवाचक सर्वनाम', 'पुरुषवाचक सर्वनाम', 'A', 'ज्याची-त्याची ही पुढे येणाऱ्या दर्शक सर्वनामाशी संबंध दाखवणारी संबंधी सर्वनामे आहेत.');
INSERT INTO public.questions (subject_tag, subtopic_tag, question_text, option_a, option_b, option_c, option_d, correct_option, explanation) VALUES ('node_2', 'General', 'रांगेत अमरचा दोन्ही बाजूंकडून १० वा क्रमांक आहे, तर रांगेत एकूण किती लोक आहेत?', '१८', '१९', '२०', '२१', 'B', 'एकूण = (१० × २) - १ = २० - १ = १९.');
INSERT INTO public.questions (subject_tag, subtopic_tag, question_text, option_a, option_b, option_c, option_d, correct_option, explanation) VALUES ('node_2', 'General', 'जर आज गुरुवार आहे, तर ५० दिवसांनंतर कोणता वार असेल?', 'शुक्रवार', 'शनिवार', 'रविवार', 'सोमवार', 'A', '५० ला ७ ने भागल्यास बाकी १ उरते. गुरुवार + १ दिवस = शुक्रवार.');
INSERT INTO public.questions (subject_tag, subtopic_tag, question_text, option_a, option_b, option_c, option_d, correct_option, explanation) VALUES ('node_2', 'General', 'रेड क्रॉस (Red Cross) या आंतरराष्ट्रीय संस्थेचे मुख्यालय कोठे आहे?', 'जेनेव्हा', 'पॅरिस', 'न्यू यॉर्क', 'लंडन', 'A', 'रेड क्रॉस या जागतिक सेवाभावी संस्थेचे मुख्यालय जेनेव्हा (स्वित्झर्लंड) येथे आहे.');
INSERT INTO public.questions (subject_tag, subtopic_tag, question_text, option_a, option_b, option_c, option_d, correct_option, explanation) VALUES ('node_2', 'General', 'अ हा ब चा भाऊ आहे. क ही अ ची आई आहे. तर क ही ब ची कोण?', 'मावशी', 'आई', 'आजी', 'बहीण', 'B', 'अ आणि ब भाऊ आहेत, त्यामुळे अ ची आई ही ब ची सुद्धा ''आई'' असेल.');
INSERT INTO public.questions (subject_tag, subtopic_tag, question_text, option_a, option_b, option_c, option_d, correct_option, explanation) VALUES ('node_2', 'General', 'महाराष्ट्रातील उच्च न्यायालय कोठे स्थित आहे?', 'पुणे', 'नागपूर', 'मुंबई', 'छत्रपती संभाजीनगर', 'C', 'महाराष्ट्र व गोवा या दोन राज्यांसाठी मुंबई येथे मुख्य उच्च न्यायालय आहे (नागपूर, छत्रपती संभाजीनगर व पणजी येथे खंडपीठे आहेत).');
INSERT INTO public.questions (subject_tag, subtopic_tag, question_text, option_a, option_b, option_c, option_d, correct_option, explanation) VALUES ('node_2', 'General', 'पोलिओ हा आजार कशामुळे होतो?', 'जिवाणू (Bacteria)', 'विषाणू (Virus)', 'कवक (Fungus)', 'परजीवी', 'B', 'पोलिओ हा पोलिओव्हायरस नावाच्या विषाणूमुळे होणारा संसर्गजन्य रोग आहे.');
INSERT INTO public.questions (subject_tag, subtopic_tag, question_text, option_a, option_b, option_c, option_d, correct_option, explanation) VALUES ('node_2', 'General', '''मराठी भाषा गौरव दिन'' कोणत्या दिवशी साजरा केला जातो?', '१ मे', '२७ फेब्रुवारी', '१५ ऑगस्ट', '२६ जानेवारी', 'B', 'जेष्ठ कवी कुसुमाग्रज (वि. वा. शिरवाडकर) यांच्या जन्मदिवशी २७ फेब्रुवारीला मराठी भाषा गौरव दिन साजरा केला जातो.');
INSERT INTO public.questions (subject_tag, subtopic_tag, question_text, option_a, option_b, option_c, option_d, correct_option, explanation) VALUES ('node_2', 'General', '''मराठी भाषेचे शिवाजी'' असे कोणाला म्हटले जाते?', 'विष्णूशास्त्री चिपळूणकर', 'दादोबा पांडुरंग तर्खडकर', 'बाळशास्त्री जांभेकर', 'कृष्णशास्त्री चिपळूणकर', 'A', 'मराठी भाषेच्या समृद्धीसाठी आणि प्रसारासाठी दिलेल्या योगदानामुळे विष्णूशास्त्री चिपळूणकर यांना ''मराठी भाषेचे शिवाजी'' म्हटले जाते.');
INSERT INTO public.questions (subject_tag, subtopic_tag, question_text, option_a, option_b, option_c, option_d, correct_option, explanation) VALUES ('node_2', 'General', 'महाराष्ट्रात गुप्तवार्ता प्रबोधिनी (State Intelligence Academy) कोठे स्थित आहे?', 'मुंबई', 'नागपूर', 'पुणे', 'नाशिक', 'C', 'महाराष्ट्र राज्याची गुप्तवार्ता प्रबोधिनी (SIA) पुणे येथे स्थित आहे.');
INSERT INTO public.questions (subject_tag, subtopic_tag, question_text, option_a, option_b, option_c, option_d, correct_option, explanation) VALUES ('node_2', 'General', 'मालिकेतील गहाळ पद शोधा: A, C, E, G, ?', 'H', 'I', 'J', 'K', 'B', 'प्रत्येक अक्षरामध्ये एक अक्षर सोडून ( +२ चा फरक ) पुढील अक्षर येत आहे: A(+2)C(+2)E(+2)G(+2)I.');
INSERT INTO public.questions (subject_tag, subtopic_tag, question_text, option_a, option_b, option_c, option_d, correct_option, explanation) VALUES ('node_2', 'General', '''विद्वान'' या शब्दाचे स्त्रीलिंगी रूप काय होईल?', 'विदुषी', 'विद्वानी', 'विद्वत्ता', 'विद्विनी', 'A', '''विद्वान'' या पुल्लिंगी शब्दाचे स्त्रीलिंगी रूप ''विदुषी'' असे होते.');
INSERT INTO public.questions (subject_tag, subtopic_tag, question_text, option_a, option_b, option_c, option_d, correct_option, explanation) VALUES ('node_2', 'General', 'भारताच्या संविधानात एकूण किती अनुसूची (Schedules) आहेत?', '१०', '१२', '८', '१४', 'B', 'मूळ राज्यघटनेत ८ अनुसूची होत्या, परंतु विविध घटनादुरुस्तींद्वारे सध्या १२ अनुसूची आहेत.');
INSERT INTO public.questions (subject_tag, subtopic_tag, question_text, option_a, option_b, option_c, option_d, correct_option, explanation) VALUES ('node_2', 'General', '''ययाती'' या प्रसिद्ध कादंबरीचे लेखक कोण आहेत?', 'वि. स. खांडेकर', 'वपु काळे', 'रणजित देसाई', 'शिवाजी सावंत', 'A', 'मराठीला पहिले ज्ञानपीठ पारितोषिक मिळवून देणाऱ्या ''ययाती'' कादंबरीचे लेखक विष्णू सखाराम खांडेकर आहेत.');
INSERT INTO public.questions (subject_tag, subtopic_tag, question_text, option_a, option_b, option_c, option_d, correct_option, explanation) VALUES ('node_2', 'General', 'मराठी भाषेची लिपी कोणती आहे?', 'देवनागरी', 'रोमन', 'फारसी', 'गुरुमुखी', 'A', 'मराठी भाषा बाळबोध म्हणजेच ''देवनागरी'' लिपीत लिहिली जाते.');
INSERT INTO public.questions (subject_tag, subtopic_tag, question_text, option_a, option_b, option_c, option_d, correct_option, explanation) VALUES ('node_2', 'General', 'भारतातील पहिल्या महिला राष्ट्रपती कोण होत्या?', 'इंदिरा गांधी', 'प्रतिभाताई पाटील', 'द्रौपदी मुर्मू', 'सरोजिनी नायडू', 'B', 'श्रीमती प्रतिभाताई पाटील या २००७ ते २०१२ या काळात भारताच्या पहिल्या महिला राष्ट्रपती होत्या.');
INSERT INTO public.questions (subject_tag, subtopic_tag, question_text, option_a, option_b, option_c, option_d, correct_option, explanation) VALUES ('node_2', 'General', '''कान देऊन ऐकणे'' या वाक्प्रचाराचा अर्थ काय?', 'लक्षपूर्वक ऐकणे', 'कान दुखणे', 'हळूच ऐकणे', 'दुर्लक्ष करणे', 'A', 'एखादी गोष्ट अत्यंत एकाग्रतेने आणि लक्ष देऊन ऐकणे म्हणजेच ''कान देऊन ऐकणे''.');
INSERT INTO public.questions (subject_tag, subtopic_tag, question_text, option_a, option_b, option_c, option_d, correct_option, explanation) VALUES ('node_2', 'General', '१ ते ५० मधील सर्व मूळ संख्यांची (Prime Numbers) एकूण संख्या किती आहे?', '१०', '१२', '१५', '२०', 'C', '१ ते ५० दरम्यान एकूण १५ मूळ संख्या आहेत (२, ३, ५, ७, ११, १३, १७, १९, २३, २९, ३१, ३७, ४१, ४३, ४७).');
INSERT INTO public.questions (subject_tag, subtopic_tag, question_text, option_a, option_b, option_c, option_d, correct_option, explanation) VALUES ('node_2', 'General', 'खालीलपैकी ''विष्णु वामन शिरवाडकर'' यांचे टोपणनाव काय आहे?', 'बालकवी', 'कुसुमाग्रज', 'केशवसूत', 'गोविंदाग्रज', 'B', 'ज्ञानपीठ पुरस्कार विजेते कवी विष्णु वामन शिरवाडकर यांचे टोपणनाव ''कुसुमाग्रज'' हे आहे.');
INSERT INTO public.questions (subject_tag, subtopic_tag, question_text, option_a, option_b, option_c, option_d, correct_option, explanation) VALUES ('node_2', 'General', 'सूर्यप्रकाशापासून मानवी शरीराला कोणते जीवनसत्त्व मिळते?', 'जीवनसत्त्व A', 'जीवनसत्त्व B', 'जीवनसत्त्व C', 'जीवनसत्त्व D', 'D', 'सकाळच्या कोवळ्या ऊन्हामुळे त्वचेखाली जीवनसत्त्व ''डी'' (Vitamin D) तयार होते.');
INSERT INTO public.questions (subject_tag, subtopic_tag, question_text, option_a, option_b, option_c, option_d, correct_option, explanation) VALUES ('node_2', 'General', 'जिल्हा स्तरावर कायदा व सुव्यवस्था राखण्याची अंतिम जबाबदारी कोणाची असते?', 'जिल्हा पोलीस अधीक्षक (SP)', 'जिल्हाधिकारी (District Collector)', 'मुख्य कार्यकारी अधिकारी (CEO)', 'तहसीलदार', 'B', 'जिल्हा दंडाधिकारी (District Magistrate) या नात्याने जिल्हाधिकारी हे जिल्ह्यातील कायदा व सुव्यवस्थेचे प्रमुख असतात.');
INSERT INTO public.questions (subject_tag, subtopic_tag, question_text, option_a, option_b, option_c, option_d, correct_option, explanation) VALUES ('node_2', 'General', 'महाराष्ट्र पोलीस अकादमी (MPA) कोठे स्थित आहे?', 'पुणे', 'मुंबई', 'नाशिक', 'नागपूर', 'C', 'महाराष्ट्र पोलीस अधिकारी उपनिरीक्षक व इतर पोलीस अधिकाऱ्यांच्या प्रशिक्षणासाठी प्रसिद्ध असलेली महाराष्ट्र पोलीस अकादमी नाशिक येथे आहे.');
INSERT INTO public.questions (subject_tag, subtopic_tag, question_text, option_a, option_b, option_c, option_d, correct_option, explanation) VALUES ('node_2', 'General', 'गाडीचा ताशी वेग ७२ किमी/तास आहे, तर तिचा मीटर/सेकंद मध्ये वेग किती?', '१५ मी/से', '२० मी/से', '२५ मी/से', '३० मी/से', 'B', 'किमी/तास चे मी/से मध्ये रूपांतर करण्यासाठी ५/१८ ने गुणावे: ७२ × (५/१८) = २० मीटर/सेकंद.');
INSERT INTO public.questions (subject_tag, subtopic_tag, question_text, option_a, option_b, option_c, option_d, correct_option, explanation) VALUES ('node_2', 'General', 'महाराष्ट्र पोलीस दलाचे सर्वोच्च पद कोणते आहे?', 'विशेष पोलीस महानिरीक्षक', 'पोलीस महासंचालक (DGP)', 'पोलीस आयुक्त', 'अप्पर पोलीस महासंचालक', 'B', 'पोलीस महासंचालक (Director General of Police - DGP) हे महाराष्ट्र पोलीस दलातील सर्वोच्च पद आहे.');
INSERT INTO public.questions (subject_tag, subtopic_tag, question_text, option_a, option_b, option_c, option_d, correct_option, explanation) VALUES ('node_2', 'General', '१५ वस्तूंची खरेदी किंमत १२ वस्तूंच्या विक्री किंमतीइतकी आहे, तर शेकडा नफा किती?', '२०%', '२५%', '३०%', '१५%', 'B', 'नफा टक्केवारी = [(१५ - १२) / १२] × १०० = (३ / १२) × १०० = २५%.');
INSERT INTO public.questions (subject_tag, subtopic_tag, question_text, option_a, option_b, option_c, option_d, correct_option, explanation) VALUES ('node_2', 'General', '८१ चे वर्गमूळ किती?', '७', '८', '९', '८१', 'C', '९ × ९ = ८१, त्यामुळे √८१ = ९.');
INSERT INTO public.questions (subject_tag, subtopic_tag, question_text, option_a, option_b, option_c, option_d, correct_option, explanation) VALUES ('node_2', 'General', 'एका चौरसाची परिमिती ३६ सेमी आहे, तर त्या चौरसाचे क्षेत्रफळ किती?', '८१ चौ सेमी', '३६ चौ सेमी', '७२ चौ सेमी', '६४ चौ सेमी', 'A', 'चौरसाची बाजू = परिमिती / ४ = ३६ / ४ = ९ सेमी. क्षेत्रफळ = बाजू² = ९ × ९ = ८१ चौ सेमी.');
INSERT INTO public.questions (subject_tag, subtopic_tag, question_text, option_a, option_b, option_c, option_d, correct_option, explanation) VALUES ('node_2', 'General', '''पाणी पाजणे'' या वाक्प्रचाराचा अचूक अर्थ ओळखा.', 'तहान भागवणे', 'पराभव करणे', 'मदत करणे', 'पाण्याचा पुरवठा करणे', 'B', '''पाणी पाजणे'' म्हणजे युद्धात किंवा स्पर्धेत समोरच्या व्यक्तीचा पूर्ण पराभव करणे किंवा तिला नमवणे.');
INSERT INTO public.questions (subject_tag, subtopic_tag, question_text, option_a, option_b, option_c, option_d, correct_option, explanation) VALUES ('node_2', 'General', 'जागतिक आरोग्य दिन (World Health Day) कधी साजरा केला जातो?', '७ एप्रिल', '१ मे', '५ जून', '१ डिसेंबर', 'A', 'जागतिक आरोग्य संघटनेची (WHO) स्थापना ७ एप्रिल १९४८ रोजी झाल्याने दरवर्षी ७ एप्रिल हा जागतिक आरोग्य दिन म्हणून पाळला जातो.');
INSERT INTO public.questions (subject_tag, subtopic_tag, question_text, option_a, option_b, option_c, option_d, correct_option, explanation) VALUES ('node_2', 'General', '''सहोदर'' या शब्दाचा अर्थ काय?', 'सख्खे भाऊ (एकाच उदरातून जन्मलेले)', 'चुलत भाऊ', 'मावस भाऊ', 'मित्र', 'A', '''सह + उदर'' म्हणजेच एकाच आईच्या पोटी जन्म घेतलेले सहोदर (सख्खे भाऊ) असतात.');
INSERT INTO public.questions (subject_tag, subtopic_tag, question_text, option_a, option_b, option_c, option_d, correct_option, explanation) VALUES ('node_2', 'General', 'भारताचे सर्वोच्च न्यायालय कोठे आहे?', 'मुंबई', 'कोलकाता', 'नवी दिल्ली', 'चेन्नई', 'C', 'भारतीय संविधानानुसार देशाचे सर्वोच्च न्यायालय नवी दिल्ली येथे स्थित आहे.');
INSERT INTO public.questions (subject_tag, subtopic_tag, question_text, option_a, option_b, option_c, option_d, correct_option, explanation) VALUES ('node_2', 'General', 'मालिकेतील पुढील संख्या ओळखा: १, ४, ९, १६, २५, ३६, ?', '४०', '४५', '४९', '६४', 'C', 'ही १, २, ३, ४, ५, ६ च्या वर्गांची मालिका आहे. पुढील संख्या ७² = ४९.');
INSERT INTO public.questions (subject_tag, subtopic_tag, question_text, option_a, option_b, option_c, option_d, correct_option, explanation) VALUES ('node_2', 'General', 'स्वतंत्र भारताचे पहिले गृहमंत्री कोण होते?', 'सरदार वल्लभभाई पटेल', 'पंडित नेहरू', 'डॉ. बी. आर. आंबेडकर', 'मौलाना आझाद', 'A', 'भारताच्या संस्थानांचे विलीनीकरण करणारे सरदार वल्लभभाई पटेल हे स्वतंत्र भारताचे पहिले गृहमंत्री होते.');
INSERT INTO public.questions (subject_tag, subtopic_tag, question_text, option_a, option_b, option_c, option_d, correct_option, explanation) VALUES ('node_2', 'General', '४०, ६० आणि १०० यांचा मसावी (HCF) किती?', '१०', '२०', '३०', '४०', 'B', '४०, ६० आणि १०० या तिन्ही संख्यांना भाग जाणारी सर्वात मोठी सामाईक संख्या २० आहे.');
INSERT INTO public.questions (subject_tag, subtopic_tag, question_text, option_a, option_b, option_c, option_d, correct_option, explanation) VALUES ('node_2', 'General', 'जर ताशी ४० किमी वेगाने ५ तास प्रवास केला, तर एकूण अंतर किती पार होईल?', '१५० किमी', '२०० किमी', '२५० किमी', '१८० किमी', 'B', 'अंतर = वेग × वेळ = ४० × ५ = २०० किमी.');
INSERT INTO public.questions (subject_tag, subtopic_tag, question_text, option_a, option_b, option_c, option_d, correct_option, explanation) VALUES ('node_2', 'General', '१५, २० आणि २५ यांचा लसावी (LCM) किती?', '१५०', '३००', '५००', '६०', 'B', '१५, २० आणि २५ ने भाग जाणारी लहानात लहान सामाईक संख्या ३०० आहे. (१५×२०=३००, २०×१५=३००, २५×१२=३००).');
INSERT INTO public.questions (subject_tag, subtopic_tag, question_text, option_a, option_b, option_c, option_d, correct_option, explanation) VALUES ('node_2', 'General', '१५ ऑगस्ट १९४७ रोजी भारत स्वतंत्र झाला, तेव्हा ब्रिटनचे पंतप्रधान कोण होते?', 'विन्स्टन चर्चिल', 'क्लेमेंट अ‍ॅटली', 'रॅम्से मॅकडोनाल्ड', 'लॉर्ड माऊंटबॅटन', 'B', 'भारताच्या स्वातंत्र्याच्या वेळी ब्रिटनचे पंतप्रधान लेबर पार्टीचे क्लेमेंट अ‍ॅटली हे होते.');
INSERT INTO public.questions (subject_tag, subtopic_tag, question_text, option_a, option_b, option_c, option_d, correct_option, explanation) VALUES ('node_2', 'General', '१८५७ च्या स्वांतत्र्यलढ्यात कानपूर येथून उठावाचे नेतृत्व कोणी केले?', 'झाशीची राणी लक्ष्मीबाई', 'नानासाहेब पेशवे', 'कुंवर सिंग', 'बहादूर शाह जफर', 'B', '१८५७ च्या उठावात कानपूरमध्ये नानासाहेब पेशवे आणि तात्या टोपे यांनी नेतृत्व केले होते.');
INSERT INTO public.questions (subject_tag, subtopic_tag, question_text, option_a, option_b, option_c, option_d, correct_option, explanation) VALUES ('node_2', 'General', 'पोलीस पाटलाची नेमणूक कोणत्या कायद्यानुसार केली जाते?', 'महाराष्ट्र ग्राम पोलीस कायदा १९६७', 'महाराष्ट्र पोलीस कायदा १९५१', 'सीआरपीसी', 'आयपीसी', 'A', 'महाराष्ट्र ग्राम पोलीस अधिनियम १९६७ च्या कलमानुसार गावात पोलीस पाटलाची नेमणूक केली जाते.');
INSERT INTO public.questions (subject_tag, subtopic_tag, question_text, option_a, option_b, option_c, option_d, correct_option, explanation) VALUES ('node_2', 'General', 'घड्याळात एका दिवसात (२४ तासांत) तासकाटा आणि मिनिटकाटा किती वेळा एकमेकांवर तंतोतंत येतात (०° कोन)?', '२० वेळा', '२२ वेळा', '२४ वेळा', '४४ वेळा', 'B', 'दर १२ तासांत ११ वेळा, त्यामुळे २४ तासांत दोन्ही काटे २२ वेळा एकमेकांवर येतात.');
INSERT INTO public.questions (subject_tag, subtopic_tag, question_text, option_a, option_b, option_c, option_d, correct_option, explanation) VALUES ('node_2', 'General', 'जर DOG = 26 आणि CAT = 24, तर GOAT = ?', '४२', '४३', '४४', '४५', 'B', 'अक्षरांच्या स्थानांकांची बेरीज: G(7) + O(15) + A(1) + T(20) = 43.');
INSERT INTO public.questions (subject_tag, subtopic_tag, question_text, option_a, option_b, option_c, option_d, correct_option, explanation) VALUES ('node_2', 'General', '१ ते ५० पर्यंतच्या सर्व सम संख्यांची (Even Numbers) बेरीज किती?', '६००', '६५०', '६२५', '५५०', 'B', '१ ते ५० मध्ये एकूण २५ सम संख्या आहेत. बेरीज = n(n+1) = २५ × २६ = ६५०.');
INSERT INTO public.questions (subject_tag, subtopic_tag, question_text, option_a, option_b, option_c, option_d, correct_option, explanation) VALUES ('node_2', 'General', 'उत्तर दिशेकडे तोंड करून उभी असलेली व्यक्ती १८० अंश फिरली, तर तिच्या पाठीमागची दिशा कोणती असेल?', 'दक्षिण', 'उत्तर', 'पूर्व', 'पश्चिम', 'B', '१८० अंश फिरल्याने तिचे तोंड दक्षिणेकडे जाईल, त्यामुळे तिच्या पाठीमागची दिशा ''उत्तर'' असेल.');
INSERT INTO public.questions (subject_tag, subtopic_tag, question_text, option_a, option_b, option_c, option_d, correct_option, explanation) VALUES ('node_2', 'General', '५ चा घन (5³) किती होतो?', '२५', '१२५', '१५', '६२५', 'B', '५ × ५ × ५ = १२५.');
INSERT INTO public.questions (subject_tag, subtopic_tag, question_text, option_a, option_b, option_c, option_d, correct_option, explanation) VALUES ('node_2', 'General', 'लोकायुक्त संस्था स्थापन करणारे भारतातील पहिले राज्य कोणते?', 'महाराष्ट्र', 'राजस्थान', 'कर्नाटक', 'बिहार', 'A', 'महाराष्ट्राने १९७१ मध्ये लोकायुक्त कायद्यान्वये लोकायुक्त संस्था स्थापन केली, जी देशात पहिली ठरली.');
INSERT INTO public.questions (subject_tag, subtopic_tag, question_text, option_a, option_b, option_c, option_d, correct_option, explanation) VALUES ('node_2', 'General', 'एका चौरसाची बाजू १० सेमी असल्यास त्याचे क्षेत्रफळ किती चौरस सेमी होईल?', '२०', '४०', '१००', '२००', 'C', 'चौरसाचे क्षेत्रफळ = बाजू² = १०² = १०० चौ सेमी.');
INSERT INTO public.questions (subject_tag, subtopic_tag, question_text, option_a, option_b, option_c, option_d, correct_option, explanation) VALUES ('node_2', 'General', 'मानवी शरीरात इन्सुलिनच्या कमतरतेमुळे कोणता आजार होतो?', 'उच्च रक्तदाब', 'मधुमेह (Diabetes)', 'अ‍ॅनिमिया', 'गोवर', 'B', 'इन्सुलिनच्या अभावामुळे रक्तातील साखरेचे प्रमाण वाढून मधुमेह हा विकार होतो.');
INSERT INTO public.questions (subject_tag, subtopic_tag, question_text, option_a, option_b, option_c, option_d, correct_option, explanation) VALUES ('node_2', 'General', 'खालीलपैकी ''पृथ्वी'' या शब्दाचा समानार्थी शब्द कोणता?', 'वसुंधरा', 'आकाश', 'पवन', 'गगन', 'A', 'वसुंधरा, धरणी, भूमी हे पृथ्वीचे समानार्थी शब्द आहेत.');
INSERT INTO public.questions (subject_tag, subtopic_tag, question_text, option_a, option_b, option_c, option_d, correct_option, explanation) VALUES ('node_2', 'General', 'जर M = 13 आणि MAT = 34, तर WAX = ?', '४७', '४८', '५०', '५२', 'B', 'वर्णमालेतील स्थानांकांची बेरीज: W(23) + A(1) + X(24) = 48.');
INSERT INTO public.questions (subject_tag, subtopic_tag, question_text, option_a, option_b, option_c, option_d, correct_option, explanation) VALUES ('node_2', 'General', '''सूर्य'' या शब्दाचे भाववाचक नाम काय होईल?', 'सौर्य', 'सूर्योदय', 'तेज', 'सूर्यत्व', 'A', 'व्याकरणानुसार ''सूर्य'' या नामापासून बनणारे भाववाचक नाम ''सौर्य'' (किंवा सूर्यत्व) असे होते.');
INSERT INTO public.questions (subject_tag, subtopic_tag, question_text, option_a, option_b, option_c, option_d, correct_option, explanation) VALUES ('node_2', 'General', 'महाराष्ट्रात ''ताडोबा'' राष्ट्रीय उद्यान कोणत्या जिल्ह्यात आहे?', 'नागपूर', 'चंद्रपूर', 'गडचिरोली', 'अमरावती', 'B', 'ताडोबा अंधारी व्याघ्र प्रकल्प महाराष्ट्र राज्यातील चंद्रपूर जिल्ह्यात स्थित आहे.');
INSERT INTO public.questions (subject_tag, subtopic_tag, question_text, option_a, option_b, option_c, option_d, correct_option, explanation) VALUES ('node_2', 'General', 'भारताच्या केंद्रीय अन्न आणि औषध प्रशासनाची (FDA) चाचणी प्रयोगशाळा महाराष्ट्रात कोठे आहे?', 'पुणे', 'मुंबई', 'नागपूर', 'औरंगाबाद', 'B', 'महाराष्ट्राची प्रमुख अन्न व औषध प्रशासन (FDA) प्रयोगशाळा वांद्रे, मुंबई येथे आहे.');
INSERT INTO public.questions (subject_tag, subtopic_tag, question_text, option_a, option_b, option_c, option_d, correct_option, explanation) VALUES ('node_2', 'General', 'मराठी भाषेचे ''पाणिनी'' कोणाला म्हटले जाते?', 'दादोबा पांडुरंग तर्खडकर', 'विष्णू शास्त्री चिपळूणकर', 'बालशास्त्री जांभेकर', 'कृष्णाजी प्रभाकर खाडिलकर', 'A', 'मराठी व्याकरणाचे पहिले पद्धतशीर पुस्तक लिहिणारे दादोबा पांडुरंग तर्खडकर यांना ''मराठी भाषेचे पाणिनी'' म्हणतात.');
INSERT INTO public.questions (subject_tag, subtopic_tag, question_text, option_a, option_b, option_c, option_d, correct_option, explanation) VALUES ('node_2', 'General', 'नीती आयोगाचे (NITI Aayog) पदसिद्ध अध्यक्ष कोण असतात?', 'राष्ट्रपती', 'गृहमंत्री', 'पंतप्रधान', 'वित्तमंत्री', 'C', 'भारताचे पंतप्रधान हे नीती आयोगाचे पदसिद्ध अध्यक्ष असतात.');
INSERT INTO public.questions (subject_tag, subtopic_tag, question_text, option_a, option_b, option_c, option_d, correct_option, explanation) VALUES ('node_2', 'General', 'महाराष्ट्र पोलीस प्रबोधिनी (Maharashtra Police Academy) कोठे स्थित आहे?', 'पुणे', 'नागपूर', 'नाशिक', 'मुंबई', 'C', 'महाराष्ट्र पोलीस दलातील अधिकाऱ्यांच्या प्रशिक्षणासाठी प्रसिद्ध असलेली ''महाराष्ट्र पोलीस प्रबोधिनी'' (MPA) नाशिक येथे आहे.');
INSERT INTO public.questions (subject_tag, subtopic_tag, question_text, option_a, option_b, option_c, option_d, correct_option, explanation) VALUES ('node_2', 'General', 'गोवा राज्याची राजधानी कोणती आहे?', 'मडगाव', 'पणजी', 'वास्को द गामा', 'मापसा', 'B', 'गोवा राज्याची राजधानी पणजी (Panaji) ही आहे.');
INSERT INTO public.questions (subject_tag, subtopic_tag, question_text, option_a, option_b, option_c, option_d, correct_option, explanation) VALUES ('node_2', 'General', '''राजा'' या शब्दाचे सामान्यरूप काय होईल?', 'राजास', 'राजा', 'राजाने', 'राजी', 'B', 'आ-कारान्त पुल्लिंगी नामाचे सामान्यरूप काही वेळा बदलत नाही, जसे ''राजा'' ला प्रत्यय लावताना ''राजा-'' (उदा. राजास) असेच राहते.');
INSERT INTO public.questions (subject_tag, subtopic_tag, question_text, option_a, option_b, option_c, option_d, correct_option, explanation) VALUES ('node_2', 'General', 'महाराष्ट्रातील ''माथेरान'' हे थंड हवेचे ठिकाण कोणत्या जिल्ह्यात येते?', 'पुणे', 'रायगड', 'ठाणे', 'रत्नागिरी', 'B', 'माथेरान हे गाड्यांना बंदी असलेले निसर्गरम्य थंड हवेचे ठिकाण रायगड जिल्ह्यात आहे.');
INSERT INTO public.questions (subject_tag, subtopic_tag, question_text, option_a, option_b, option_c, option_d, correct_option, explanation) VALUES ('node_2', 'General', '१५० चे २०% + २०० चे १०% = किती?', '४०', '५०', '६०', '७०', 'B', '(१५० × २०/१००) + (२०० × १०/१००) = ३० + २० = ५०.');
INSERT INTO public.questions (subject_tag, subtopic_tag, question_text, option_a, option_b, option_c, option_d, correct_option, explanation) VALUES ('node_2', 'General', 'महाराष्ट्रातील प्रथम महिला मुख्यमंत्री कोण?', 'सुप्रिया सुळे', 'पंकजा मुंडे', 'प्रतिभाताई पाटील', 'महाराष्ट्रात अद्याप महिला मुख्यमंत्री झालेल्या नाहीत', 'D', 'महाराष्ट्राच्या इतिहासात आतापर्यंत एकही महिला मुख्यमंत्री झालेली नाही.');
INSERT INTO public.questions (subject_tag, subtopic_tag, question_text, option_a, option_b, option_c, option_d, correct_option, explanation) VALUES ('node_3', 'General', 'जगातील सर्वात लांब नदी कोणती?', 'अॅमेझॉन', 'नाईल', 'मिसिसिपी', 'गंगा', 'B', 'आफ्रिका खंडातील ''नाईल'' ही जगातील सर्वात जास्त लांबीची नदी मानली जाते.');
INSERT INTO public.questions (subject_tag, subtopic_tag, question_text, option_a, option_b, option_c, option_d, correct_option, explanation) VALUES ('node_3', 'General', 'महाराष्ट्रात ''पोलीस स्मृतिदिन'' कधी पाळला जातो?', '२१ ऑक्टोबर', '२६ नोव्हेंबर', '१५ ऑगस्ट', '२ जानेवारी', 'A', 'लडाख येथे १९५९ मध्ये हुतात्मा झालेल्या CRPF जवानांच्या स्मरणार्थ दरवर्षी २१ ऑक्टोबर हा पोलीस स्मृतिदिन म्हणून पाळला जातो.');
INSERT INTO public.questions (subject_tag, subtopic_tag, question_text, option_a, option_b, option_c, option_d, correct_option, explanation) VALUES ('node_3', 'General', 'मानवी शरीरात रक्ताभिसरण प्रक्रियेचा शोध कोणी लावला?', 'विल्यम हार्वे', 'एडवर्ड जेनर', 'ल्युवेनहॉक', 'रॉबर्ट हूक', 'A', 'इ.स. १६२८ मध्ये ब्रिटीश शास्त्रज्ञ विल्यम हार्वे यांनी मानवी शरीरातील रक्ताभिसरण संस्थेचा शोध लावला.');
INSERT INTO public.questions (subject_tag, subtopic_tag, question_text, option_a, option_b, option_c, option_d, correct_option, explanation) VALUES ('node_3', 'General', '''हात टेकणे'' या वाक्प्रचाराचा अचूक अर्थ ओळखा.', 'मदत मागणे', 'इलाज नसणे / हार मानणे', 'नमस्कार करणे', 'विश्रांती घेणे', 'B', 'उपाय उरला नाही म्हणून नाइलाजाने शरण येणे किंवा हार मानणे म्हणजे ''हात टेकणे''.');
INSERT INTO public.questions (subject_tag, subtopic_tag, question_text, option_a, option_b, option_c, option_d, correct_option, explanation) VALUES ('node_3', 'General', 'भारतातील पहिल्या अणुभट्टीचे नाव काय आहे?', 'रोहिणी', 'अप्सरा', 'भास्करा', 'ध्रुव', 'B', 'तुर्भे, मुंबई येथील भाभा अणुसंशोधन केंद्रात (BARC) १९५६ मध्ये ''अप्सरा'' ही आशियातील पहिली अणुभट्टी सुरू झाली.');
INSERT INTO public.questions (subject_tag, subtopic_tag, question_text, option_a, option_b, option_c, option_d, correct_option, explanation) VALUES ('node_3', 'General', '१२० चे १५% = किती?', '१५', '१८', '२०', '२४', 'B', '(१२० × १५) / १०० = १८०० / १०० = १८.');
INSERT INTO public.questions (subject_tag, subtopic_tag, question_text, option_a, option_b, option_c, option_d, correct_option, explanation) VALUES ('node_3', 'General', 'तासकाटा १ तासात किती अंशाचा कोन पूर्ण करतो?', '१५°', '३०°', '४५°', '६०°', 'B', 'घड्याळातील एकूण ३६०° हे १२ तासांत विभागलेले असतात. त्यामुळे १ तासात तासकाटा (३६०° / १२) = ३०° फिरतो.');
INSERT INTO public.questions (subject_tag, subtopic_tag, question_text, option_a, option_b, option_c, option_d, correct_option, explanation) VALUES ('node_3', 'General', 'दिशेवरील प्रश्न: उत्तर दिशेकडे तोंड करून उभा असलेला माणूस उजवीकडे ९० अंश वळल्यास त्याचे तोंड कोणत्या दिशेला असेल?', 'पश्चिम', 'पूर्व', 'दक्षिण', 'उत्तर-पूर्व', 'B', 'उत्तर दिशेकडून घड्याळाच्या काट्याच्या दिशेने (उजवीकडे) ९० अंश वळल्यास पूर्व दिशा येते.');
INSERT INTO public.questions (subject_tag, subtopic_tag, question_text, option_a, option_b, option_c, option_d, correct_option, explanation) VALUES ('node_3', 'General', 'एका सांकेतिक भाषेत ''BOOK'' ला ''4'' आणि ''PEN'' ला ''3'' लिहिले, तर ''POLICE'' ला काय लिहितील?', '४', '५', '६', '७', 'C', 'शब्दातील एकूण अक्षरांची संख्या कोड म्हणून वापरली आहे. POLICE मध्ये ६ अक्षरे आहेत.');
INSERT INTO public.questions (subject_tag, subtopic_tag, question_text, option_a, option_b, option_c, option_d, correct_option, explanation) VALUES ('node_3', 'General', 'विभागीय आयुक्त (Divisional Commissioner) या पदाची नेमणूक कोणाकडून केली जाते?', 'केंद्र शासन', 'राज्य शासन', 'गृह मंत्रालय', 'उच्च न्यायालय', 'B', 'राज्यातील महसूल विभागाचे प्रमुख म्हणून विभागीय आयुक्तांची नेमणूक महाराष्ट्र राज्य शासनाकडून केली जाते.');
INSERT INTO public.questions (subject_tag, subtopic_tag, question_text, option_a, option_b, option_c, option_d, correct_option, explanation) VALUES ('node_3', 'General', 'विसंगत पद शोधा: सफरचंद, आंबा, केळी, बटाटा', 'सफरचंद', 'आंबा', 'केळी', 'बटाटा', 'D', 'सफरचंद, आंबा आणि केळी ही फळे आहेत, तर बटाटा ही भाजी/कंदमुळे आहे.');
INSERT INTO public.questions (subject_tag, subtopic_tag, question_text, option_a, option_b, option_c, option_d, correct_option, explanation) VALUES ('node_3', 'General', '''राम आंबा खातो.'' या वाक्याचा प्रयोग ओळखा.', 'कर्मणी प्रयोग', 'कर्तरी प्रयोग', 'भावे प्रयोग', 'संकीर्ण प्रयोग', 'B', 'येथे कर्त्याला (राम) प्रत्यय नाही व क्रियापद कर्त्याच्या लिंग-वचनानुसार बदलते, म्हणून हा कर्तरी प्रयोग आहे.');
INSERT INTO public.questions (subject_tag, subtopic_tag, question_text, option_a, option_b, option_c, option_d, correct_option, explanation) VALUES ('node_3', 'General', 'भारताची मुख्य भूमीची सर्वात दक्षिणेकडील टोक (Cap) कोणते?', 'इंदिरा पॉईंट', 'कन्याकुमारी', 'पोर्ट ब्लेअर', 'रामाेश्वरम', 'B', 'भारतीय मुख्य भूमीचे सर्वात दक्षिणेकडील टोक कन्याकुमारी (केप कोमोरिन) हे आहे.');
INSERT INTO public.questions (subject_tag, subtopic_tag, question_text, option_a, option_b, option_c, option_d, correct_option, explanation) VALUES ('node_3', 'General', '''बांदिपूर'' राष्ट्रीय उद्यान कोणत्या राज्यात आहे?', 'महाराष्ट्र', 'कर्नाटक', 'गुजरात', 'तामिळनाडू', 'B', 'प्रसिद्ध बांदिपूर राष्ट्रीय उद्यान दक्षिण भारतातील कर्नाटक राज्यात स्थित आहे.');
INSERT INTO public.questions (subject_tag, subtopic_tag, question_text, option_a, option_b, option_c, option_d, correct_option, explanation) VALUES ('node_3', 'General', 'विसंगत पर्याय ओळखा: १४, २७, ६४, १२५', '१४', '२७', '६४', '१२५', 'A', '२७ (३³), ६४ (४³), १२५ (५³) या घन संख्या आहेत, तर १४ ही घन संख्या नाही.');
INSERT INTO public.questions (subject_tag, subtopic_tag, question_text, option_a, option_b, option_c, option_d, correct_option, explanation) VALUES ('node_3', 'General', '५, १०, १५, २०, २५ यांचा मसावी (HCF) आणि लसावी (LCM) मधील फरक किती?', '२४०', '२९५', '३००', '३०५', 'B', 'मसावी = ५, लसावी = ३००. फरक = ३०० - ५ = २९५.');
INSERT INTO public.questions (subject_tag, subtopic_tag, question_text, option_a, option_b, option_c, option_d, correct_option, explanation) VALUES ('node_3', 'General', 'सहा अंकी लहानात लहान संख्या कोणती?', '९९९९९९', '१०००००', '११११११', '१००००१', 'B', '१ वर ५ शून्ये ठेवून बनणारी ''१०००००'' (एक लाख) ही ६ अंकी लहानात लहान संख्या आहे.');
INSERT INTO public.questions (subject_tag, subtopic_tag, question_text, option_a, option_b, option_c, option_d, correct_option, explanation) VALUES ('node_3', 'General', '''महोत्सव'' या शब्दाची योग्य संधी फोड ओळखा.', 'महा + उत्सव', 'महो + उत्सव', 'महान + उत्सव', 'मह + उत्सव', 'A', 'महा + उत्सव = महोत्सव (आ + उ = ओ ही गुणादेश संधी आहे).');
INSERT INTO public.questions (subject_tag, subtopic_tag, question_text, option_a, option_b, option_c, option_d, correct_option, explanation) VALUES ('node_3', 'General', 'महाराष्ट्रात गुप्तवार्ता प्रबोधिनी (Centre for Police Research) कोठे आहे?', 'पुणे', 'मुंबई', 'नागपूर', 'नाशिक', 'A', 'महाराष्ट्र पोलीस दलाचे गुप्तवार्ता प्रशिक्षण केंद्र आणि पोलीस संशोधन केंद्र (CPR) पाषाण, पुणे येथे स्थित आहे.');
INSERT INTO public.questions (subject_tag, subtopic_tag, question_text, option_a, option_b, option_c, option_d, correct_option, explanation) VALUES ('node_3', 'General', 'एका त्रिकोणाच्या बाजू ५ सेमी, १२ सेमी आणि १३ सेमी आहेत, तर तो कोणता त्रिकोण आहे?', 'समभुज त्रिकोण', 'काटकोन त्रिकोण', 'विशालकोन त्रिकोण', 'समद्विभुज त्रिकोण', 'B', '५² + १२² = २५ + १४४ = १६९ = १३². पायथागोरसच्या त्रिकूटानुसार हा काटकोन त्रिकोण आहे.');
INSERT INTO public.questions (subject_tag, subtopic_tag, question_text, option_a, option_b, option_c, option_d, correct_option, explanation) VALUES ('node_3', 'General', 'जर CAT = 24, तर DOG = ?', '२६', '२६', '२६', '२६', 'A', 'वर्णमालेतील स्थानांकांची बेरीज: C(3) + A(1) + T(20) = 24. त्याचप्रमाणे D(4) + O(15) + G(7) = 26.');
INSERT INTO public.questions (subject_tag, subtopic_tag, question_text, option_a, option_b, option_c, option_d, correct_option, explanation) VALUES ('node_3', 'General', 'मालिकेतील पुढील पद शोधा: ५, १०, १५, २०, ?', '२२', '२५', '३०', '२४', 'B', 'प्रत्येक संख्येत ५ ची भर घातली जात आहे (५ च्या पटीतील संख्या). म्हणून २० + ५ = २५.');
INSERT INTO public.questions (subject_tag, subtopic_tag, question_text, option_a, option_b, option_c, option_d, correct_option, explanation) VALUES ('node_3', 'General', 'भारतातील प्रथम क्रमांकाचे नागरी सन्मान पदक कोणते आहे?', 'पद्मविभूषण', 'पद्मभूषण', 'भारतरत्न', 'परमवीर चक्र', 'C', '''भारतरत्न'' हा भारत सरकारचा सर्वोच्च नागरी पुरस्कार आहे.');
INSERT INTO public.questions (subject_tag, subtopic_tag, question_text, option_a, option_b, option_c, option_d, correct_option, explanation) VALUES ('node_3', 'General', 'महाराष्ट्रातील ''नाशिक'' हे शहर कोणत्या नदीकाठी वसलेले आहे?', 'कृष्णा', 'तापी', 'गोदावरी', 'भीमा', 'C', 'दक्षिण भारताची गंगा मानली जाणारी गोदावरी नदी नाशिक शहरातील त्र्यंबकेश्वर येथून उगम पावते.');
INSERT INTO public.questions (subject_tag, subtopic_tag, question_text, option_a, option_b, option_c, option_d, correct_option, explanation) VALUES ('node_3', 'General', '''विद्वान'' या शब्दाचे स्त्रीलिंगी रूप काय होईल?', 'विदुषी', 'विद्वत्ता', 'विद्वानी', 'विद्या', 'A', 'मराठी व्याकरणानुसार ''विद्वान'' या पुल्लिंगी शब्दाचे स्त्रीलिंगी रूप ''विदुषी'' होते.');
INSERT INTO public.questions (subject_tag, subtopic_tag, question_text, option_a, option_b, option_c, option_d, correct_option, explanation) VALUES ('node_3', 'General', 'जर ४५ x = १३५ असेल, तर x ची किंमत किती?', '२', '३', '४', '५', 'B', 'x = १३५ / ४५ = ३.');
INSERT INTO public.questions (subject_tag, subtopic_tag, question_text, option_a, option_b, option_c, option_d, correct_option, explanation) VALUES ('node_3', 'General', 'घड्याळात ९:३० वाजता दोन्ही काट्यांमध्ये किती अंशाचा कोन असेल?', '९०°', '१०५°', '७५°', '१२०°', 'B', 'सूत्र: |(३० × तास) - (११/२ × मिनिटे)| = |(३० × ९) - (११/२ × ३०)| = |२७० - १६५| = १०५°.');
INSERT INTO public.questions (subject_tag, subtopic_tag, question_text, option_a, option_b, option_c, option_d, correct_option, explanation) VALUES ('node_3', 'General', 'पंचायत राज व्यवस्थेला घटनात्मक दर्जा कोणत्या दुरुस्तीने मिळाला?', '४२ वी दुरुस्ती', '४४ वी दुरुस्ती', '७३ वी दुरुस्ती', '८६ वी दुरुस्ती', 'C', '१९९२ च्या ७३ व्या घटनादुरुस्तीद्वारे पंचायत राज संस्थेला भारतीय संविधानात घटनात्मक दर्जा देण्यात आला.');
INSERT INTO public.questions (subject_tag, subtopic_tag, question_text, option_a, option_b, option_c, option_d, correct_option, explanation) VALUES ('node_3', 'General', 'शुद्ध शब्द ओळखा:', 'उज्ज्वल', 'उज्वल', 'उजवल', 'उज्जवल', 'A', 'मराठी व्याकरणानुसार दोन ''ज'' अर्धे जोडून ''उज्ज्वल'' असा शब्द शुद्ध मानला जातो.');
INSERT INTO public.questions (subject_tag, subtopic_tag, question_text, option_a, option_b, option_c, option_d, correct_option, explanation) VALUES ('node_3', 'General', 'मानवी शरीरातील सर्वात मोठी ग्रंथी (Gland) कोणती?', 'स्वादुपिंड', 'यकृत (Liver)', 'थायरॉईड', 'पिट्युटरी', 'B', 'मानवी शरीरातील सर्वात मोठी ग्रंथी ''यकृत'' (Liver) आहे.');
INSERT INTO public.questions (subject_tag, subtopic_tag, question_text, option_a, option_b, option_c, option_d, correct_option, explanation) VALUES ('node_3', 'General', 'विसंगत घटक ओळखा: २५, ३६, ४९, ६४, ८१, १००, १०५', '६४', '८१', '१००', '१०५', 'D', '१०५ व्यतिरिक्त बाकी सर्व संख्या पूर्ण वर्ग संख्या (Square Numbers) आहेत.');
INSERT INTO public.questions (subject_tag, subtopic_tag, question_text, option_a, option_b, option_c, option_d, correct_option, explanation) VALUES ('node_3', 'General', 'गोदावरी नदीचा उगम महाराष्ट्रातील कोणत्या जिल्ह्यात होतो?', 'अहमदनगर', 'पुणे', 'नाशिक', 'सतारा', 'C', 'दक्षिण भारतातील सर्वात मोठी नदी गोदावरी हिचा उगम नाशिक जिल्ह्यातील त्र्यंबकेश्वर येथे होतो.');
INSERT INTO public.questions (subject_tag, subtopic_tag, question_text, option_a, option_b, option_c, option_d, correct_option, explanation) VALUES ('node_3', 'General', 'विसंगत पद ओळखा: २, ४, ८, १६, ३२, ५०', '१६', '३२', '५०', '८', 'C', 'येथे प्रत्येक संख्या मागील संख्येची दुप्पट आहे (२x२=४, ४x२=८, ८x२=१६, १६x२=३२). त्यामुळे ३२x२ = ६४ यायला हवे होते, पण ५० दिले आहे.');
INSERT INTO public.questions (subject_tag, subtopic_tag, question_text, option_a, option_b, option_c, option_d, correct_option, explanation) VALUES ('node_3', 'General', 'दोन संख्यांचे प्रमाण ३ : ४ आहे आणि त्यांची बेरीज १४० आहे, तर मोठी संख्या कोणती?', '६०', '७०', '८०', '९०', 'C', 'माना ३x + ४x = १४० => ७x = १४० => x = २०. मोठी संख्या = ४ × २० = ८०.');
INSERT INTO public.questions (subject_tag, subtopic_tag, question_text, option_a, option_b, option_c, option_d, correct_option, explanation) VALUES ('node_3', 'General', 'खालीलपैकी विशेषनाम ओळखा.', 'मुलगा', 'नदी', 'हिमालय', 'शहर', 'C', 'मुलगा, नदी आणि शहर ही सामान्यनामे आहेत, तर ''हिमालय'' हे एका विशिष्ट पर्वताचे नाव असल्याने विशेषनाम आहे.');
INSERT INTO public.questions (subject_tag, subtopic_tag, question_text, option_a, option_b, option_c, option_d, correct_option, explanation) VALUES ('node_3', 'General', 'महाराष्ट्रातील ''लोणार'' सरोवर कोणत्या जिल्ह्यात आहे?', 'बुलढाणा', 'अकोला', 'वाशीम', 'जळगाव', 'A', 'बुलढाणा जिल्ह्यातील लोणार सरोवर हे उल्कापातामुळे निर्माण झालेले खऱ्या पाण्याचे प्रसिद्ध सरोवर आहे.');
INSERT INTO public.questions (subject_tag, subtopic_tag, question_text, option_a, option_b, option_c, option_d, correct_option, explanation) VALUES ('node_3', 'General', 'महाराष्ट्राची राजधानी कोणती आहे?', 'पुणे', 'नागपूर', 'मुंबई', 'नाशिक', 'C', 'मुंबई ही महाराष्ट्राची मुख्य राजधानी आहे, तर नागपूर ही उपराजधानी आहे.');
INSERT INTO public.questions (subject_tag, subtopic_tag, question_text, option_a, option_b, option_c, option_d, correct_option, explanation) VALUES ('node_3', 'General', 'भारतातील प्रथम महिला राज्यपाल कोण होत्या?', 'सुचेता कृपलानी', 'सरोजिनी नायडू', 'विजयलक्ष्मी पंडित', 'पद्मजा नायडू', 'B', 'सरोजिनी नायडू या स्वतंत्र भारताच्या उत्तर प्रदेश राज्याच्या पहिल्या महिला राज्यपाल बनल्या.');
INSERT INTO public.questions (subject_tag, subtopic_tag, question_text, option_a, option_b, option_c, option_d, correct_option, explanation) VALUES ('node_3', 'General', 'जगातील सर्वात मोठे महासागर कोणते?', 'अटलांटिक महासागर', 'हिंदी महासागर', 'पॅसिफिक (प्रशांत) महासागर', 'आर्क्टिक महासागर', 'C', 'प्रशांत महासागर (Pacific Ocean) हा पृथ्वीवरील सर्वात मोठा आणि खोल महासागर आहे.');
INSERT INTO public.questions (subject_tag, subtopic_tag, question_text, option_a, option_b, option_c, option_d, correct_option, explanation) VALUES ('node_3', 'General', '''चोर भीतीने थरथर कापत होता.'' या वाक्यातील ''भीतीने'' या शब्दाची विभक्ती ओळखा.', 'द्वितीया', 'तृतीया', 'चतुर्थी', 'पंचमी', 'B', '''ने'' हे प्रत्यय तृतीया विभक्तीचे मुख्य साधन किंवा कारकार्थ दर्शवतात.');
INSERT INTO public.questions (subject_tag, subtopic_tag, question_text, option_a, option_b, option_c, option_d, correct_option, explanation) VALUES ('node_3', 'General', 'लोहित पेशी (RBC) मानवी शरीरात कोठे तयार होतात?', 'हृदय', 'यकृत', 'अस्थिमज्जा (Bone Marrow)', 'मूत्रपिंड', 'C', 'रक्तातील लाल रक्तपेशी (RBCs) हाडांच्या आतील ''अस्थिमज्जा'' (Bone Marrow) या भागात तयार होतात.');
INSERT INTO public.questions (subject_tag, subtopic_tag, question_text, option_a, option_b, option_c, option_d, correct_option, explanation) VALUES ('node_3', 'General', 'विरुद्धार्थी शब्द ओळखा: ''इहलोक'' × ?', 'परलोक', 'देवलोक', 'स्वर्गलोक', 'पाताळलोक', 'A', '''इहलोक'' (आपण जगत असलेले विश्व) या शब्दाचा विरुद्धार्थी शब्द ''परलोक'' असा होतो.');
INSERT INTO public.questions (subject_tag, subtopic_tag, question_text, option_a, option_b, option_c, option_d, correct_option, explanation) VALUES ('node_3', 'General', 'जर MANGO = 50, तर APPLE = ?', '५०', '५०', '५०', '५०', 'A', 'A(1)+P(16)+P(16)+L(12)+E(5) = 50. अक्षरांच्या क्रमांकांची बेरीज ५० येते.');
INSERT INTO public.questions (subject_tag, subtopic_tag, question_text, option_a, option_b, option_c, option_d, correct_option, explanation) VALUES ('node_3', 'General', 'पोलीस दलातील ''FIR'' चा पूर्ण विस्तार (Full Form) काय आहे?', 'First Investigation Report', 'First Information Report', 'Final Investigation Record', 'First Inspection Record', 'B', 'गुन्ह्याबाबत पोलिसांना मिळालेल्या पहिल्या अधिकृत माहितीच्या नोंदीला First Information Report (प्रथम बातमी अहवाल) म्हणतात.');
INSERT INTO public.questions (subject_tag, subtopic_tag, question_text, option_a, option_b, option_c, option_d, correct_option, explanation) VALUES ('node_3', 'General', 'कोल्हापूर शहर कोणत्या नदीच्या काठावर वसलेले आहे?', 'पंचगंगा', 'कृष्णा', 'गोदावरी', 'वारणा', 'A', 'कोल्हापूर हे प्रसिद्ध शहर पंचगंगा नदीच्या काठावर वसलेले आहे.');
INSERT INTO public.questions (subject_tag, subtopic_tag, question_text, option_a, option_b, option_c, option_d, correct_option, explanation) VALUES ('node_3', 'General', 'एका चौरसाची बाजू ८ सेमी आहे, तर त्याचे क्षेत्रफळ किती?', '३२ चौ सेमी', '६४ चौ सेमी', '१६ चौ सेमी', '४८ चौ सेमी', 'B', 'चौरसाचे क्षेत्रफळ = बाजू² = ८ × ८ = ६४ चौ सेमी.');
INSERT INTO public.questions (subject_tag, subtopic_tag, question_text, option_a, option_b, option_c, option_d, correct_option, explanation) VALUES ('node_3', 'General', 'भारताच्या संविधानाचे शिल्पकार कोणास म्हटले जाते?', 'डॉ. सर्वपल्ली राधाकृष्णन', 'डॉ. बाबासाहेब आंबेडकर', 'पंडित जवाहरलाल नेहरू', 'महात्मा गांधी', 'B', 'मसुदा समितीचे अध्यक्ष म्हणून भारतीय संविधान तयार करण्यात मुख्य योगदान दिल्यामुळे डॉ. बाबासाहेब आंबेडकर यांना संविधानाचे शिल्पकार म्हटले जाते.');
INSERT INTO public.questions (subject_tag, subtopic_tag, question_text, option_a, option_b, option_c, option_d, correct_option, explanation) VALUES ('node_3', 'General', 'खालीलपैकी ''नदी'' या शब्दाचा बहुवचनी रूप कोणता?', 'नद्या', 'नद्यांना', 'नदी', 'नद्यांचे', 'A', 'मराठी व्याकरणात इ-कारान्त स्त्रीलिंगी नामाचे अनेकवचन या-कारान्त होते (उदा. नदी -> नद्या).');
INSERT INTO public.questions (subject_tag, subtopic_tag, question_text, option_a, option_b, option_c, option_d, correct_option, explanation) VALUES ('node_3', 'General', '''ग्रामगीता'' हा ग्रंथ कोणी लिहिला?', 'संत तुकाराम', 'संत गाडगेबाबा', 'राष्ट्रसंत तुकडोजी महाराज', 'संत ज्ञानेश्वर', 'C', 'ग्रामीण विकासाचा आणि ग्रामसुधारणेचा संदेश देणारा ''ग्रामगीता'' ग्रंथ राष्ट्रसंत तुकडोजी महाराजांनी लिहिला.');
INSERT INTO public.questions (subject_tag, subtopic_tag, question_text, option_a, option_b, option_c, option_d, correct_option, explanation) VALUES ('node_3', 'General', 'ताशी ४५ किमी वेगाने जाणारी गाडी ४ तासांत किती अंतर पार करेल?', '१६० किमी', '१८० किमी', '२०० किमी', '२२० किमी', 'B', 'अंतर = वेग × वेळ = ४५ × ४ = १८० किमी.');
INSERT INTO public.questions (subject_tag, subtopic_tag, question_text, option_a, option_b, option_c, option_d, correct_option, explanation) VALUES ('node_3', 'General', 'एका वर्गातील ४० विद्यार्थ्यांचे सरासरी वय १५ वर्षे आहे. शिक्षकाचे वय मिळवल्यास सरासरी १६ वर्षे होते, तर शिक्षकाचे वय किती?', '५५ वर्षे', '५६ वर्षे', '५७ वर्षे', '५६.५ वर्षे', 'B', '४० मुलांचे वय = ६००. ४१ जणांचे वय = ४१ × १६ = ६५६. शिक्षकाचे वय = ६५६ - ६०० = ५६ वर्षे.');
INSERT INTO public.questions (subject_tag, subtopic_tag, question_text, option_a, option_b, option_c, option_d, correct_option, explanation) VALUES ('node_3', 'General', 'भारताची मध्यवर्ती बँक कोणती आहे?', 'स्टेट बँक ऑफ इंडिया (SBI)', 'रिझर्व्ह बँक ऑफ इंडिया (RBI)', 'पंजाब नॅशनल बँक (PNB)', 'बँक ऑफ महाराष्ट्र', 'B', 'भारतीय रिझर्व्ह बँक (RBI) ही देशातील सर्व बँकांवर नियंत्रण ठेवणारी मध्यवर्ती बँक आहे.');
INSERT INTO public.questions (subject_tag, subtopic_tag, question_text, option_a, option_b, option_c, option_d, correct_option, explanation) VALUES ('node_3', 'General', 'जर एका वर्तुळाची त्रिज्या १४ सेमी असेल, तर त्याचा परिघ किती?', '४४ सेमी', '८८ सेमी', '१३२ सेमी', '१५४ सेमी', 'B', 'वर्तुळाचा परिघ = २ × π × r = २ × (२२/७) × १४ = २ × २२ × २ = ८८ सेमी.');
INSERT INTO public.questions (subject_tag, subtopic_tag, question_text, option_a, option_b, option_c, option_d, correct_option, explanation) VALUES ('node_3', 'General', 'जर x + y = १० आणि x - y = ४, तर x व y ची किंमत किती?', 'x=7, y=3', 'x=6, y=4', 'x=8, y=2', 'x=5, y=5', 'A', 'दोन्ही समीकरणांची बेरीज केल्यास: २x = १४ => x = ७. ७ + y = १० => y = ३.');
INSERT INTO public.questions (subject_tag, subtopic_tag, question_text, option_a, option_b, option_c, option_d, correct_option, explanation) VALUES ('node_3', 'General', 'लोणावळा आणि खंडाळा ही प्रसिद्ध थंड हवेची ठिकाणे कोणत्या जिल्ह्यात आहेत?', 'सातारा', 'पुणे', 'रायगड', 'ठाणे', 'B', 'लोणावळा आणि खंडाळा ही दोन्ही पर्यटन स्थळे पुणे जिल्ह्यात येतात.');
INSERT INTO public.questions (subject_tag, subtopic_tag, question_text, option_a, option_b, option_c, option_d, correct_option, explanation) VALUES ('node_3', 'General', 'पुढीलपैकी तत्सम शब्द कोणता?', 'दूध', 'हात', 'सूर्य', 'कान', 'C', 'संस्कृतमधून मराठीत जसेच्या तसे आलेले शब्द ''तत्सम'' असतात. (उदा. सूर्य, अग्नि, कवी).');
INSERT INTO public.questions (subject_tag, subtopic_tag, question_text, option_a, option_b, option_c, option_d, correct_option, explanation) VALUES ('node_3', 'General', 'ग्रामपंचायतीचा कार्यकाळ सामान्यतः किती वर्षांचा असतो?', '४ वर्षे', '५ वर्षे', '६ वर्षे', '३ वर्षे', 'B', 'महाराष्ट्रात ग्रामपंचायतीची मुदत तिच्या पहिल्या बैठकीच्या तारखेपासून ५ वर्षांची असते.');
INSERT INTO public.questions (subject_tag, subtopic_tag, question_text, option_a, option_b, option_c, option_d, correct_option, explanation) VALUES ('node_3', 'General', 'जर पाण्याला हवा म्हटले, हवेला अग्नी म्हटले, अग्नीला जमीन म्हटले, तर पक्षी कोठे उडतात?', 'हवा', 'अग्नी', 'जमीन', 'पाणी', 'B', 'पक्षी ''हवेत'' उडतात, आणि दिलेल्या सांकेतिक माहितीनुसार हवेला ''अग्नी'' म्हटले आहे.');
INSERT INTO public.questions (subject_tag, subtopic_tag, question_text, option_a, option_b, option_c, option_d, correct_option, explanation) VALUES ('node_3', 'General', '''काठोकाठ भरलेला'' या शब्दासाठी सामासिक शब्द ओळखा.', 'अलोप', 'अहोरात्र', 'आकंठ', 'काठोकाठ', 'C', '''कंठापर्यंत भरलेला'' किंवा काठोकाठ भरलेला याला ''आकंठ'' असे म्हणतात.');
INSERT INTO public.questions (subject_tag, subtopic_tag, question_text, option_a, option_b, option_c, option_d, correct_option, explanation) VALUES ('node_3', 'General', 'मालिकेतील प्रश्नचिन्हाच्या जागी योग्य पर्याय निवडा: A, C, F, J, O, ?', 'S', 'T', 'U', 'V', 'C', 'फरक वाढतोय: +1, +2, +3, +4, +5. O च्या पुढे ५ वे अक्षर ''U'' येते.');
INSERT INTO public.questions (subject_tag, subtopic_tag, question_text, option_a, option_b, option_c, option_d, correct_option, explanation) VALUES ('node_3', 'General', 'खालीलपैकी कोणता शब्द ''सूर्य'' या शब्दाचा समानार्थी नाही?', 'भास्कर', 'दिनकर', 'रवी', 'चंद्र', 'D', 'भास्कर, दिनकर आणि रवी हे सर्व सूर्याचे समानार्थी शब्द आहेत. चंद्र हा वेगळा ग्रह/उपग्रह दर्शवतो.');
INSERT INTO public.questions (subject_tag, subtopic_tag, question_text, option_a, option_b, option_c, option_d, correct_option, explanation) VALUES ('node_3', 'General', 'मानवी शरीरात रक्ताभिसरणाचा शोध कोणी लावला?', 'विल्यम हार्वे', 'ल्युवेनहॉक', 'रॉबर्ट हूक', 'एडवर्ड जेन्नर', 'A', 'विल्यम हार्वे या शास्त्रज्ञाने १६२८ मध्ये मानवी शरीरातील रक्ताभिसरण संस्थेचा शोध लावला.');
INSERT INTO public.questions (subject_tag, subtopic_tag, question_text, option_a, option_b, option_c, option_d, correct_option, explanation) VALUES ('node_3', 'General', '''डोळ्यांवर धुंदी येणे'' या वाक्प्रचाराचा अर्थ काय?', 'डोळे येणे', 'गर्व चढणे / मदांध होणे', 'झोप येणे', 'दिसणे बंद होणे', 'B', 'एखाद्या गोष्टीचा (संपत्ती, सत्ता इत्यादींचा) अती गर्व किंवा अहंकार होणे म्हणजे ''डोळ्यांवर धुंदी येणे''.');
INSERT INTO public.questions (subject_tag, subtopic_tag, question_text, option_a, option_b, option_c, option_d, correct_option, explanation) VALUES ('node_3', 'General', 'घड्याळात दुपारी ३:०० वाजता तासकाटा आणि मिनिटकाटा यांत किती अंशाचा कोन असतो?', '४५°', '६०°', '९०°', '१२०°', 'C', '३ वाजता दोन्ही काट्यांमध्ये ३ तासांचे अंतर असते (३ × ३०°) = ९०° काटकोन.');
INSERT INTO public.questions (subject_tag, subtopic_tag, question_text, option_a, option_b, option_c, option_d, correct_option, explanation) VALUES ('node_3', 'General', 'महाराष्ट्र पोलीस दलाच्या ''SRPF'' चा पूर्ण विस्तार काय आहे?', 'State Reserve Police Force', 'State Rapid Police Force', 'Special Reserve Police Force', 'State Rural Police Force', 'A', 'SRPF म्हणजे State Reserve Police Force (राज्य राखीव पोलीस बल).');
INSERT INTO public.questions (subject_tag, subtopic_tag, question_text, option_a, option_b, option_c, option_d, correct_option, explanation) VALUES ('node_3', 'General', 'महाराष्ट्रातील ''नागपूर'' हे शहर कोणत्या फळासाठी प्रसिद्ध आहे?', 'केळी', 'संत्रे', 'द्राक्षे', 'स्ट्रॉबेरी', 'B', 'नागपूरला ''ऑरेंज सिटी'' म्हटले जाते कारण ते संत्र्यांच्या उत्पादनासाठी प्रसिद्ध आहे.');
INSERT INTO public.questions (subject_tag, subtopic_tag, question_text, option_a, option_b, option_c, option_d, correct_option, explanation) VALUES ('node_4', 'General', 'महाराष्ट्रातील तापी नदीचा उगम कोठे होतो?', 'महाबळेश्वर', 'त्र्यंबकेश्वर', 'मुलताई (मध्य प्रदेश)', 'भीमाशंकर', 'C', 'पश्चिम वाहिनी तापी नदीचा उगम मध्य प्रदेशातील बैतुल जिल्ह्यातील मुलताई टेकड्यांमध्ये होतो.');
INSERT INTO public.questions (subject_tag, subtopic_tag, question_text, option_a, option_b, option_c, option_d, correct_option, explanation) VALUES ('node_4', 'General', 'जर CAT = 24 आणि DOG = 26, तर COW = ?', '४१', '३९', '४३', '३८', 'A', 'अक्षरांचे स्थानांक: C(3) + O(15) + W(23) = 41.');
INSERT INTO public.questions (subject_tag, subtopic_tag, question_text, option_a, option_b, option_c, option_d, correct_option, explanation) VALUES ('node_4', 'General', '''निसर्ग'' या शब्दाचा विभक्ती प्रत्यय नसलेला मूळ रूप कोणता?', 'निसर्गाने', 'निसर्गात', 'निसर्ग', 'निसर्गाला', 'C', '''निसर्ग'' हा प्रथमा विभक्तीतील शब्द आहे. प्रथमा विभक्तीला कोणतेही प्रत्यय नसतात.');
INSERT INTO public.questions (subject_tag, subtopic_tag, question_text, option_a, option_b, option_c, option_d, correct_option, explanation) VALUES ('node_4', 'General', 'महाराष्ट्राची उपराजधानी कोणती आहे?', 'नाशिक', 'औरंगाबाद', 'नागपूर', 'सोलापूर', 'C', 'नागपूर ही महाराष्ट्राची उपराजधानी असून येथे हिवाळी अधिवेशन पार पडते.');
INSERT INTO public.questions (subject_tag, subtopic_tag, question_text, option_a, option_b, option_c, option_d, correct_option, explanation) VALUES ('node_4', 'General', 'भारतीय राज्यघटनेत एकूण किती मूलभूत कर्तव्ये (Fundamental Duties) आहेत?', '१०', '११', '१२', '९', 'B', 'राज्यघटनेच्या कलम ५१A अंतर्गत भारतीय नागरिकांसाठी एकूण ११ मूलभूत कर्तव्ये नमूद करण्यात आली आहेत.');
INSERT INTO public.questions (subject_tag, subtopic_tag, question_text, option_a, option_b, option_c, option_d, correct_option, explanation) VALUES ('node_4', 'General', 'विसंगत शब्द शोधा: चौरस, आयत, त्रिकोण, वर्तुळ', 'चौरस', 'आयत', 'त्रिकोण', 'वर्तुळ', 'D', 'चौरस, आयत आणि त्रिकोण हे सरळ रेषाखंडांनी (बाजू) बनलेले असतात, तर वर्तुळात वक्ररेषा असते.');
INSERT INTO public.questions (subject_tag, subtopic_tag, question_text, option_a, option_b, option_c, option_d, correct_option, explanation) VALUES ('node_4', 'General', 'महाराष्ट्र पोलिसांचे आणीबाणीच्या मदतीसाठी असलेले हेल्पलाइन नंबर कोणते आहे?', '१०० / ११२', '१०१', '१०२', '१०९१', 'A', 'आणीबाणीच्या प्रसंगी पोलीस मदतीसाठी ११२ (आणि पारंपारिक १००) हा नंबर डायल केला जातो.');
INSERT INTO public.questions (subject_tag, subtopic_tag, question_text, option_a, option_b, option_c, option_d, correct_option, explanation) VALUES ('node_4', 'General', 'भारताचा राष्ट्रीय प्राणी कोणता आहे?', 'सिंह', 'वाघ', 'हत्ती', 'बिबट्या', 'B', 'बंगाल टायगर (वाघ) हा भारताचा अधिकृत राष्ट्रीय प्राणी आहे.');
INSERT INTO public.questions (subject_tag, subtopic_tag, question_text, option_a, option_b, option_c, option_d, correct_option, explanation) VALUES ('node_4', 'General', '''वाघ'' या शब्दाचे स्त्रीलिंगी रूप काय होईल?', 'वाघीण', 'वाघिणी', 'वाघी', 'वाघीणबाई', 'A', 'मराठी व्याकरणात ''वाघ'' या पुल्लिंगी शब्दाचे स्त्रीलिंगी रूप ''वाघीण'' असे होते.');
INSERT INTO public.questions (subject_tag, subtopic_tag, question_text, option_a, option_b, option_c, option_d, correct_option, explanation) VALUES ('node_4', 'General', 'भारतातील पहिल्या महिला राष्ट्रपती कोण?', 'इंदिरा गांधी', 'प्रतिभाताई पाटील', 'द्रौपदी मुर्मू', 'सुचेता कृपलानी', 'B', 'महाराष्ट्राच्या कन्या प्रतिभाताई पाटील भारताच्या १२ व्या राष्ट्रपती व पहिल्या महिला राष्ट्रपती बनल्या.');
INSERT INTO public.questions (subject_tag, subtopic_tag, question_text, option_a, option_b, option_c, option_d, correct_option, explanation) VALUES ('node_4', 'General', '''पांढरा फेन'' या शब्दसमूहासाठी शुद्ध शब्द ओळखा.', 'शुभ्र', 'धवल', 'फेन धवल', 'पांढरा शुभ्र', 'D', 'पांढऱ्या रंगाच्या तीव्रतेसाठी ''पांढरा शुभ्र'' किंवा ''धवल'' असा जोडशब्द वापरला जातो.');
INSERT INTO public.questions (subject_tag, subtopic_tag, question_text, option_a, option_b, option_c, option_d, correct_option, explanation) VALUES ('node_4', 'General', 'लोकमान्य टिळकांनी कोणते वृत्तपत्र सुरू केले होते?', 'केसरी', 'मूकनायक', 'दर्पण', 'हरिजन', 'A', 'लोकमान्य बाळ गंगाधर टिळक यांनी जनजागृतीसाठी मराठीत ''केसरी'' आणि इंग्रजीत ''मराठा'' वृत्तपत्र सुरू केले.');
INSERT INTO public.questions (subject_tag, subtopic_tag, question_text, option_a, option_b, option_c, option_d, correct_option, explanation) VALUES ('node_4', 'General', 'खालीलपैकी ''शुद्ध'' शब्द ओळखा.', 'उज्वल', 'उज्ज्वल', 'उज्वल', 'उजवल', 'B', 'उत् + ज्वल = उज्ज्वल. यामध्ये दोन ''ज'' अर्धे जोडून ''उज्ज्वल'' असा शुद्ध शब्द बनतो.');
INSERT INTO public.questions (subject_tag, subtopic_tag, question_text, option_a, option_b, option_c, option_d, correct_option, explanation) VALUES ('node_4', 'General', 'घड्याळात दुपारी ३ वाजले असताना तासकाटा व मिनिटकाटा यांत किती अंशाचा कोन असतो?', '४५°', '६०°', '९०°', '१८०°', 'C', 'प्रत्येक तासाच्या अंतरात ३० अंशाचा कोन असतो. ३ वाजता (३ × ३०°) = ९० अंशाचा (काटकोन) कोन बनतो.');
INSERT INTO public.questions (subject_tag, subtopic_tag, question_text, option_a, option_b, option_c, option_d, correct_option, explanation) VALUES ('node_4', 'General', 'खालीलपैकी कोणता दिवस ''महाराष्ट्र दिन'' म्हणून साजरा केला जातो?', '१५ ऑगस्ट', '२६ जानेवारी', '१ मे', '२ ऑक्टोबर', 'C', '१ मे १९६० रोजी महाराष्ट्र राज्याची स्थापना झाल्यामुळे हा दिवस ''महाराष्ट्र दिन'' म्हणून साजरा होतो.');
INSERT INTO public.questions (subject_tag, subtopic_tag, question_text, option_a, option_b, option_c, option_d, correct_option, explanation) VALUES ('node_4', 'General', 'भारतीय राष्ट्रध्वजाच्या रुंदी आणि लांबीचे गुणोत्तर किती असते?', '२ : ३', '३ : २', '१ : २', '२ : ४', 'A', 'भारतीय राष्ट्रध्वजाचे रुंदी आणि लांबीचे प्रमाणीकृत प्रमाण २:३ असे आहे.');
INSERT INTO public.questions (subject_tag, subtopic_tag, question_text, option_a, option_b, option_c, option_d, correct_option, explanation) VALUES ('node_4', 'General', '३०% चे २०% = किती?', '६%', '०.६%', '६०%', '०.०६%', 'A', '(३०/१००) × (२०/१००) = ६०० / १०००० = ६/१०० = ६%.');
INSERT INTO public.questions (subject_tag, subtopic_tag, question_text, option_a, option_b, option_c, option_d, correct_option, explanation) VALUES ('node_4', 'General', 'नाशिक हे शहर कोणत्या नदीच्या काठावर वसलेले आहे?', 'कृष्णा', 'गोदावरी', 'भीमा', 'तापी', 'B', 'गोदावरी नदीचा उगम नाशिक जिल्ह्यातील त्र्यंबकेश्वर येथे होतो आणि नाशिक शहर या नदीच्या काठावर वसलेले आहे.');
INSERT INTO public.questions (subject_tag, subtopic_tag, question_text, option_a, option_b, option_c, option_d, correct_option, explanation) VALUES ('node_4', 'General', 'मानवाच्या शरीरातील कोणत्या भागात ''हिमोग्लोबिन'' आढळते?', 'हाडे', 'रक्त', 'स्नायू', 'त्वचा', 'B', 'रक्तातील तांबड्या पेशींमध्ये (RBC) ऑक्सिजनचे वहन करणारे ''हिमोग्लोबिन'' हे प्रथिन असते.');
INSERT INTO public.questions (subject_tag, subtopic_tag, question_text, option_a, option_b, option_c, option_d, correct_option, explanation) VALUES ('node_4', 'General', 'समीकरण सोडवा: ३x - ७ = २०, तर x = ?', '७', '८', '९', '१०', 'C', '३x = २० + ७ => ३x = २७ => x = ९.');
INSERT INTO public.questions (subject_tag, subtopic_tag, question_text, option_a, option_b, option_c, option_d, correct_option, explanation) VALUES ('node_4', 'General', 'महाराष्ट्रातील ''दख्खनच्या पठाराची'' निर्मिती कशाने झाली आहे?', 'भूकंप', 'भ्रंशघाटी', 'ज्वालामुखीचे उद्रेक (लाव्हा)', 'गाळाचे संचयन', 'C', 'दख्खनचे पठार हे लाव्हाच्या भेगाळी उद्रेकातून (fissure eruption) थंड झालेल्या बेसाल्ट खडकापासून बनले आहे.');
INSERT INTO public.questions (subject_tag, subtopic_tag, question_text, option_a, option_b, option_c, option_d, correct_option, explanation) VALUES ('node_4', 'General', 'A ही B ची बहीण आहे. C हा B चा भाऊ आहे. D हा C चा मुलगा आहे. तर A चे D शी नाते काय?', 'आई', 'आत्या', 'मावशी', 'बहीण', 'B', 'C हा D चा वडील आहे आणि A ही C ची बहीण आहे, म्हणून A ही D ची ''आत्या'' होईल.');
INSERT INTO public.questions (subject_tag, subtopic_tag, question_text, option_a, option_b, option_c, option_d, correct_option, explanation) VALUES ('node_4', 'General', 'विरुद्धार्थी शब्द शोधा: ''प्राचीन'' × ?', 'जुनं', 'अर्वाचीन', 'ऐतिहासिक', 'पुराणकालीन', 'B', '''प्राचीन'' म्हणजे खूप जुन्या काळातील, तर त्याचा विरुद्धार्थी शब्द ''अर्वाचीन'' (आधुनिक/नवीन काळातील) असा होतो.');
INSERT INTO public.questions (subject_tag, subtopic_tag, question_text, option_a, option_b, option_c, option_d, correct_option, explanation) VALUES ('node_4', 'General', '''नागझिरा'' अभयारण्य महाराष्ट्रातील कोणत्या जिल्ह्यात स्थित आहे?', 'गोंदिया', 'चंद्रपूर', 'गडचिरोली', 'भंडारा', 'A', 'नागझिरा वन्यजीव अभयारण्य प्रामुख्याने गोंदिया आणि भंडारा जिल्ह्यांच्या सीमेवर (गोंदिया) येते.');
INSERT INTO public.questions (subject_tag, subtopic_tag, question_text, option_a, option_b, option_c, option_d, correct_option, explanation) VALUES ('node_4', 'General', 'संसदेची दोन अधिवेशनांमधील कमाल अंतर किती असू शकते?', '३ महिने', '६ महिने', '९ महिने', '१ वर्ष', 'B', 'घटनेनुसार संसदेच्या दोन बैठकांमध्ये ६ महिन्यांपेक्षा जास्त अंतर असता कामा नये.');
INSERT INTO public.questions (subject_tag, subtopic_tag, question_text, option_a, option_b, option_c, option_d, correct_option, explanation) VALUES ('node_4', 'General', 'भारताचे पहिले पंतप्रधान कोण होते?', 'डॉ. राजेंद्र प्रसाद', 'पंडित जवाहरलाल नेहरू', 'सरदार वल्लभभाई पटेल', 'मराठवाडा मुक्तीसंग्राम नेते', 'B', 'स्वतंत्र भारताचे पहिले पंतप्रधान पंडित जवाहरलाल नेहरू होते, त्यांनी १९४७ ते १९६४ या काळात पद भूषवले.');
INSERT INTO public.questions (subject_tag, subtopic_tag, question_text, option_a, option_b, option_c, option_d, correct_option, explanation) VALUES ('node_4', 'General', 'जागतिक महिला दिन कधी साजरा केला जातो?', '८ मार्च', '१० डिसेंबर', '५ सप्टेंबर', '१४ नोव्हेंबर', 'A', 'दरवर्षी ८ मार्च हा दिवस आंतरराष्ट्रीय महिला दिन म्हणून पाळला जातो.');
INSERT INTO public.questions (subject_tag, subtopic_tag, question_text, option_a, option_b, option_c, option_d, correct_option, explanation) VALUES ('node_4', 'General', '''मनात मांडणे'' या वाक्प्रचाराचा अर्थ काय?', 'विचार करणे / बेत आखणे', 'मनातून काढून टाकणे', 'राग व्यक्त करणे', 'दुःख करणे', 'A', 'एखादी योजना किंवा विचार मनात पक्का करणे म्हणजे ''मनात मांडणे''.');
INSERT INTO public.questions (subject_tag, subtopic_tag, question_text, option_a, option_b, option_c, option_d, correct_option, explanation) VALUES ('node_4', 'General', 'ग्रामपंचायतीचा प्रशासकीय प्रमुख कोण असतो?', 'सरपंच', 'ग्रामसेवक', 'गटविकास अधिकारी (BDO)', 'पोलीस पाटील', 'B', 'सरपंच हे राजकीय प्रमुख असतात, तर जिल्हा परिषदेकडून नेमणूक झालेला ग्रामसेवक हा ग्रामपंचायतीचा प्रशासकीय/सरकारी प्रमुख असतो.');
INSERT INTO public.questions (subject_tag, subtopic_tag, question_text, option_a, option_b, option_c, option_d, correct_option, explanation) VALUES ('node_4', 'General', '१५ मजूर एक काम १० दिवसांत पूर्ण करतात, तर तेच काम ५ मजूर किती दिवसांत करतील?', '२० दिवस', '२५ दिवस', '३० दिवस', '३५ दिवस', 'C', 'व्यस्त प्रमाण: m1 × d1 = m2 × d2 => १५ × १० = ५ × d2 => d2 = १५० / ५ = ३० दिवस.');
INSERT INTO public.questions (subject_tag, subtopic_tag, question_text, option_a, option_b, option_c, option_d, correct_option, explanation) VALUES ('node_4', 'General', 'भारतीय राज्यघटनेचे पालकत्व कोणाकडे असते?', 'संसद', 'राष्ट्रपती', 'सर्वोच्च न्यायालय', 'पंतप्रधान', 'C', 'भारतीय राज्यघटनेचे संरक्षण आणि अंतिम अर्थ लावण्याचा अधिकार सर्वोच्च न्यायालयाकडे असतो.');
INSERT INTO public.questions (subject_tag, subtopic_tag, question_text, option_a, option_b, option_c, option_d, correct_option, explanation) VALUES ('node_4', 'General', 'मराठीतील पहिली महिला कादंबरीकार कोण मानल्या जातात?', 'ताराबाई शिंदे', 'सावित्रीबाई फुले', 'साळूबाई तांबडे / काशीबाई कानिटकर', 'आनंदीबाई जोशी', 'C', 'काशीबाई कानिटकर यांना मराठीतील पहिल्या महिला कादंबरीकार म्हणून ओळखले जाते.');
INSERT INTO public.questions (subject_tag, subtopic_tag, question_text, option_a, option_b, option_c, option_d, correct_option, explanation) VALUES ('node_4', 'General', 'महाराष्ट्राचे सध्याचे राज्यपाल कोण आहेत? (नवीनतम माहितीनुसार)', 'भगतसिंग कोश्यारी', 'रमेश बैस', 'सी. पी. राधाकृष्णन', 'विद्यासागर राव', 'C', 'महाराष्ट्राचे राज्यपाल सी. पी. राधाकृष्णन हे जुलै २०२४ मध्ये नियुक्त झाले आहेत.');
INSERT INTO public.questions (subject_tag, subtopic_tag, question_text, option_a, option_b, option_c, option_d, correct_option, explanation) VALUES ('node_4', 'General', 'भारताची मध्यवर्ती बँक कोणती आहे?', 'स्टेट बँक ऑफ इंडिया', 'पंजाब नॅशनल बँक', 'रिझर्व्ह बँक ऑफ इंडिया (RBI)', 'बँक ऑफ महाराष्ट्र', 'C', 'भारताच्या वित्तीय क्षेत्राचे नियंत्रण आणि चलन निर्मितीचे कार्य रिझर्व्ह बँक ऑफ इंडिया करते.');
INSERT INTO public.questions (subject_tag, subtopic_tag, question_text, option_a, option_b, option_c, option_d, correct_option, explanation) VALUES ('node_4', 'General', 'भारतीय चलनावरील नोटेवर एकूण किती भाषांमध्ये तिची किंमत लिहिलेली असते?', '१५', '१७', '१२', '२२', 'B', 'भारतीय चलनी नोटेच्या मागील बाजूच्या भाषा पॅनेलवर १५ आणि समोरील बाजूला हिंदी व इंग्रजी अशा एकूण १७ भाषा असतात.');
INSERT INTO public.questions (subject_tag, subtopic_tag, question_text, option_a, option_b, option_c, option_d, correct_option, explanation) VALUES ('node_4', 'General', '''रामाने रावणास मारले.'' या वाक्यातील विभक्ती प्रत्यय ओळखा.', 'प्रथमा व द्वितीया', 'तृतीया व द्वितीया', 'चतुर्थी व पंचमी', 'सप्तमी व द्वितीया', 'B', '''रामाने'' मधील ''ने'' हा तृतीया विभक्तीचा प्रत्यय आहे आणि ''रावणास'' मधील ''स'' हा द्वितीया विभक्तीचा प्रत्यय आहे.');
INSERT INTO public.questions (subject_tag, subtopic_tag, question_text, option_a, option_b, option_c, option_d, correct_option, explanation) VALUES ('node_4', 'General', 'दोन किंवा अधिक शब्द एकत्र येऊन बनणाऱ्या नवीन शब्दाला काय म्हणतात?', 'संधी', 'समास', 'प्रयोग', 'अलंकार', 'B', 'शब्दांच्या एकत्रीकरणाने जो नवीन संक्षिप्त शब्द तयार होतो, त्याला ''समास'' म्हणतात.');
INSERT INTO public.questions (subject_tag, subtopic_tag, question_text, option_a, option_b, option_c, option_d, correct_option, explanation) VALUES ('node_4', 'General', 'ताशी ६० किमी वेगाने जाणारी १५० मीटर लांबीची आगगाडी एका खांबाला किती सेकंदात ओलांडेल?', '७ सेकंद', '९ सेकंद', '१० सेकंद', '१२ सेकंद', 'B', 'वेग = ६० × (५/१८) = २५/३ मीटर/सेकंद. वेळ = अंतर / वेग = १५० / (२५/३) = (१५० × ३) / २५ = ९ सेकंद.');
INSERT INTO public.questions (subject_tag, subtopic_tag, question_text, option_a, option_b, option_c, option_d, correct_option, explanation) VALUES ('node_4', 'General', 'असहकार आंदोलन (Non-Cooperation Movement) महात्मा गांधींनी कधी मागे घेतले?', '१९२०', '१९२२', '१९३०', '१९४२', 'B', 'चौरी-चौरा घटनेतील हिंसेनंतर फेब्रुवारी १९२२ मध्ये महात्मा गांधींनी असहकार आंदोलन मागे घेतले.');
INSERT INTO public.questions (subject_tag, subtopic_tag, question_text, option_a, option_b, option_c, option_d, correct_option, explanation) VALUES ('node_4', 'General', '१५, २५ आणि ३५ यांचा मसावी (HCF) किती?', '५', '१०', '१५', '१०५', 'A', '१५, २५ आणि ३५ या तिन्ही संख्यांना भाग जाणारी सर्वात मोठी सामाईक संख्या ५ आहे.');
INSERT INTO public.questions (subject_tag, subtopic_tag, question_text, option_a, option_b, option_c, option_d, correct_option, explanation) VALUES ('node_4', 'General', 'एका वर्तुळाची त्रिज्या २१ सेमी असेल, तर त्याचे क्षेत्रफळ किती चौ सेमी?', '१३८६', '१५४', '६१६', '१२००', 'A', 'क्षेत्रफळ = (२२/७) × २१ × २१ = २२ × ३ × २१ = १३८६ चौ सेमी.');
INSERT INTO public.questions (subject_tag, subtopic_tag, question_text, option_a, option_b, option_c, option_d, correct_option, explanation) VALUES ('node_4', 'General', 'एका रांगेत मध्यभागी उभारलेल्या मुलाचा क्रमांक १५ वा आहे, तर रांगेत एकूण किती मुले आहेत?', '२९', '३०', '३१', '२८', 'A', 'मध्यभागी १५ वा मुलगा म्हणजेच त्याच्या डावीकडे १४ आणि उजवीकडे १४ मुले आहेत. एकूण मुले = १४ + १ + १४ = २९.');
INSERT INTO public.questions (subject_tag, subtopic_tag, question_text, option_a, option_b, option_c, option_d, correct_option, explanation) VALUES ('node_4', 'General', 'महाराष्ट्राचे राज्यप्राणी कोणता आहे?', 'वाघ', 'शेकरू', 'हत्ती', 'हरिण', 'B', 'शेकरू (एक प्रकारची मोठी खार) हा महाराष्ट्र राज्याचा अधिकृत राज्यप्राणी आहे.');
INSERT INTO public.questions (subject_tag, subtopic_tag, question_text, option_a, option_b, option_c, option_d, correct_option, explanation) VALUES ('node_4', 'General', 'जर BAT = 23 आणि CAT = 24, तर BALL = ?', '२५', '२७', '२९', '३०', 'B', 'B(2) + A(1) + L(12) + L(12) = 27.');
INSERT INTO public.questions (subject_tag, subtopic_tag, question_text, option_a, option_b, option_c, option_d, correct_option, explanation) VALUES ('node_4', 'General', '७, १४, २१, २८, ३५ यांची सरासरी किती?', '२०', '२१', '२२', '२३', 'B', 'समान फरक असलेल्या ५ संख्यांची मधली संख्या २१ हीच सरासरी असते.');
INSERT INTO public.questions (subject_tag, subtopic_tag, question_text, option_a, option_b, option_c, option_d, correct_option, explanation) VALUES ('node_4', 'General', 'एका वर्तुळाचे क्षेत्रफळ १५४ चौ सेमी असेल, तर त्याची त्रिज्या (Radius) किती असेल?', '७ सेमी', '१४ सेमी', '२१ सेमी', '३.५ सेमी', 'A', 'क्षेत्रफळ = π × r² => १५४ = (२२/७) × r² => r² = ४९ => r = ७ सेमी.');
INSERT INTO public.questions (subject_tag, subtopic_tag, question_text, option_a, option_b, option_c, option_d, correct_option, explanation) VALUES ('node_4', 'General', 'एका वस्तूची खरेदी किंमत ₹८०० असून ती ₹९६० ला विकली, तर शेकडा नफा किती?', '१५%', '१८%', '२०%', '२५%', 'C', 'नफा = ९६० - ८०० = १६० रुपये. शेकडा नफा = (१६० / ८००) × १०० = २०%.');
INSERT INTO public.questions (subject_tag, subtopic_tag, question_text, option_a, option_b, option_c, option_d, correct_option, explanation) VALUES ('node_4', 'General', 'महाराष्ट्र पोलिसांचे ध्येयवाक्य ''सद्रक्षणाय खलनिग्रहणाय'' याचा अर्थ काय?', 'सज्जनांचे रक्षण व दुर्जनांचा नाश', 'सदैव सेवेसाठी तत्पर', 'सत्य हेच आमचे कर्तव्य', 'शांतता आणि सुव्यवस्था', 'A', '''सद्रक्षणाय'' (सज्जनांचे रक्षण करण्यासाठी) आणि ''खलनिग्रहणाय'' (दुष्टांचे दमन/नाश करण्यासाठी) हा याचा अर्थ आहे.');
INSERT INTO public.questions (subject_tag, subtopic_tag, question_text, option_a, option_b, option_c, option_d, correct_option, explanation) VALUES ('node_4', 'General', '१ ते १०० दरम्यान किती मूळ संख्या (Prime Numbers) आहेत?', '२०', '२२', '२५', '३०', 'C', '१ ते १०० या संख्यांच्या दरम्यान एकूण २५ मूळ संख्या येतात.');
INSERT INTO public.questions (subject_tag, subtopic_tag, question_text, option_a, option_b, option_c, option_d, correct_option, explanation) VALUES ('node_4', 'General', 'विधानपरिषदेची मुदत किती वर्षांची असते?', '५ वर्षे', '६ वर्षे', 'कायमस्वरूपी (कधीही विसर्जित होत नाही)', '४ वर्षे', 'C', 'विधानपरिषद हे स्थायी सभागृह आहे. ते कधीही विसर्जित होत नाही, परंतु सदस्यांचा कार्यकाळ ६ वर्षांचा असतो.');
INSERT INTO public.questions (subject_tag, subtopic_tag, question_text, option_a, option_b, option_c, option_d, correct_option, explanation) VALUES ('node_4', 'General', 'समानार्थी शब्द ओळखा: ''वारा'' = ?', 'पवन', 'अनल', 'तोय', 'अर्क', 'A', 'पवन, अनिल, वायू, मरुत हे वाऱ्याचे समानार्थी शब्द आहेत.');
INSERT INTO public.questions (subject_tag, subtopic_tag, question_text, option_a, option_b, option_c, option_d, correct_option, explanation) VALUES ('node_4', 'General', 'भारतीय राज्यघटनेत ''समवर्ती सूची'' (Concurrent List) ची संकल्पना कोणत्या देशाकडून घेतली आहे?', 'अमेरिका', 'ब्रिटन', 'ऑस्ट्रेलिया', 'कॅनडा', 'C', 'केंद्र व राज्य या दोघांना कायदा करण्याचा अधिकार असणारी समवर्ती सूची ऑस्ट्रेलियाच्या घटनेवरून प्रेरित आहे.');
INSERT INTO public.questions (subject_tag, subtopic_tag, question_text, option_a, option_b, option_c, option_d, correct_option, explanation) VALUES ('node_4', 'General', '५० चा २०% किती?', '५', '१०', '१५', '२०', 'B', '(५० × २०) / १०० = १०.');
INSERT INTO public.questions (subject_tag, subtopic_tag, question_text, option_a, option_b, option_c, option_d, correct_option, explanation) VALUES ('node_4', 'General', '''सुधाकराने निबंध लिहिला.'' या वाक्यातील कर्म ओळखा.', 'सुधाकराने', 'निबंध', 'लिहिला', 'निबंध लिहिला', 'B', 'लिहिण्याची क्रिया ''निबंध'' या घटकावर घडत असल्याने वाक्यातील कर्म ''निबंध'' आहे.');
INSERT INTO public.questions (subject_tag, subtopic_tag, question_text, option_a, option_b, option_c, option_d, correct_option, explanation) VALUES ('node_4', 'General', 'एका वर्तुळाचा व्यास १४ सेमी असल्यास त्याची त्रिज्या किती असेल?', '२८ सेमी', '७ सेमी', '१४ सेमी', '२१ सेमी', 'B', 'वर्तुळाची त्रिज्या ही व्यासाच्या निम्मी असते. त्यामुळे त्रिज्या = १४ / २ = ७ सेमी.');
INSERT INTO public.questions (subject_tag, subtopic_tag, question_text, option_a, option_b, option_c, option_d, correct_option, explanation) VALUES ('node_4', 'General', '१ ते २० पर्यंतच्या सर्व नैसर्गिक संख्यांची बेरीज किती होईल?', '२१०', '२००', '१९०', '२२०', 'A', 'नैसर्गिक संख्यांची बेरीज = [n × (n + १)] / २ = [२० × २१] / २ = २१०.');
INSERT INTO public.questions (subject_tag, subtopic_tag, question_text, option_a, option_b, option_c, option_d, correct_option, explanation) VALUES ('node_4', 'General', 'खालीलपैकी ''अनुज'' या शब्दाचा विरुद्धार्थी शब्द कोणता?', 'अग्रज', 'लहान', 'भाऊ', 'सुपुत्र', 'A', '''अनुज'' म्हणजे मागाहून (लहान) जन्मलेला आणि ''अग्रज'' म्हणजे आधी (मोठा) जन्मलेला.');
INSERT INTO public.questions (subject_tag, subtopic_tag, question_text, option_a, option_b, option_c, option_d, correct_option, explanation) VALUES ('node_4', 'General', '''पी हळद नि हो गोरी'' या म्हणीचा योग्य अर्थ सांगा.', 'हळद लावणे', 'अतिशय उतावळेपणा दाखवणे', 'रंग गोरा होणे', 'औषध घेणे', 'B', 'कोणत्याही कृतीचा निकाल लगेच मिळावा म्हणून दाखवलेला उतावळेपणा म्हणजे ''पी हळद नि हो गोरी''.');
INSERT INTO public.questions (subject_tag, subtopic_tag, question_text, option_a, option_b, option_c, option_d, correct_option, explanation) VALUES ('node_4', 'General', '१०, १५, २०, २५, ३० यांची सरासरी किती?', '१५', '२०', '२५', '१८', 'B', 'समान फरक असलेल्या मालिकेतील मधली संख्या म्हणजेच २० ही तिची सरासरी असते. (किंवा १०० / ५ = २०).');
INSERT INTO public.questions (subject_tag, subtopic_tag, question_text, option_a, option_b, option_c, option_d, correct_option, explanation) VALUES ('node_4', 'General', '''आकाशात जेव्हा ढग जमतात, तेव्हा मोर नाचू लागतो.'' - हे कोणत्या प्रकारचे वाक्य आहे?', 'केवल वाक्य', 'संयुक्त वाक्य', 'मिश्र वाक्य', 'आज्ञार्थी वाक्य', 'C', 'जेव्हा-तेव्हा या संबंधी उभयान्वयी अव्ययाने जोडलेली मुख्य आणि गौण वाक्ये मिळून ''मिश्र वाक्य'' बनते.');
INSERT INTO public.questions (subject_tag, subtopic_tag, question_text, option_a, option_b, option_c, option_d, correct_option, explanation) VALUES ('node_4', 'General', 'दोन संख्यांचा गुणाकार २४० आहे आणि मसावी ४ आहे, तर त्यांचा लसावी किती?', '६०', '८०', '१२०', '४०', 'A', 'लसावी × मसावी = दोन संख्यांचा गुणाकार => लसावी × ४ = २४० => लसावी = २४० / ४ = ६०.');
INSERT INTO public.questions (subject_tag, subtopic_tag, question_text, option_a, option_b, option_c, option_d, correct_option, explanation) VALUES ('node_4', 'General', '''झाडावरून फळ पडले.'' या वाक्यातील ''झाडावरून'' या शब्दाची विभक्ती ओळखा.', 'तृतीया', 'चतुर्थी', 'पंचमी', 'सप्तमी', 'C', '''वरून'' किंवा ''हून'' हे प्रत्यय वियोगाचा (वियोग/दुरावा) अर्थ दर्शवतात, जे पंचमी विभक्तीत येतात.');
INSERT INTO public.questions (subject_tag, subtopic_tag, question_text, option_a, option_b, option_c, option_d, correct_option, explanation) VALUES ('node_4', 'General', 'दिशेवरील प्रश्न: उत्तर दिशेला तोंड असलेली व्यक्ती उजवीकडे ९०° फिरल्यास तिचे तोंड कोणत्या दिशेला असेल?', 'पूर्व', 'पश्चिम', 'दक्षिण', 'उत्तर', 'A', 'उत्तरेकडून ९० अंश उजवीकडे (घड्याळाच्या दिशेने) फिरल्यास ''पूर्व'' दिशा येते.');
INSERT INTO public.questions (subject_tag, subtopic_tag, question_text, option_a, option_b, option_c, option_d, correct_option, explanation) VALUES ('node_4', 'General', 'एका आयताची लांबी १५ सेमी व रुंदी ८ सेमी आहे, तर त्याची परिमिती किती?', '४६ सेमी', '२३ सेमी', '१२० सेमी', '६० सेमी', 'A', 'आयताची परिमिती = २ × (लांबी + रुंदी) = २ × (१५ + ८) = २ × २३ = ४६ सेमी.');
INSERT INTO public.questions (subject_tag, subtopic_tag, question_text, option_a, option_b, option_c, option_d, correct_option, explanation) VALUES ('node_4', 'General', 'महाराष्ट्रात पंचायत राज व्यवस्थेची सुरुवात कधी झाली?', '१ मे १९६२', '१ मे १९६०', '१५ ऑगस्ट १९४७', '२६ जानेवारी १९५०', 'A', 'वसंतराव नाईक समितीच्या शिफारशींनुसार महाराष्ट्रात १ मे १९६२ पासून त्रिस्तरीय पंचायत राज व्यवस्था लागू करण्यात आली.');
INSERT INTO public.questions (subject_tag, subtopic_tag, question_text, option_a, option_b, option_c, option_d, correct_option, explanation) VALUES ('node_4', 'General', 'महाराष्ट्र पोलिसांचे ''Anti-Terrorism Squad'' (ATS) प्रमुख अधिकारी कोण असतात?', 'अप्पर पोलीस महासंचालक दर्जाचे अधिकारी', 'पोलीस अधीक्षक', 'पोलीस उपनिरीक्षक', 'गृहमंत्री', 'A', 'महाराष्ट्र ATS चे नेतृत्व ADGP (अप्पर पोलीस महासंचालक) किंवा तत्सम दर्जाचे वरिष्ठ आयपीएस अधिकारी करतात.');
INSERT INTO public.questions (subject_tag, subtopic_tag, question_text, option_a, option_b, option_c, option_d, correct_option, explanation) VALUES ('node_5', 'General', 'भारतीय राज्यघटनेत ''मूलभूत हक्क'' कोणत्या भागामध्ये दिले आहेत?', 'भाग १', 'भाग २', 'भाग ३', 'भाग ४', 'C', 'संविधानाच्या भाग ३ मधील कलम १२ ते ३५ दरम्यान नागरिकांचे मूलभूत हक्क नमूद आहेत.');
INSERT INTO public.questions (subject_tag, subtopic_tag, question_text, option_a, option_b, option_c, option_d, correct_option, explanation) VALUES ('node_5', 'General', 'सरदार वल्लभभाई पटेल यांचा प्रसिद्ध ''स्टॅच्यू ऑफ युनिटी'' पुतळा कोणत्या राज्यात आहे?', 'महाराष्ट्र', 'गुजरात', 'राजस्थान', 'मध्य प्रदेश', 'B', 'गुजरात राज्यातील नर्मदा नदीकाठी केवडिया येथे १८२ मीटर उंच ''स्टॅच्यू ऑफ युनिटी'' उभारण्यात आला आहे.');
INSERT INTO public.questions (subject_tag, subtopic_tag, question_text, option_a, option_b, option_c, option_d, correct_option, explanation) VALUES ('node_5', 'General', 'मालिकेतील विसंगत संख्या ओळखा: ८, २७, ६४, १००, १२५, २१६', '२७', '६४', '१००', '१२५', 'C', '८(२³), २७(३³), ६४(४³), १२५(५³), २१६(६³) या पूर्ण घनमूळ संख्या आहेत; १०० हा १० चा वर्ग आहे, घन नाही.');
INSERT INTO public.questions (subject_tag, subtopic_tag, question_text, option_a, option_b, option_c, option_d, correct_option, explanation) VALUES ('node_5', 'General', 'नातेसंबंध: ''राम हा श्यामचा भाऊ आहे, श्याम ही तानाची बहीण आहे, तर रामचा तानाशी संबंध काय?''', 'काका', 'भाऊ', 'वडील', 'मुलगा', 'B', 'राम आणि श्याम भाऊ-बहीण आहेत आणि श्याम व ताना बहिणी आहेत. त्यामुळे राम हा तानाचा भाऊ आहे.');
INSERT INTO public.questions (subject_tag, subtopic_tag, question_text, option_a, option_b, option_c, option_d, correct_option, explanation) VALUES ('node_5', 'General', '१२ च्या पहिल्या ५ पटींची बेरीज किती होईल?', '१५०', '१८०', '२००', '१२०', 'B', '१२ च्या पहिल्या ५ पटी: १२, २४, ३६, ४८, ६०. बेरीज = १२ + २४ + ३६ + ४८ + ६० = १८०.');
INSERT INTO public.questions (subject_tag, subtopic_tag, question_text, option_a, option_b, option_c, option_d, correct_option, explanation) VALUES ('node_5', 'General', 'अजंठा आणि वेरूळच्या प्रसिद्ध लेण्या कोणत्या जिल्ह्यात आहेत?', 'नाशिक', 'छत्रपती संभाजीनगर', 'पुणे', 'सातारा', 'B', 'जागतिक वारसा स्थळ असलेल्या अजंठा व वेरूळच्या लेण्या छत्रपती संभाजीनगर (औरंगाबाद) जिल्ह्यात आहेत.');
INSERT INTO public.questions (subject_tag, subtopic_tag, question_text, option_a, option_b, option_c, option_d, correct_option, explanation) VALUES ('node_5', 'General', '''काठोकाठ'' या शब्दाचा समास ओळखा.', 'अव्ययीभाव समास', 'तत्पुरुष समास', 'द्वंद्व समास', 'बहुव्रीहि समास', 'A', 'काठोकाठ (काठावर) ही द्विरुक्ती होऊन तयार झालेला शब्द अव्ययीभाव समासाचे उदाहरण आहे.');
INSERT INTO public.questions (subject_tag, subtopic_tag, question_text, option_a, option_b, option_c, option_d, correct_option, explanation) VALUES ('node_5', 'General', '२५० चे ४०% = किती?', '८०', '१००', '१२०', '१५०', 'B', '(२५० × ४०) / १०० = १००.');
INSERT INTO public.questions (subject_tag, subtopic_tag, question_text, option_a, option_b, option_c, option_d, correct_option, explanation) VALUES ('node_5', 'General', 'एका चौरसाची परिमिती ३६ सेमी आहे, तर त्याचे क्षेत्रफळ किती चौरस सेमी?', '६४', '८१', '१००', '१४४', 'B', 'बाजू = ३६ / ४ = ९ सेमी. क्षेत्रफळ = बाजू² = ९² = ८१ चौ सेमी.');
INSERT INTO public.questions (subject_tag, subtopic_tag, question_text, option_a, option_b, option_c, option_d, correct_option, explanation) VALUES ('node_5', 'General', 'विसंगत पर्याय ओळखा: नाक, कान, डोळा, यकृत', 'नाक', 'कान', 'डोळा', 'यकृत', 'D', 'नाक, कान व डोळा हे बाह्य ज्ञानेंद्रिये आहेत, तर ''यकृत'' हा शरीरातील अंतर्गत अवयव आहे.');
INSERT INTO public.questions (subject_tag, subtopic_tag, question_text, option_a, option_b, option_c, option_d, correct_option, explanation) VALUES ('node_5', 'General', 'महाराष्ट्र पोलीस दलाच्या ध्वजाचा रंग कोणता आहे?', 'गडद निळा', 'लाल', 'हिरवा', 'केशरी', 'A', 'महाराष्ट्र पोलीस दलाच्या अधिकृत ध्वजाचा रंग गडद निळा असून त्यावर पंचकोनी तारा व सद्रक्षणाय खलनिग्रहणाय हे ब्रीदवाक्य आहे.');
INSERT INTO public.questions (subject_tag, subtopic_tag, question_text, option_a, option_b, option_c, option_d, correct_option, explanation) VALUES ('node_5', 'General', '१० ते २० च्या दरम्यान असणाऱ्या मूळ संख्यांची बेरीज किती?', '६०', '६५', '६०', '६०', 'A', '१० ते २० दरम्यानच्या मूळ संख्या: ११, १३, १७, १९. बेरीज = ११ + १३ + १७ + १९ = ६०.');
INSERT INTO public.questions (subject_tag, subtopic_tag, question_text, option_a, option_b, option_c, option_d, correct_option, explanation) VALUES ('node_5', 'General', 'मालिकेतील विसंगत संख्या शोधा: ३, ५, ७, ९, ११, १३', '५', '७', '९', '११', 'C', '३, ५, ७, ११, १३ या सर्व मूळ संख्या (Prime Numbers) आहेत, परंतु ९ ही संयुक्त संख्या आहे.');
INSERT INTO public.questions (subject_tag, subtopic_tag, question_text, option_a, option_b, option_c, option_d, correct_option, explanation) VALUES ('node_5', 'General', 'एका सांकेतिक भाषेत ''PEN'' ला ''16514'' लिहितात, तर ''RED'' ला काय लिहितील?', '1854', '1853', '1954', '1754', 'A', 'अक्षरांचे इंग्रजी वर्णमालेतील क्रमांक: R=18, E=5, D=4 => 1854.');
INSERT INTO public.questions (subject_tag, subtopic_tag, question_text, option_a, option_b, option_c, option_d, correct_option, explanation) VALUES ('node_5', 'General', 'एका त्रिकोणाचे दोन कोन ६०° आणि ५०° आहेत, तर तिसऱ्या कोनाचे माप किती असेल?', '७०°', '८०°', '९०°', '६०°', 'A', 'त्रिकोणाच्या तिन्ही कोनांची बेरीज १८०° असते. तिसरा कोन = १८०° - (६०° + ५०°) = १८०° - ११०° = ७०°.');
INSERT INTO public.questions (subject_tag, subtopic_tag, question_text, option_a, option_b, option_c, option_d, correct_option, explanation) VALUES ('node_5', 'General', 'इन्सुलिन (Insulin) हे संप्रेरक मानवी शरीरातील कोणत्या अवयवातून स्रवते?', 'यकृत', 'स्वादुपिंड (Pancreas)', 'वृक्क (Kidney)', 'लाळग्रंथी', 'B', 'स्वादुपिंडातील बिटा-पेशींद्वारे इन्सुलिन स्रवते, जे रक्तातील साखरेचे प्रमाण नियंत्रित ठेवते.');
INSERT INTO public.questions (subject_tag, subtopic_tag, question_text, option_a, option_b, option_c, option_d, correct_option, explanation) VALUES ('node_5', 'General', 'एका घनाचे (Cube) घनफळ ६४ घ सेमी आहे, तर त्याच्या एका बाजूची लांबी किती?', '२ सेमी', '४ सेमी', '८ सेमी', '१६ सेमी', 'B', 'घनाचे घनफळ = बाजू³ => बाजू³ = ६४ => बाजू = ∛६४ = ४ सेमी.');
INSERT INTO public.questions (subject_tag, subtopic_tag, question_text, option_a, option_b, option_c, option_d, correct_option, explanation) VALUES ('node_5', 'General', 'वि सु संग त ओ ळ खा: वाघ, सिंह, हत्ती, बिबट्या', 'वाघ', 'सिंह', 'हत्ती', 'बिबट्या', 'C', 'वाघ, सिंह आणि बिबट्या हे मांजर कुळातील मांसाहारी प्राणी आहेत, तर हत्ती हा शाकाहारी प्राणी आहे.');
INSERT INTO public.questions (subject_tag, subtopic_tag, question_text, option_a, option_b, option_c, option_d, correct_option, explanation) VALUES ('node_5', 'General', 'जर ०.०४ × ०.५ = ?', '०.२', '०.०२', '०.००२', '२.०', 'B', '४ × ५ = २०. दोन संख्यांमधील एकूण ३ अंकांनंतर दशांश चिन्ह दिल्यास ०.०२० म्हणजेच ०.०२ उत्तर येते.');
INSERT INTO public.questions (subject_tag, subtopic_tag, question_text, option_a, option_b, option_c, option_d, correct_option, explanation) VALUES ('node_5', 'General', '''ज्याला सीमा नाही असा'' या शब्दसमूहाबद्दल एक शब्द ओळखा.', 'असीम', 'ससीम', 'असीमत्व', 'असीम बहु', 'A', 'ज्याला कोणतीही सीमा किंवा मर्यादा नसते त्याला ''असीम'' किंवा ''अमर्याद'' म्हणतात.');
INSERT INTO public.questions (subject_tag, subtopic_tag, question_text, option_a, option_b, option_c, option_d, correct_option, explanation) VALUES ('node_5', 'General', 'विधानसभेचा कार्यकाळ सामान्यतः किती वर्षांचा असतो?', '५ वर्षे', '६ वर्षे', '४ वर्षे', '२ वर्षे', 'A', 'विधानसभेची मुदत पहिल्या बैठकीपासून ५ वर्षांची असते.');
INSERT INTO public.questions (subject_tag, subtopic_tag, question_text, option_a, option_b, option_c, option_d, correct_option, explanation) VALUES ('node_5', 'General', '''पक्षी आकाशात उडतात.'' या वाक्यातील क्रियापद ओळखा.', 'पक्षी', 'आकाशात', 'उडतात', 'उडणारे', 'C', 'वाक्याचा अर्थ पूर्ण करणाऱ्या क्रियावाचक शब्दाला क्रियापद म्हणतात, म्हणून ''उडतात'' हे क्रियापद आहे.');
INSERT INTO public.questions (subject_tag, subtopic_tag, question_text, option_a, option_b, option_c, option_d, correct_option, explanation) VALUES ('node_5', 'General', '१०, २०, ३०, ४० यांची सरासरी किती येईल?', '२०', '२५', '३०', '३५', 'B', 'सरासरी = (१० + २० + ३० + ४०) / ४ = १०० / ४ = २५.');
INSERT INTO public.questions (subject_tag, subtopic_tag, question_text, option_a, option_b, option_c, option_d, correct_option, explanation) VALUES ('node_5', 'General', 'रांगेत अजयचा पुढून ८ वा आणि मागून १२ वा क्रमांक आहे, तर रांगेत एकूण किती लोक आहेत?', '१९', '२०', '२१', '१८', 'A', 'एकूण = (८ + १२) - १ = २० - १ = १९ लोक.');
INSERT INTO public.questions (subject_tag, subtopic_tag, question_text, option_a, option_b, option_c, option_d, correct_option, explanation) VALUES ('node_5', 'General', '''माझे कुटुंब, माझी जबाबदारी'' ही मोहीम कोणत्या राज्याने सुरू केली होती?', 'गुजरात', 'महाराष्ट्र', 'कर्नाटक', 'मध्य प्रदेश', 'B', 'कोविड-१९ काळात आरोग्य जनजागृतीसाठी महाराष्ट्र शासनाने ही प्रसिद्ध मोहीम राबवली होती.');
INSERT INTO public.questions (subject_tag, subtopic_tag, question_text, option_a, option_b, option_c, option_d, correct_option, explanation) VALUES ('node_5', 'General', 'महाराष्ट्रातील ''प्रवरानदी'' काठी वसलेले प्रसिद्ध देवस्थान कोणते?', 'नेवासे', 'प पंढरपूर', 'शेगाव', 'तुळजापूर', 'A', 'ज्ञानेश्वरांनी भावार्थदीपिका (ज्ञानेश्वरी) जिथे लिहिली ते नेवासे प्रवरा नदीकाठी आहे.');
INSERT INTO public.questions (subject_tag, subtopic_tag, question_text, option_a, option_b, option_c, option_d, correct_option, explanation) VALUES ('node_5', 'General', 'महाराष्ट्रात कुपोषणमुक्तीसाठी प्रसिद्ध असणारा ''मेळघाट'' प्रदेश कोणत्या जिल्ह्यात आहे?', 'अमरावती', 'नागपूर', 'यवतमाळ', 'धुळे', 'A', 'मेळघाट हा आदिवासी व अभयारण्य क्षेत्र अमरावती जिल्ह्यात येतो.');
INSERT INTO public.questions (subject_tag, subtopic_tag, question_text, option_a, option_b, option_c, option_d, correct_option, explanation) VALUES ('node_5', 'General', 'एका त्रिकोणाचा पाया १० सेमी व उंची ८ सेमी असल्यास त्याचे क्षेत्रफळ किती?', '८० चौ सेमी', '४० चौ सेमी', '२० चौ सेमी', '६० चौ सेमी', 'B', 'त्रिकोणाचे क्षेत्रफळ = १/२ × पाया × उंची = १/२ × १० × ८ = ४० चौ सेमी.');
INSERT INTO public.questions (subject_tag, subtopic_tag, question_text, option_a, option_b, option_c, option_d, correct_option, explanation) VALUES ('node_5', 'General', 'मानवी शरीरातील सर्वात मोठी ग्रंथी कोणती आहे?', 'यकृत (Liver)', 'वृक्क (Kidney)', 'हृदय (Heart)', 'लाळग्रंथी', 'A', 'यकृत (Liver) ही मानवी शरीरातील सर्वात मोठी अंतःस्रावी व पचनसंस्थेशी संबंधित ग्रंथी आहे.');
INSERT INTO public.questions (subject_tag, subtopic_tag, question_text, option_a, option_b, option_c, option_d, correct_option, explanation) VALUES ('node_5', 'General', '०.०५ × ०.६ = किती?', '०.३', '०.०३', '०.००३', '३.०', 'B', '५ × ६ = ३०. तीन दशांश स्थानांनंतर चिन्ह दिल्यास ०.०३० म्हणजेच ०.०३ उत्तर येते.');
INSERT INTO public.questions (subject_tag, subtopic_tag, question_text, option_a, option_b, option_c, option_d, correct_option, explanation) VALUES ('node_5', 'General', 'संगणकाचा (Computer) मेंदू कोणाला म्हटले जाते?', 'RAM', 'Hard Disk', 'CPU', 'Monitor', 'C', 'Central Processing Unit (CPU) ला संगणकाचा मुख्य प्रक्रिया करणारा भाग किंवा मेंदू म्हटले जाते.');
INSERT INTO public.questions (subject_tag, subtopic_tag, question_text, option_a, option_b, option_c, option_d, correct_option, explanation) VALUES ('node_5', 'General', 'ताशी ६० किमी वेगाने जाणारी गाडी ५ तासांत किती अंतर कापेल?', '२५० किमी', '३०० किमी', '३५० किमी', '४०० किमी', 'B', 'अंतर = ६० × ५ = ३०० किमी.');
INSERT INTO public.questions (subject_tag, subtopic_tag, question_text, option_a, option_b, option_c, option_d, correct_option, explanation) VALUES ('node_5', 'General', 'भारताचा सर्वोच्च नागरी पुरस्कार कोणता?', 'पद्मश्री', 'पद्मभूषण', 'पद्मविभूषण', 'भारतरत्न', 'D', '''भारतरत्न'' हा भारत सरकारद्वारे दिला जाणारा सर्वोच्च नागरी सन्मान आहे.');
INSERT INTO public.questions (subject_tag, subtopic_tag, question_text, option_a, option_b, option_c, option_d, correct_option, explanation) VALUES ('node_5', 'General', '''महान राष्ट्र = महाराष्ट्र'' हा कोणता समास आहे?', 'कर्मधारय समास', 'द्विगु समास', 'अव्ययीभाव समास', 'द्वंद्व समास', 'A', 'ज्या समासातील दोन्ही पदे एकाच विभक्तीत असतात व पहिले पद विशेषण असते, त्याला कर्मधारय समास म्हणतात.');
INSERT INTO public.questions (subject_tag, subtopic_tag, question_text, option_a, option_b, option_c, option_d, correct_option, explanation) VALUES ('node_5', 'General', 'महाराष्ट्र पोलिसांचे ब्रीदवाक्य काय आहे?', 'सत्यमेव जयते', 'सद्रक्षणाय खलनिग्रहणाय', 'बहुजन हिताय बहुजन सुखाय', 'सेवा आणि कर्तव्य', 'B', '''सद्रक्षणाय खलनिग्रहणाय'' म्हणजे सज्जनांचे रक्षण आणि दुर्जनांचा नाश करणे, हे महाराष्ट्र पोलिसांचे अधिकृत ब्रीदवाक्य आहे.');
INSERT INTO public.questions (subject_tag, subtopic_tag, question_text, option_a, option_b, option_c, option_d, correct_option, explanation) VALUES ('node_5', 'General', 'माधुरीचा जन्म रविवारी ५ मार्च रोजी झाला, तर त्याच महिन्यात २६ मार्च रोजी कोणता वार असेल?', 'शनिवार', 'रविवार', 'सोमवार', 'मंगळवार', 'B', 'दिवसांतील फरक = २६ - ५ = २१ दिवस. २१ ला ७ ने भागल्यास बाकी ० उरते, त्यामुळे वार तोच म्हणजेच ''रविवार'' राहील.');
INSERT INTO public.questions (subject_tag, subtopic_tag, question_text, option_a, option_b, option_c, option_d, correct_option, explanation) VALUES ('node_5', 'General', 'भारतीय राज्यघटनेचे शिल्पकार कोणाला मानले जाते?', 'डॉ. बी. आर. आंबेडकर', 'पंडित जवाहरलाल नेहरू', 'डॉ. राजेंद्र प्रसाद', 'महात्मा गांधी', 'A', 'भारताच्या मसुदा समितीचे अध्यक्ष डॉ. बाबासाहेब आंबेडकर यांना भारतीय राज्यघटनेचे शिल्पकार मानले जाते.');
INSERT INTO public.questions (subject_tag, subtopic_tag, question_text, option_a, option_b, option_c, option_d, correct_option, explanation) VALUES ('node_5', 'General', 'सत्यशोधक समाजाची स्थापना कोणी केली?', 'स्वामी विवेकानंद', 'म महात्मा जोतीराव फुले', 'राजा राममोहन रॉय', 'महर्षी विठ्ठल रामजी शिंदे', 'B', 'महात्मा जोतीराव फुले यांनी २४ सप्टेंबर १८७३ रोजी पुण्यात सत्यशोधक समाजाची स्थापना केली.');
INSERT INTO public.questions (subject_tag, subtopic_tag, question_text, option_a, option_b, option_c, option_d, correct_option, explanation) VALUES ('node_5', 'General', '२५ चा वर्ग आणि १५ चा वर्ग यांमधील फरक किती?', '४००', '३००', '३५०', '२००', 'A', '२५² = ६२५, १५² = २२५. फरक = ६२५ - २२५ = ४००.');
INSERT INTO public.questions (subject_tag, subtopic_tag, question_text, option_a, option_b, option_c, option_d, correct_option, explanation) VALUES ('node_5', 'General', '१२ च्या पहिल्या ५ पट संख्यांची (Multiples) सरासरी किती?', '३०', '३६', '४२', '४८', 'B', 'पहिली संख्या १२, पाचवी ६०. सरासरी = (१२ + ६०) / २ = ३६.');
INSERT INTO public.questions (subject_tag, subtopic_tag, question_text, option_a, option_b, option_c, option_d, correct_option, explanation) VALUES ('node_5', 'General', 'A हा B चा मुलगा आहे. B ही C ची आई आहे. तर A हा C चा कोण?', 'भाऊ', 'वडील', 'काका', 'मुलगा', 'A', 'A आणि C ची आई B आहे, त्यामुळे A हा C चा ''भाऊ'' असेल.');
INSERT INTO public.questions (subject_tag, subtopic_tag, question_text, option_a, option_b, option_c, option_d, correct_option, explanation) VALUES ('node_5', 'General', 'सूर्यकुलातील सर्वात मोठा ग्रह कोणता?', 'पृथ्वी', 'मंगल', 'गुरु', 'शनि', 'C', 'सूर्यमालेतील आकाराने सर्वात मोठा ग्रह ''गुरु'' (Jupiter) हा आहे.');
INSERT INTO public.questions (subject_tag, subtopic_tag, question_text, option_a, option_b, option_c, option_d, correct_option, explanation) VALUES ('node_5', 'General', '''निसर्ग'' या शब्दाचे विशेषण काय होईल?', 'नैसर्गिक', 'निसर्गात', 'निसर्गाचा', 'निसर्गी', 'A', '''निसर्ग'' या नामापासून ''नैसर्गिक'' हे विशेषण तयार होते.');
INSERT INTO public.questions (subject_tag, subtopic_tag, question_text, option_a, option_b, option_c, option_d, correct_option, explanation) VALUES ('node_5', 'General', '१ ते ३० मधील सर्व विषम संख्यांची बेरीज किती?', '२१०', '२२५', '२४०', '२५०', 'B', '१ ते ३० मध्ये एकूण १५ विषम संख्या आहेत. विषम संख्यांची बेरीज = n² = १५² = २२५.');
INSERT INTO public.questions (subject_tag, subtopic_tag, question_text, option_a, option_b, option_c, option_d, correct_option, explanation) VALUES ('node_5', 'General', 'भारताचे राष्ट्रीय प्रतीक (National Emblem) कोठून घेण्यात आले आहे?', 'अजंठा लेणी', 'सारनाथ येथील अशोकस्तंभ', 'सांची स्तूप', 'खजुराहो मंदिर', 'B', 'वाराणसीजवळील सारनाथ येथील सम्राट अशोकाच्या सिंहस्तंभावरून भारताचे राष्ट्रीय राजचिन्ह स्वीकारण्यात आले आहे.');
INSERT INTO public.questions (subject_tag, subtopic_tag, question_text, option_a, option_b, option_c, option_d, correct_option, explanation) VALUES ('node_5', 'General', 'एका माणसाकडे काही कोंबड्या व काही गाई आहेत. त्यांच्या डोक्यांची संख्या ४० आणि पायांची संख्या १३० आहे, तर गाईंची संख्या किती?', '१५', '२५', '२०', '३०', 'B', 'गाईंची संख्या = (एकूण पाय - २ × डोके) / २ = (१३० - ८०) / २ = ५० / २ = २५ गाई.');
INSERT INTO public.questions (subject_tag, subtopic_tag, question_text, option_a, option_b, option_c, option_d, correct_option, explanation) VALUES ('node_5', 'General', '''राम आंबा खातो'' या वाक्यातील प्रयोग ओळखा.', 'कर्तरी प्रयोग', 'कर्मणी प्रयोग', 'भावे प्रयोग', 'अकर्मक प्रयोग', 'A', 'येथे कर्त्याच्या (राम) लिंग/वचनानुसार क्रियापद बदलते (उदा. सीता आंबा खाते), म्हणून हा कर्तरी प्रयोग आहे.');
INSERT INTO public.questions (subject_tag, subtopic_tag, question_text, option_a, option_b, option_c, option_d, correct_option, explanation) VALUES ('node_5', 'General', 'खालीलपैकी कोणता शब्द ''पृथ्वी'' या शब्दाचा समानार्थी नाही?', 'वसुंधरा', 'अवनी', 'भूमी', 'सरिता', 'D', 'वसुंधरा, अवनी आणि भूमी हे पृथ्वीचे समानार्थी शब्द आहेत; तर ''सरिता'' म्हणजे नदी.');
INSERT INTO public.questions (subject_tag, subtopic_tag, question_text, option_a, option_b, option_c, option_d, correct_option, explanation) VALUES ('node_5', 'General', '''अनुज'' या शब्दाचा अर्थ काय होतो?', 'आधी जन्मलेला (मोठा भाऊ)', 'मागाहून जन्मलेला (लहान भाऊ)', 'एकुलता एक', 'भाच्याचे नाव', 'B', 'अनु (नंतर) + ज (जन्मलेला) = मागाहून जन्मलेला म्हणजेच लहान भाऊ. आधी जन्मलेल्यास ''अग्रज'' म्हणतात.');
INSERT INTO public.questions (subject_tag, subtopic_tag, question_text, option_a, option_b, option_c, option_d, correct_option, explanation) VALUES ('node_5', 'General', 'नातेसंबंध: ''माझ्या भावाच्या एकमेव बहिणीचा मुलगा माझा कोण लागेल?''', 'भाचा', 'मुलगा', 'काका', 'भाऊ', 'B', 'जर बोलणारी व्यक्ती स्त्री असेल, तर तिच्या भावाची एकमेव बहीण ती स्वतःच असेल. त्यामुळे तिच्या बहिणीचा (तिचा) मुलगा हा तिचा ''मुलगा'' लागेल.');
INSERT INTO public.questions (subject_tag, subtopic_tag, question_text, option_a, option_b, option_c, option_d, correct_option, explanation) VALUES ('node_5', 'General', 'दरसाल दरशेकडा ५% दराने ₹४००० चे ३ वर्षांचे सरळव्याज किती?', '₹५००', '₹६००', '₹७००', '₹८००', 'B', 'सरळव्याज = (मुद्दल × दर × मुदत) / १०० = (४००० × ५ × ३) / १०० = ६०० रुपये.');
INSERT INTO public.questions (subject_tag, subtopic_tag, question_text, option_a, option_b, option_c, option_d, correct_option, explanation) VALUES ('node_5', 'General', 'भारताचे राष्ट्रीय गाणे ''वंदे मातरम'' कोणी लिहिले?', 'रवींद्रनाथ टागोर', 'बंकिमचंद्र चटर्जी', 'महर्षी वाल्मिकी', 'लोकमान्य टिळक', 'B', '''आनंदमठ'' या कादंबरीतील ''वंदे मातरम'' हे गीत बंकिमचंद्र चटर्जी यांनी लिहिले.');
INSERT INTO public.questions (subject_tag, subtopic_tag, question_text, option_a, option_b, option_c, option_d, correct_option, explanation) VALUES ('node_5', 'General', 'जर २५ × ४ = १००, तर २५ × ०.४ = किती?', '१', '१०', '१०-', '०.१', 'B', '२५ × ४ = १००. इथे एका अंकानंतर दशांश चिन्ह (point) आहे, त्यामुळे १०० च्या ऐवजी १०.० म्हणजेच १० उत्तर येईल.');
INSERT INTO public.questions (subject_tag, subtopic_tag, question_text, option_a, option_b, option_c, option_d, correct_option, explanation) VALUES ('node_5', 'General', 'एका त्रिकोणाच्या तिन्ही कोनांच्या मापांची बेरीज किती असते?', '९०°', '३६०°', '१८०°', '२७०°', 'C', 'भूमितीच्या नियमानुसार कोणत्याही त्रिकोणाच्या तिन्ही अंतःकोनांच्या मापांची बेरीज नेहमी १८० अंश असते.');
INSERT INTO public.questions (subject_tag, subtopic_tag, question_text, option_a, option_b, option_c, option_d, correct_option, explanation) VALUES ('node_5', 'General', 'जर a : b = 3 : 4 आणि b : c = 8 : 9, तर a : c = ?', '1 : 2', '2 : 3', '3 : 2', '4 : 3', 'B', '(a/b) × (b/c) = (3/4) × (8/9) = 24/36 = 2/3.');
INSERT INTO public.questions (subject_tag, subtopic_tag, question_text, option_a, option_b, option_c, option_d, correct_option, explanation) VALUES ('node_5', 'General', 'महाराष्ट्राची सांस्कृतिक राजधानी कोणती मानली जाते?', 'मुंबई', 'नागपूर', 'पुणे', 'नाशिक', 'C', 'शिक्षणाचे माहेरघर व ऐतिहासिक वारशामुळे पुण्याला महाराष्ट्राची सांस्कृतिक राजधानी मानले जाते.');
INSERT INTO public.questions (subject_tag, subtopic_tag, question_text, option_a, option_b, option_c, option_d, correct_option, explanation) VALUES ('node_5', 'General', 'एका रांगेत सीताचा क्रमांक डावीकडून १० वा आणि उजवीकडून १५ वा आहे, तर रांगेत एकूण किती मुली आहेत?', '२४', '२५', '२६', '२३', 'A', 'एकूण व्यक्ती = (डावीकडील स्थान + उजवीकडील स्थान) - १ = (१० + १५) - १ = २४.');
INSERT INTO public.questions (subject_tag, subtopic_tag, question_text, option_a, option_b, option_c, option_d, correct_option, explanation) VALUES ('node_5', 'General', 'मराठी भाषेत ''प्रयोग'' चे मुख्य प्रकार किती आहेत?', '२', '३', '४', '५', 'B', 'मराठी व्याकरणात प्रयोगाचे कर्तरी, कर्मणी आणि भावे असे मुख्य ३ प्रकार आहेत.');
INSERT INTO public.questions (subject_tag, subtopic_tag, question_text, option_a, option_b, option_c, option_d, correct_option, explanation) VALUES ('node_5', 'General', 'जर x/४ = ५, तर x = ?', '१५', '२०', '२५', '१०', 'B', 'x = ५ × ४ = २०.');
INSERT INTO public.questions (subject_tag, subtopic_tag, question_text, option_a, option_b, option_c, option_d, correct_option, explanation) VALUES ('node_5', 'General', 'भारताच्या पहिल्या महिला पंतप्रधान कोण होत्या?', 'प्रतिभाताई पाटील', 'इंदिरा गांधी', 'सुलभ सोरबजी', 'सरोजिनी नायडू', 'B', 'श्रीमती इंदिरा गांधी या १९६६ मध्ये भारताच्या पहिल्या महिला पंतप्रधान बनल्या.');
INSERT INTO public.questions (subject_tag, subtopic_tag, question_text, option_a, option_b, option_c, option_d, correct_option, explanation) VALUES ('node_5', 'General', 'सत्यशोधक समाजाची स्थापना कोणी केली?', 'स्वामी विवेकानंद', 'राजा राममोहन रॉय', 'महात्मा महात्मा जोतीराव फुले', 'महर्षी कर्वे', 'C', '२४ सप्टेंबर १८७३ रोजी पुण्यात महात्मा जोतीराव फुले यांनी सत्यशोधक समाजाची स्थापना केली.');
INSERT INTO public.questions (subject_tag, subtopic_tag, question_text, option_a, option_b, option_c, option_d, correct_option, explanation) VALUES ('node_5', 'General', 'महाराष्ट्रात ''कांदा-लसूण संशोधक केंद्र'' कोठे स्थित आहे?', 'पालेगाव (नाशिक)', 'राजगुरूनगर (पुणे)', 'राहुरी (अहमदनगर)', 'सोलापूर', 'B', 'राष्ट्रीय कांदा आणि लसूण संशोधन केंद्र राजगुरूनगर (जि. पुणे) येथे आहे.');
INSERT INTO public.questions (subject_tag, subtopic_tag, question_text, option_a, option_b, option_c, option_d, correct_option, explanation) VALUES ('node_5', 'General', 'आरबीआय (RBI) चे मुख्यालय कोठे आहे?', 'नवी दिल्ली', 'मुंबई', 'कोलकाता', 'बंगळुरू', 'B', 'भारतीय रिझर्व्ह बँक (Reserve Bank of India) चे केंद्रीय मुख्यालय मुंबई येथे आहे.');
INSERT INTO public.questions (subject_tag, subtopic_tag, question_text, option_a, option_b, option_c, option_d, correct_option, explanation) VALUES ('node_5', 'General', 'ताशी ९० किमी वेगाने जाणारी ट्रेन एका सेकंदात किती मीटर अंतर कापेल?', '२० मीटर', '२५ मीटर', '३० मीटर', '१५ मीटर', 'B', 'किमी/तास चे मीटर/सेकंद मध्ये रूपांतर करण्यासाठी ५/१८ ने गुणतात. ९० × (५/१८) = २५ मीटर/सेकंद.');
INSERT INTO public.questions (subject_tag, subtopic_tag, question_text, option_a, option_b, option_c, option_d, correct_option, explanation) VALUES ('node_5', 'General', 'महाराष्ट्र पोलीस दलाचे मुख्यालय कोठे आहे?', 'पुणे', 'नागपूर', 'मुंबई', 'नाशिक', 'C', 'महाराष्ट्र राज्य पोलीस महासंचालकांचे मुख्य कार्यालय (मुख्यालय) कुलाबा, मुंबई येथे स्थित आहे.');
INSERT INTO public.questions (subject_tag, subtopic_tag, question_text, option_a, option_b, option_c, option_d, correct_option, explanation) VALUES ('node_5', 'General', 'मालिकेतील गहाळ पद शोधा: ४, ९, १६, २५, ३६, ?', '४०', '४५', '४९', '५०', 'C', 'ही अनुक्रमे २², ३², ४², ५², ६² ची वर्ग मालिका आहे. पुढील संख्या ७² = ४९ असेल.');
INSERT INTO public.questions (subject_tag, subtopic_tag, question_text, option_a, option_b, option_c, option_d, correct_option, explanation) VALUES ('node_5', 'General', '''सुसंवाद'' या शब्दाचा विरुद्धार्थी शब्द कोणता?', 'कुसंवाद', 'संवाद', 'वाद', 'संभाषण', 'A', '''सुसंवाद'' (चांगला संवाद) याचा योग्य विरुद्धार्थी शब्द ''कुसंवाद'' असा होतो.');
INSERT INTO public.questions (subject_tag, subtopic_tag, question_text, option_a, option_b, option_c, option_d, correct_option, explanation) VALUES ('node_5', 'General', 'मराठी भाषेत एकूण किती वर्ण आहेत?', '४८', '५०', '५२', '४५', 'C', 'आधुनिक सुधारित वर्णमாலानुसार (६ नोव्हेंबर २००९ च्या शासन निर्णयानुसार) मराठीत एकूण ५२ वर्ण मानले जातात.');
INSERT INTO public.questions (subject_tag, subtopic_tag, question_text, option_a, option_b, option_c, option_d, correct_option, explanation) VALUES ('node_5', 'General', '''हात टेकणे'' या वाक्प्रचाराचा योग्य अर्थ कोणता?', 'नमन करणे', 'इलाज न चालल्याने हार मानणे', 'हात जोडून उभे राहणे', 'मदत करणे', 'B', 'एखाद्या समस्येवर कोणताही उपाय न उरल्यामुळे नाईलाजाने माघार घेणे किंवा हार मानणे म्हणजे ''हात टेकणे''.');
INSERT INTO public.questions (subject_tag, subtopic_tag, question_text, option_a, option_b, option_c, option_d, correct_option, explanation) VALUES ('node_5', 'General', 'आझाद हिंद सेनेची स्थापना कोणी केली?', 'सुभाषचंद्र बोस', 'रास बिहारी बोस', 'कॅप्टन मोहन सिंग', 'लाला हरदयाळ', 'C', 'आझाद हिंद सेनेची मूळ संकल्पना आणि स्थापना कॅप्टन मोहन सिंग यांनी केली, तर नंतर तिचे नेतृत्व रास बिहारी बोस व सुभाषचंद्र बोस यांनी केले.');
